toolchain.packs.py:
"""UI Kit packs: reading, checking and turning them into game files.

A pack is a folder (anywhere; UI Kit's own are under packs/) that pack.py builds into its own VPK:

    <folder>/pack.json          id, name, version, author, widgets, stock panels to hide
    <folder>/widgets/<w>.xml    one Panorama layout per widget
    <folder>/widgets/<w>.css    its stylesheet (optional, same base name)
    <folder>/pack.css           styles shared by every widget of the pack (optional)
    <folder>/images/<n>.svg     vector images; layouts and CSS refer to them as uikit://<n>.vsvg

pack.json:

    {
      "id": "greeb_example", "name": "Example", "version": "1.0", "author": "...",
      "description": "...", "url": "...",
      "widgets": [
        {"name": "health_readout", "mount": "hud", "bind": ["health"]},
        {"name": "ult_button", "mount": "hud"}
      ],
      "hide": ["AbilitiesContainer"]
    }

The runtime finds installed packs without a file list: each pack VPK holds marker images along the
hex digits of its slot (a 16-bit hash of the id: "1", "1f", "1f2", "1f2a"), and the runtime only
looks inside branches that exist. Its files are named after its id, so two packs never overwrite
each other's files unless they share an id or a slot (1 in 65,536; pack.py refuses to install one
that would).

Where a widget is mounted decides which of the game's values it can show (see docs/engine.md):
a widget only sees the dialog variables of the panel it is mounted in and of that panel's parents.
"bind" asks the runtime to copy values from another part of the HUD onto the kit root. Widgets are
checked against that at build time, because in game a missing variable just shows nothing. Widgets
don't take mouse input unless they set "input": true, so they never block clicks on the HUD below.
"""
import json
import os
import re
import xml.etree.ElementTree as ET
import zlib

import laco
from compilers import BuildError

# Packs built by this version need a runtime at least this new (the slot tree came in 0.3.0).
PACK_FORMAT = "0.3.0"
EDITS_FORMAT = "0.4.0"   # the runtime that applies a pack's edits.json
SLOT_DIGITS = 4

# Value types, and the {x:name} formats that show them: i = whole number ({i:x} or {d:x}),
# f = decimal number ({f:x}), s = text ({s:x}).
FORMATS = {"i": "id", "f": "f", "s": "s"}
TYPE_NAMES = {"i": "a whole number", "f": "a decimal number", "s": "text"}

# Mount points and the values a widget there sees without any script. Verified in game build 6746 by
# HUD Fit's engine probe (Hero Testing) and UI Kit's data probe (bot match, 2026-10-05).
MOUNTS = {
    # anywhere on screen: a full-screen kit root inside HudCore; values set on #Hud reach it
    "hud": {"panel": None, "vars": {
        "current_ap": "i",                        # unspent ability points
        "respawn_timer": "s",                     # seconds until respawn, while dead
        "district_name": "s",                     # where the player is: "Greenwich : " (with the separator)
        "building_name": "s",                     # ...and "Campus"
        "dps": "i", "damage_meter_total": "i",    # only while the damage meter is on (sandbox)
    }},
    # inside the health component, for decorations next to the health bar: its children are clipped
    # to the component's own box
    "health": {"panel": "health_and_abilities_container", "inherits": "hud",
               "vars": {"current_health": "i", "total_health": "i", "health_regen": "f"}},
}

# Values the runtime copies onto the kit root, for widgets mounted at "hud". Only binds that a mounted
# widget uses run. source: a panel id in the HUD, or "<panel type>@<id>" for the first panel of that
# type inside it. every: copied every n-th frame (1 = every frame, for values that move smoothly).
# classes: mirrored onto the kit root, for widget CSS. fills: uikit-fill="<name>" clips that panel to
# the first value divided by the second. Decimals (f) are copied as the text the game shows, because
# script can't set a decimal (Panorama's JS has no SetDialogVariableFloat; checked in game), so
# widgets show them with {s:name}. All verified in a bot match (milestone 2).
BINDS = {
    "health": {
        "source": "health_and_abilities_container", "every": 1,
        "vars": {"current_health": "i", "total_health": "i"},
        "classes": ["localPlayerLowHealth", "localPlayerMidHealth", "damageCountersActive", "healCountersActive"],
        "fills": {"health": ["current_health", "total_health"]},
    },
    "regen": {
        "source": "health_and_abilities_container", "every": 6,
        "vars": {"health_regen": "f"},                    # health per second: {s:health_regen} shows "21.10"
    },
    "ammo": {
        "source": "Citadel_AbilityHUDElement_Gun@crosshair", "every": 1,
        "vars": {"current_clip_ammo": "i", "max_clip_ammp": "i"},   # the game's spelling: ammp
        "classes": ["reloading"],
        "fills": {"ammo": ["current_clip_ammo", "max_clip_ammp"]},
    },
    "souls": {
        "source": "gold_and_ap_container", "every": 3,
        # hud_item_gold is only kept current with infinite souls (Hero Testing), the only time the stock
        # HUD shows it; hud_death_gold_penalty is the "haunted souls" you lose if you die
        "vars": {"hud_cur_gold": "i", "hud_item_gold": "i", "hud_death_gold_penalty": "i"},
        # set for about a second when souls come in (Min / Med / Max: how many)
        "classes": ["goldIncreaseEvent_Min", "goldIncreaseEvent_Med", "goldIncreaseEvent_Max"],
    },
    "level": {
        "source": "CitadelPlayerLevel@gold_and_ap_container", "every": 6,
        "vars": {"player_level": "i"},                    # -1 before the match starts
    },
    "score": {
        "source": "TopBar", "every": 6,
        "vars": {"friendly_kills": "i", "enemy_kills": "i", "friendly_ap": "i", "enemy_ap": "i"},
    },
}

# Panel types any widget can use.
GENERIC = {"Panel", "Label", "Image", "Button", "TextButton", "ToggleButton", "RadioButton", "GlobalClassListener",
           "ProgressBar", "ProgressBarWithMiddle", "CircularProgressBar", "UICanvas"}

# The game's own HUD components a widget can contain: the game drives a copy like the stock one. From
# the data probe (bot match, game 6746, a copy compared with the stock part every 3 s for 7 minutes;
# no stock part stopped working) and milestones 1 and 2. ok: a copy shows what the stock part shows.
# size: the stock part gets that dimension (w, h) from CSS for its own id or as 100% of its parent,
# so a copy is 0 there, and invisible, unless it or a panel around it gets a size in px; the build
# warns when it can't find one. refused: doesn't work as a copy. warn: builds, with that warning.
# Other component types build with a warning.
NATIVE = {
    "CitadelHudAbilities": {"ok": True},                 # slots="signature_4": only the ultimate
    "CitadelHudHealth": {"ok": True},                    # the health bar
    "CitadelStatusEffect": {"ok": True},                 # status effects (sizes itself)
    "CitadelHudModifiers": {"ok": True, "size": "w"},    # buffs and debuffs
    "CitadelHudPlayerStats": {"ok": True, "size": "w"},
    "CitadelModsPurchasedPanel": {"ok": True},           # owned items (only seen with no items bought)
    "CitadelHudSoulAPContainer": {"ok": True, "size": "w"},
    "HudDataFeed": {"ok": True, "size": "wh"},           # kill feed; works while HUD Fit hides the stock one
    "CitadelHudTopBar": {"ok": True, "size": "h"},       # 4000 panels: a copy doubles the top bar's cost
    # sized: no layout warnings (milestone 2); 0x0: 27,000 "Invalid content height" warnings in 7 minutes
    "HudMinimap": {"ok": True, "size": "wh", "unsized": "an unsized minimap also floods the console with layout warnings"},
    "CitadelHudMovementSpeed": {"warn": "not verified: its copy never changed in the data probe (neither did the stock one)"},
    "CitadelHudPassiveAbilities": {"warn": "not verified: no items were owned in the data probe"},
    "CitadelHudAbilityResource": {"warn": "not verified: builds nothing for heroes without an ability resource"},
    "CitadelHudHealthContainer": {"refused": "its copy doesn't show what the stock one shows; use <CitadelHudHealth />"},
    "Citadel_AbilityHUDPanels": {"refused": "its copy doesn't show what the stock crosshair shows"},
    "ActiveAbilitiesMenu": {"refused": "its copy never updated in the data probe"},
}
STRUCTURE = {"root", "styles", "include", "snippets", "snippet", "scripts"}
CSS_COMMENT_RE = re.compile(r"/\*.*?\*/", re.S)
PX_RE = re.compile(r"^-?\d+(\.\d+)?px$")

ID_RE = re.compile(r"^[a-z0-9_]{1,32}$")
PANEL_ID_RE = re.compile(r"^[A-Za-z0-9_]{1,64}$")
THEME_RE = re.compile(r"^([a-z0-9_]+/)*[a-z0-9_]{1,64}$")   # theme/<layout>.css: a stylesheet for layout/<layout>.xml
DEFINE_NAME_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]{0,63}$")   # "defines": {"sans": "Jost"}: the game's @define constants
DEFINE_VALUE_RE = re.compile(r"^(?!.*/\*)[^;{}<>\r\n]{1,200}$")
# The game layouts and stylesheets whose ids and classes the theme checks know (the build and tools/themecheck.py):
# the match HUD's (survey.HUD_LAYOUT_RE), the shop's, which opens inside the HUD, and the tooltips' (drawn outside
# the HUD: their theme rules don't start with #Hud).
THEME_LAYOUT_RE = re.compile(r"^panorama/layout/(citadel_shop_[a-z_]+|citadel_ui_shop_filters|shop_ability_slot_menu|"
                             r"tooltips/[a-z_]+)\.vxml_c$")
THEME_STYLE_RE = re.compile(r"hud|abilit|shop|tooltip")
# edits.json: [{"sel": "#TopBar .SoulsValue", "props": {"font-size": "20px"}}]: inline styles on the game's panels
EDIT_COMPOUND_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)?(#[A-Za-z0-9_\-]+)?((?:\.[A-Za-z0-9_\-]+)*)(:nth-child\(\d+\))?$")
EDIT_PROP_RE = re.compile(r"^[a-z][a-z0-9\-]{0,40}$")
EDIT_VALUE_RE = re.compile(r'^[^;{}<>"\r\n]{1,200}$')
MAX_EDITS = 2000
VAR_RE = re.compile(r"\{([a-z])(?::([a-z]))?:([A-Za-z0-9_]+)\}")
IMAGE_PREFIX = "uikit://"


def read_text(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def mount_vars(mount):
    """{name: type} of the values a widget at this mount sees."""
    out, m = {}, mount
    while m:
        out.update(MOUNTS[m]["vars"])
        m = MOUNTS[m].get("inherits")
    return out


def bound_type(t):
    """How a bound value of type t reaches the kit root: whole numbers as numbers, the rest as text."""
    return "i" if t == "i" else "s"


def css_rules(text):
    """(selector, {property: value}) for each plain rule of a stylesheet, in order; @-blocks skipped."""
    text = CSS_COMMENT_RE.sub("", text)
    rules, i = [], 0
    while True:
        j = text.find("{", i)
        if j < 0:
            return rules
        depth, k = 1, j + 1
        while k < len(text) and depth:
            depth += {"{": 1, "}": -1}.get(text[k], 0)
            k += 1
        head = text[i:j].split(";")[-1].strip()      # after any @define lines
        if head and not head.startswith("@"):
            decls = style_decls(text[j + 1:k - 1])
            rules += [(sel.strip(), decls) for sel in head.split(",")]
        i = k


def style_decls(text):
    out = {}
    for d in text.split(";"):
        if ":" in d:
            prop, val = d.split(":", 1)
            out[prop.strip().lower()] = val.strip()
    return out


def selector_needs(selector):
    """What the rightmost part of a selector needs on one panel (type, .class, #id), or None when it
    depends on a state like :hover."""
    part = re.split(r"[\s>+~]+", selector.strip())[-1]
    return None if ":" in part else set(re.findall(r"[.#]?[A-Za-z_][A-Za-z0-9_-]*", part))


def size_resolves(chain, rules, prop):
    """Whether a part (chain[0]) gets a real width or height (prop): a size in px on it or on a parent,
    with only percentages in between. A parent without one fits its children, and 100% of that is 0."""
    for n, el in enumerate(chain):
        has = {el.tag, "#" + el.get("id", "")} | {"." + c for c in (el.get("class") or "").split()}
        value = None
        for sel, decls in rules:
            needs = selector_needs(sel)
            if needs and needs <= has and prop in decls:
                value = decls[prop]
        value = style_decls(el.get("style") or "").get(prop, value)
        if value is None and n == 0:
            continue                       # the part's own stylesheet: a percentage of its parent
        if value is None or not (PX_RE.match(value) or value.endswith("%")):
            return False
        if PX_RE.match(value):
            return True
    return True                            # percentages up to the full-screen kit root


def runtime_binds():
    """BINDS as the runtime reads them: vars as [name, type] pairs, in order."""
    return {name: {"source": b["source"], "every": b.get("every", 1), "vars": [[v, t] for v, t in b["vars"].items()],
                   "classes": b.get("classes", []), "fills": b.get("fills", {})} for name, b in BINDS.items()}


def slot(pack_id):
    """Where the runtime finds a pack: one of 65,536 names, taken from the pack id."""
    return "%0*x" % (SLOT_DIGITS, zlib.crc32(pack_id.encode("utf-8")) & (16 ** SLOT_DIGITS - 1))


def version_tuple(v):
    """"0.3.0" -> (0, 3, 0); anything that isn't a number counts as 0."""
    return tuple(int(x) if x.isdigit() else 0 for x in str(v).split("."))


class Widget:
    def __init__(self, pack, spec):
        self.pack = pack
        self.name = spec.get("name", "")
        self.mount = spec.get("mount", "hud")
        self.bind = list(spec.get("bind", []))
        self.input = spec.get("input", False)
        self.source_xml = os.path.join(pack.folder, "widgets", self.name + ".xml")
        self.source_css = os.path.join(pack.folder, "widgets", self.name + ".css")
        self.fills = []        # (panel id, fill name)
        self.xml = None        # compiled-ready layout text

    @property
    def res(self):
        return "panorama/layout/uikit/%s/%s" % (self.pack.id, self.name)

    @property
    def css_res(self):
        return "panorama/styles/uikit/%s/%s" % (self.pack.id, self.name)


class Pack:
    def __init__(self, folder):
        self.folder = folder
        path = os.path.join(folder, "pack.json")
        try:
            spec = json.loads(read_text(path))
        except (OSError, ValueError) as e:
            raise BuildError("%s: %s" % (path, e))
        self.id = spec.get("id", "")
        self.name = str(spec.get("name", self.id))
        self.version = str(spec.get("version", "0"))
        self.author = str(spec.get("author", ""))
        self.description = str(spec.get("description", ""))
        self.url = str(spec.get("url", ""))
        self.hide = list(spec.get("hide", []))
        self.defines = spec.get("defines", {})
        # "vars": {"accent": "#30C8FF"} or {"accent": {"value": "#30C8FF", "label": "Accent", "type": "color"}}:
        # var(--accent) in the pack's CSS becomes the value when it is built (and in the live preview)
        self.vars_spec = spec.get("vars", {})
        self.edits_path = os.path.join(folder, "edits.json")
        self.edits = []
        if os.path.isfile(self.edits_path):
            try:
                self.edits = json.loads(read_text(self.edits_path)).get("rules", [])
            except (ValueError, AttributeError) as e:
                raise BuildError("%s: edits.json can't be read: %s" % (folder, e))
        self.warnings = []
        self.widgets = [Widget(self, w) for w in spec.get("widgets", [])]
        self.pack_css = os.path.join(folder, "pack.css")
        image_dir = os.path.join(folder, "images")
        self.images = sorted(n[:-4] for n in os.listdir(image_dir) if n.endswith(".svg")) if os.path.isdir(image_dir) else []
        theme_dir = os.path.join(folder, "theme")
        self.themes = sorted(os.path.relpath(os.path.join(root, n), theme_dir)[:-4].replace(os.sep, "/")
                             for root, _, files in os.walk(theme_dir) for n in files if n.endswith(".css"))

    @property
    def slot(self):
        return slot(self.id)

    @property
    def entry_res(self):
        return "panorama/layout/uikit/packs/" + self.slot

    @property
    def markers(self):
        """The marker images along the slot's hex digits ("1", "1f", "1f2", "1f2a")."""
        return ["panorama/images/uikit/packs/" + self.slot[:n] for n in range(1, SLOT_DIGITS + 1)]

    @property
    def manifest_path(self):
        """A plain JSON file in the pack's VPK, for tools: who the pack is (the game ignores it)."""
        return "uikit/packs/%s.json" % self.id

    def manifest(self, built_with="", game_version="", patched=None):
        """patched: {game file the pack replaces: CRC32 of the game's copy it was made from}, so tools can tell
        when a game update has changed one of them and the pack needs rebuilding."""
        return {"id": self.id, "name": self.name, "version": self.version, "author": self.author,
                "description": self.description, "url": self.url, "slot": self.slot, "needs": self.needs,
                "built_with": built_with, "game_version": game_version, "widgets": [w.name for w in self.widgets],
                "theme": self.themes, "defines": dict(self.defines), "vars": dict(self.vars), "edits": len(self.edits),
                "patched": dict(patched or {})}

    @property
    def needs(self):
        """The oldest UI Kit runtime that can load this pack."""
        return EDITS_FORMAT if self.edits else PACK_FORMAT

    def theme_source(self, name):
        return os.path.join(self.folder, "theme", name + ".css")

    def theme_css_res(self, name):
        """The pack's own stylesheet that a theme file becomes (added to the game layout's stylesheets)."""
        return "panorama/styles/uikit/%s/theme_%s" % (self.id, name.replace("/", "_"))

    @property
    def pack_css_res(self):
        return "panorama/styles/uikit/%s/pack" % self.id

    def image_res(self, name):
        return "panorama/images/uikit/%s/%s" % (self.id, name)

    def where(self, what=""):
        return "pack %r%s" % (self.id or self.folder, (": " + what) if what else "")

    def warn(self, what):
        self.warnings.append(self.where(what))

    # -------------------------------------------------------------- checks

    def check(self, stock_ids=()):
        """Validate the pack and prepare each widget's layout. Raises BuildError on the first problem;
        collects warnings in self.warnings. stock_ids: panel ids of the stock HUD (hud.xml)."""
        self.stock_ids = set(stock_ids)
        if not ID_RE.match(self.id):
            raise BuildError(self.where("id must be 1-32 lowercase letters, digits or _"))
        if not self.widgets and not self.themes and not self.defines and not self.edits:
            raise BuildError(self.where("no widgets, no theme, no defines and no edits"))
        check_edits(self.edits, self.where)
        if not isinstance(self.vars_spec, dict):
            raise BuildError(self.where('vars: use {"name": "value"}, like {"accent": "#30C8FF"}'))
        for name, value in sorted(self.vars.items()):
            if not VAR_NAME_RE.match(name):
                raise BuildError(self.where("vars: %r: use lowercase letters, digits and -, starting with a letter" % name))
            if not isinstance(value, str) or not DEFINE_VALUE_RE.match(value) or "var(" in value:
                raise BuildError(self.where("vars: %s: the value must be 1-200 characters without ; { } < >, line breaks "
                                            "or var()" % name))
        if not isinstance(self.defines, dict):
            raise BuildError(self.where('defines: use {"name": "value"}, like {"sans": "Jost"}'))
        for name, value in sorted(self.defines.items()):
            if not DEFINE_NAME_RE.match(name):
                raise BuildError(self.where("defines: %r is not a constant name" % name))
            if not isinstance(value, str) or not DEFINE_VALUE_RE.match(value):
                raise BuildError(self.where("defines: %s: the value must be 1-200 characters without ; { } < > "
                                            "or line breaks" % name))
        for name in self.themes:
            if not THEME_RE.match(name):
                raise BuildError(self.where("theme/%s.css: name it after the game layout it restyles, "
                                            "like theme/hud.css for layout/hud.xml" % name))
        names = set()
        for w in self.widgets:
            if not ID_RE.match(w.name):
                raise BuildError(self.where("widget name %r: use lowercase letters, digits and _" % w.name))
            if w.name in names:
                raise BuildError(self.where("two widgets are called %r" % w.name))
            names.add(w.name)
            if w.mount not in MOUNTS:
                raise BuildError(self.where("widget %r: unknown mount %r (use %s)" % (w.name, w.mount, ", ".join(sorted(MOUNTS)))))
            for b in w.bind:
                if b not in BINDS:
                    raise BuildError(self.where("widget %r: unknown bind %r (use %s)" % (w.name, b, ", ".join(sorted(BINDS)))))
            if w.bind and w.mount != "hud":
                raise BuildError(self.where("widget %r: bind only works for widgets mounted at hud" % w.name))
            if not isinstance(w.input, bool):
                raise BuildError(self.where("widget %r: input must be true or false" % w.name))
            self._prepare(w)
        for panel in self.hide:
            if not PANEL_ID_RE.match(str(panel)):
                raise BuildError(self.where("hide: %r is not a panel id" % panel))
            if self.stock_ids and panel not in self.stock_ids:
                self.warn("hide: the stock hud.xml has no #%s (it may be inside a component; check the log in game)" % panel)
        for name in self.images:
            if not ID_RE.match(name):
                raise BuildError(self.where("image %r.svg: use lowercase letters, digits and _" % name))
        return self

    def _prepare(self, w):
        if not os.path.isfile(w.source_xml):
            raise BuildError(self.where("widget %r: %s is missing" % (w.name, os.path.relpath(w.source_xml))))
        text = read_text(w.source_xml)
        try:
            tree = ET.fromstring(text)
        except ET.ParseError as e:
            raise BuildError(self.where("widget %r: %s" % (w.name, e)))
        if tree.tag != "root":
            raise BuildError(self.where("widget %r: the layout must start with <root>" % w.name))
        if tree.find("scripts") is not None:
            raise BuildError(self.where("widget %r: packs can't contain scripts; use binds and classes" % w.name))
        panels = [c for c in tree if c.tag not in ("styles", "snippets")]
        if len(panels) != 1:
            raise BuildError(self.where("widget %r: the layout needs exactly one top panel" % w.name))

        allowed = mount_vars(w.mount)
        fills, as_text = {}, set()
        for b in w.bind:
            for var, t in BINDS[b]["vars"].items():
                allowed[var] = bound_type(t)
                if t == "f":
                    as_text.add(var)
            fills.update(BINDS[b].get("fills", {}))
        for fmt, mod, var in VAR_RE.findall(text):
            if var not in allowed:
                hint = [name for name, spec in sorted(BINDS.items()) if var in spec["vars"]]
                raise BuildError(self.where(
                    "widget %r uses {%s:%s} but a widget mounted at %s%s only gets: %s%s" %
                    (w.name, fmt, var, w.mount, " with bind %s" % "+".join(w.bind) if w.bind else "",
                     ", ".join(sorted(allowed)),
                     ("; add \"bind\": [\"%s\"] to the widget" % hint[0]) if hint and w.mount == "hud" else "")))
            if fmt not in FORMATS[allowed[var]] and var in as_text:
                raise BuildError(self.where("widget %r: the %s bind copies %s as text (script can't set decimals), "
                                            "so write {s:%s} instead of {%s:...}" %
                                            (w.name, next(b for b in w.bind if var in BINDS[b]["vars"]), var, var, fmt)))
            if fmt not in FORMATS[allowed[var]]:
                raise BuildError(self.where("widget %r: %s is %s, so write {%s:%s} instead of {%s:...}" %
                                            (w.name, var, TYPE_NAMES[allowed[var]], FORMATS[allowed[var]][0], var, fmt)))
        parents = {c: p for p in tree.iter() for c in p}
        for el in tree.iter():
            if el.tag in STRUCTURE:
                continue
            if el.get("id") in self.stock_ids:
                raise BuildError(self.where("widget %r: id %r belongs to a stock HUD panel; the game and UI Kit find "
                                            "panels by id, so use another one" % (w.name, el.get("id"))))
            if el.tag in GENERIC:
                continue
            info = NATIVE.get(el.tag)
            if info is None:
                self.warn("widget %r uses <%s>, which UI Kit hasn't tested as a copy: it may stay empty or not update "
                          "(the data probe can check it)" % (w.name, el.tag))
            elif "refused" in info:
                raise BuildError(self.where("widget %r: <%s> can't be used: %s" % (w.name, el.tag, info["refused"])))
            elif "warn" in info:
                self.warn("widget %r: <%s>: %s" % (w.name, el.tag, info["warn"]))
            if info and info.get("size"):
                self._check_size(w, el, parents, info)
        for el in tree.iter():
            fill = el.get("uikit-fill")
            if fill is None:
                continue
            if fill not in fills:
                raise BuildError(self.where("widget %r: uikit-fill=%r needs a bind that provides it (%s)" %
                                            (w.name, fill, ", ".join(sorted(fills)) or "none bound")))
            if not el.get("id"):
                raise BuildError(self.where("widget %r: the uikit-fill panel needs an id" % w.name))
            w.fills.append((el.get("id"), fill))
        for ref in re.findall(re.escape(IMAGE_PREFIX) + r"([A-Za-z0-9_]+)\.vsvg", text):
            if ref not in self.images:
                raise BuildError(self.where("widget %r refers to %s%s.vsvg but images/%s.svg is missing" %
                                            (w.name, IMAGE_PREFIX, ref, ref)))
        w.xml = self.layout_text(w, text)
        try:
            laco.from_xml(w.xml)
        except Exception as e:  # expat or layout errors, with the file named
            raise BuildError(self.where("widget %r: %s" % (w.name, e)))

    def _check_size(self, w, el, parents, info):
        """Warn when a game part that needs a size can't get one from the widget's CSS."""
        rules = []
        for path in (self.pack_css, w.source_css):
            if os.path.isfile(path):
                rules += css_rules(read_text(path))
        chain = [el]
        while chain[-1] in parents and parents[chain[-1]].tag != "root":
            chain.append(parents[chain[-1]])
        missing = [name for dim, name in (("w", "width"), ("h", "height"))
                   if dim in info["size"] and not size_resolves(chain, rules, name)]
        if missing:
            self.warn("widget %r: <%s> gets no fixed %s, so it will be invisible: give it, or a panel around it, "
                      "a size in px in the widget's CSS (percentages only work inside a sized panel)%s" %
                      (w.name, el.tag, " or ".join(missing), "; " + info["unsized"] if "unsized" in info else ""))

    # -------------------------------------------------------------- generated text

    @property
    def vars(self):
        """{name: value} of the pack's "vars"."""
        out = {}
        for name, v in (self.vars_spec or {}).items() if isinstance(self.vars_spec, dict) else []:
            out[name] = v.get("value") if isinstance(v, dict) else v
        return out

    def apply_vars(self, text, where=""):
        """The CSS with each var(--name) replaced by the pack's value for it."""
        return apply_vars(text, self.vars, lambda m: self.where("%s: %s" % (where, m) if where else m))

    def resolve_images(self, text):
        return text.replace(IMAGE_PREFIX, "s2r://panorama/images/uikit/%s/" % self.id)

    def stylesheets(self, w):
        out = []
        if os.path.isfile(self.pack_css):
            out.append(self.pack_css_res)
        if os.path.isfile(w.source_css):
            out.append(w.css_res)
        return out

    def layout_text(self, w, text):
        """The widget's layout with its stylesheets included and image references resolved."""
        includes = "".join('\n\t\t<include src="s2r://%s.vcss" />' % res for res in self.stylesheets(w))
        if includes:
            if re.search(r"<styles\s*>", text):
                text = re.sub(r"<styles\s*>", lambda m: m.group(0) + includes, text, count=1)
            else:
                text = re.sub(r"<root\s*>", lambda m: m.group(0) + "\n\t<styles>" + includes + "\n\t</styles>", text, count=1)
        return self.resolve_images(text)

    def references(self, w):
        """Resources a widget layout refers to, for its resource metadata."""
        refs = [res + ".vcss" for res in self.stylesheets(w)]
        refs += [self.image_res(n) + ".vsvg" for n in re.findall(r"panorama/images/uikit/%s/([A-Za-z0-9_]+)\.vsvg" % self.id, w.xml)]
        return sorted(set(refs))

    def entry_layout(self):
        """The layout the runtime finds through the pack's slot: who the pack is and what to mount."""
        def attr(v):
            return v.replace("&", "&amp;").replace('"', "&quot;").replace("<", "&lt;")
        edits = ' uikit-edits="%s"' % attr(json.dumps({"rules": self.edits}, separators=(",", ":"))) if self.edits else ""
        lines = ['<root>',
                 '\t<Panel hittest="false" uikit-pack="%s" uikit-name="%s" uikit-version="%s" uikit-author="%s" '
                 'uikit-needs="%s" uikit-hide="%s"%s>' %
                 (self.id, attr(self.name), attr(self.version), attr(self.author), self.needs, " ".join(self.hide), edits)]
        for w in self.widgets:
            lines.append('\t\t<Panel uikit-widget="%s" uikit-mount="%s" uikit-layout="file://{resources}/layout/uikit/%s/%s.xml"'
                         ' uikit-bind="%s" uikit-fills="%s"%s />' %
                         (w.name, w.mount, self.id, w.name, " ".join(w.bind),
                          " ".join("%s:%s" % f for f in w.fills), ' uikit-input="1"' if w.input else ""))
        lines += ['\t</Panel>', '</root>', '']
        return "\n".join(lines)


def check_edits(rules, where=lambda m: m):
    """Raise BuildError for the first edit the runtime couldn't apply as written."""
    if not isinstance(rules, list):
        raise BuildError(where('edits.json: "rules" must be a list'))
    if len(rules) > MAX_EDITS:
        raise BuildError(where("edits.json: %d rules, at most %d" % (len(rules), MAX_EDITS)))
    for n, rule in enumerate(rules, 1):
        if not isinstance(rule, dict) or not isinstance(rule.get("sel"), str) or not isinstance(rule.get("props"), dict):
            raise BuildError(where('edits.json rule %d: use {"sel": "...", "props": {"property": "value"}}' % n))
        tokens = rule["sel"].replace(">", " > ").split()
        if not tokens or tokens[0] == ">" or tokens[-1] == ">" or any(
                t != ">" and not (EDIT_COMPOUND_RE.match(t) and t.strip(":")) for t in tokens) or ">\x00>" in "\x00".join(tokens):
            raise BuildError(where("edits.json rule %d: can't read the selector %r (types, #ids, .classes, "
                                   ":nth-child(n), spaces and >)" % (n, rule["sel"])))
        for prop, value in rule["props"].items():
            if not EDIT_PROP_RE.match(str(prop)):
                raise BuildError(where("edits.json rule %d: %r is not a CSS property name" % (n, prop)))
            if not isinstance(value, str) or not EDIT_VALUE_RE.match(value):
                raise BuildError(where('edits.json rule %d: %s: the value must be 1-200 characters without ; { } < > " '
                                       "or line breaks" % (n, prop)))


VAR_NAME_RE = re.compile(r"^[a-z][a-z0-9-]{0,40}$")
VAR_USE_RE = re.compile(r"var\(\s*--([A-Za-z0-9_-]+)\s*\)")


def apply_vars(text, values, where=lambda m: m):
    """CSS with each var(--name) replaced by values[name]; an unknown name is an error (named by where())."""
    def one(m):
        if m.group(1) not in values:
            raise BuildError(where("var(--%s) isn't one of the pack's vars (%s)" % (m.group(1), ", ".join(sorted(values)) or
                                                                                  'none: add "vars" to pack.json')))
        return values[m.group(1)]
    return VAR_USE_RE.sub(one, text)


def theme_res(name):
    """The game layout a theme file restyles: theme/<name>.css -> panorama/layout/<name>.vxml_c."""
    return "panorama/layout/" + name


def selector_targets(text):
    """The ids a stylesheet's rules style directly: the ones in the last part of each selector
    (`#Hud #TopBar .Clock` styles .Clock, `#Hud #TopBar` styles #TopBar)."""
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
    out, sel = set(), ""
    for ch in text:
        if ch == "{":
            if not sel.strip().startswith("@") and not re.match(r"^\s*(from|to|[\d.]+%)\s*$", sel):
                for part in sel.split(","):
                    last = re.split(r"[\s>+~]+", part.strip())[-1] if part.strip() else ""
                    out |= set(re.findall(r"#([A-Za-z_][A-Za-z0-9_-]*)", last))
            sel = ""
        elif ch == "}":
            sel = ""
        else:
            sel = "" if ch == ";" else sel + ch
    return out


def selector_names(text):
    """The ids and classes a stylesheet's selectors name: ({ids}, {classes})."""
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
    ids, classes, depth, sel = set(), set(), 0, ""
    for ch in text:
        if ch == "{":
            if not sel.strip().startswith("@") and not re.match(r"^\s*(from|to|[\d.]+%)\s*$", sel):
                ids |= set(re.findall(r"#([A-Za-z_][A-Za-z0-9_-]*)", sel))
                classes |= set(re.findall(r"\.([A-Za-z_][A-Za-z0-9_-]*)", sel))
            depth += 1
            sel = ""
        elif ch == "}":
            depth = max(0, depth - 1)
            sel = ""
        else:
            sel = "" if ch == ";" else sel + ch
    return ids, classes


def load_pack(folder, stock_ids=()):
    """The pack in a folder, checked against the stock HUD's ids."""
    if not os.path.isfile(os.path.join(folder, "pack.json")):
        raise BuildError("%s has no pack.json" % folder)
    return Pack(folder).check(stock_ids)


def load_packs(packs_dir, only=None, stock_ids=()):
    """Every pack in the folders under packs_dir (or the ones whose id is in `only`), checked."""
    if not os.path.isdir(packs_dir):
        return []
    names = sorted(n for n in os.listdir(packs_dir) if os.path.isfile(os.path.join(packs_dir, n, "pack.json")))
    packs = [load_pack(os.path.join(packs_dir, n), stock_ids) for n in names]
    if only:
        missing = [n for n in only if n not in [p.id for p in packs]]
        if missing:
            raise BuildError("no such pack: " + ", ".join(missing))
        packs = [p for p in packs if p.id in only]
    seen = {}
    for p in packs:
        if p.slot in seen:
            raise BuildError("packs %r and %r share slot %s; rename one of them" % (seen[p.slot], p.id, p.slot))
        seen[p.slot] = p.id
    return packs


MARKER_SVG = ('<svg xmlns="http://www.w3.org/2000/svg" width="4" height="4" viewBox="0 0 4 4">'
              '<rect width="4" height="4" fill="#000000" fill-opacity="0"/></svg>\n')

toolchain.addons.py:
"""Deadlock's addons folder: which pakNN_dir.vpk files it has, what they hold, and installing or removing
UI Kit's runtime and packs there.

The game loads pak01_dir.vpk, pak02_dir.vpk, ... and stops at the first missing number, so a file
removed from the middle would switch off every addon after it. UI Kit leaves a small placeholder VPK
in that case, and reuses placeholders before taking a new number.
"""
import json
import os
import re
import shutil
import tempfile

import resource
import vpk
from compilers import BuildError

PAK_RE = re.compile(r"^pak(\d\d)_dir\.vpk$")
RUNTIME_MARKER = "panorama/scripts/uikit.vjs_c"
PROBE_MARKER = "panorama/scripts/uikit_probe.vjs_c"
DEV_MARKERS = [("panorama/scripts/uikit_probe.vjs_c", "probe"), ("panorama/scripts/uikit_survey.vjs_c", "survey"),
               ("panorama/scripts/uikit_autopilot.vjs_c", "autopilot")]
PLACEHOLDER = "uikit/placeholder.txt"
MANIFEST_RE = re.compile(r"^uikit/packs/([a-z0-9_]{1,32})\.json$")


def addons_dir(game_dir):
    """game/citadel/addons, after checking the game is set up to load addons."""
    citadel = os.path.join(game_dir, "game", "citadel")
    with open(os.path.join(citadel, "gameinfo.gi"), encoding="utf-8", errors="replace") as f:
        if "citadel/addons" not in f.read():
            raise BuildError("gameinfo.gi does not load citadel/addons yet, so the game ignores addon files.\n"
                             "Enable mods first (Deadlock Mod Manager does this for you), then run this again.")
    addons = os.path.join(citadel, "addons")
    os.makedirs(addons, exist_ok=True)
    return addons


def paks(addons):
    """{number: filename} for every pakNN_dir.vpk in the addons folder."""
    out = {}
    for name in os.listdir(addons):
        m = PAK_RE.match(name)
        if m:
            out[int(m.group(1))] = name
    return out


def loaded_numbers(numbers):
    """The game mounts pak01, pak02, ... and stops at the first missing number."""
    n = 1
    while n in numbers:
        n += 1
    return set(range(1, n))


class Pak:
    """One pakNN_dir.vpk and what UI Kit can tell about it."""
    def __init__(self, addons, number, name):
        self.number, self.name, self.path = number, name, os.path.join(addons, name)
        self.entries, self.base, self.manifest, self.runtime_version = {}, 0, None, None
        try:
            self.entries, self.base = vpk.read_index(self.path)
        except (OSError, ValueError):
            self.entries = None
            return
        for rel in self.entries:
            if MANIFEST_RE.match(rel):
                try:
                    self.manifest = json.loads(self.read(rel).decode("utf-8"))
                except (OSError, ValueError):
                    self.manifest = {"id": MANIFEST_RE.match(rel).group(1)}
        if RUNTIME_MARKER in self.entries:
            try:
                m = re.search(rb'var VERSION = "([^"]+)"', resource.get_block(self.read(RUNTIME_MARKER), b"DATA"))
                self.runtime_version = m.group(1).decode() if m else "?"
            except Exception:  # an unreadable script still counts as UI Kit
                self.runtime_version = "?"

    def read(self, rel):
        return vpk.read_file(self.path, self.entries[rel], self.base)

    @property
    def is_runtime(self):
        return bool(self.entries) and RUNTIME_MARKER in self.entries

    @property
    def is_placeholder(self):
        return bool(self.entries) and list(self.entries) == [PLACEHOLDER]

    @property
    def pack_id(self):
        return self.manifest.get("id") if self.manifest else None

    def kind(self):
        if self.entries is None:
            return "unreadable"
        if self.is_runtime:
            bundled = sorted({k.split("/")[3] for k in self.entries if k.startswith("panorama/layout/uikit/") and
                              k.count("/") == 4 and not k.startswith("panorama/layout/uikit/packs/")})
            return "UI Kit %s%s%s" % (self.runtime_version, " with " + ", ".join(bundled) if bundled else "",
                                      "".join(" + " + name for res, name in DEV_MARKERS if res in self.entries))
        if self.manifest:
            return "UI Kit pack %s %s" % (self.pack_id, self.manifest.get("version", "?"))
        if self.is_placeholder:
            return "empty (keeps the numbers after it)"
        if "panorama/scripts/hud_fit.vjs_c" in self.entries:
            return "HUD Fit + probe" if "panorama/scripts/hud_fit_probe.vjs_c" in self.entries else "HUD Fit"
        if "panorama/scripts/hero_select_plus.vjs_c" in self.entries:
            return "Hero Select Plus"
        if "aspect_4x3_mod.txt" in self.entries:
            return "4:3 Video"
        return "%d files" % len(self.entries)


def scan(addons):
    """[Pak] in number order."""
    return [Pak(addons, n, name) for n, name in sorted(paks(addons).items())]


def describe(addons):
    """One line per addon file: number, what it is, and whether the game loads it."""
    found = scan(addons)
    live = loaded_numbers({p.number for p in found})
    return ["  %s  %-36s %s" % (p.name, p.kind(), "loads" if p.number in live else "NOT loaded (gap before it)")
            for p in found]


def shadowed(addons):
    """Files that more than one addon has: the game takes each from the lowest-numbered pak, so the others'
    copies don't show. {pak name: [(file, the pak that wins)]} for every pak that loses some file."""
    found = [p for p in scan(addons) if p.entries]
    out = {}
    for i, pak in enumerate(found):
        for rel in sorted(pak.entries):
            first = next((q for q in found[:i] if rel in q.entries), None)
            if first and rel != PLACEHOLDER and not rel.startswith(("uikit/", "panorama/images/uikit/packs/")):
                out.setdefault(pak.name, []).append((rel, first))
    return out


def shadow_lines(addons, only=None):
    """Warnings about addon files that another addon's copy hides (only: pak names to report on)."""
    lines = []
    for name, files in sorted(shadowed(addons).items()):
        if only is not None and name not in only:
            continue
        for rel, first in files[:12]:
            lines.append("warning: %s's %s doesn't show: %s (%s) has the same file and loads first"
                         % (name, rel, first.name, first.kind()))
        if len(files) > 12:
            lines.append("warning: ...and %d more files of %s" % (len(files) - 12, name))
    return lines


def runtime(addons):
    return next((p for p in scan(addons) if p.is_runtime), None)


def installed_packs(addons):
    """{pack id: Pak} for the UI Kit packs installed as their own VPKs."""
    return {p.pack_id: p for p in scan(addons) if p.pack_id}


def free_number(addons):
    """A placeholder to reuse, or else the first missing number."""
    found = scan(addons)
    for p in found:
        if p.is_placeholder:
            return p.number
    numbers = {p.number for p in found}
    n = 1
    while n in numbers:
        n += 1
    if n > 99:
        raise BuildError("no free pakNN number left in the addons folder")
    return n


def install(addons, src, number):
    """Copy a built VPK into the addons folder as pakNN; returns the file name."""
    name = "pak%02d_dir.vpk" % number
    shutil.copyfile(src, os.path.join(addons, name))
    return name


def remove(addons, number):
    """Remove pakNN. In the middle of the numbers it becomes a placeholder, so the files after it still
    load; at the end it goes, with any placeholders right before it."""
    numbers = paks(addons)
    if number != max(numbers):
        write_placeholder(os.path.join(addons, numbers[number]))
        return "replaced %s with an empty placeholder, so the addons after it still load" % numbers[number]
    os.remove(os.path.join(addons, numbers[number]))
    removed = [numbers[number]]
    while True:
        numbers = paks(addons)
        if not numbers:
            break
        last = Pak(addons, max(numbers), numbers[max(numbers)])
        if not last.is_placeholder:
            break
        os.remove(last.path)
        removed.append(last.name)
    return "removed " + ", ".join(removed)


def write_placeholder(path):
    stage = tempfile.mkdtemp(prefix="uikit_placeholder_")
    try:
        os.makedirs(os.path.join(stage, "uikit"))
        with open(os.path.join(stage, PLACEHOLDER), "w", encoding="utf-8") as f:
            f.write("Empty on purpose: the game stops loading addons at the first missing pakNN number, so this\n"
                    "keeps the ones after it loading. UI Kit's installers reuse it.\n")
        vpk.pack(stage, path)
    finally:
        shutil.rmtree(stage, ignore_errors=True)

toolchain.game.py:
"""The installed Deadlock game: where it is and how to read its packed files.

UI Kit reads game files from citadel's pak01 first and the engine's core pak01 second, the same
order the game uses (the hook layout, hud_perfstats_basics, lives in core).
"""
import os

import kv3
import laco
import resource
import vpk
from compilers import BuildError

GAME_CANDIDATES = [
    "/mnt/c/Program Files (x86)/Steam/steamapps/common/Deadlock",
    "C:/Program Files (x86)/Steam/steamapps/common/Deadlock",
    os.path.expanduser("~/.steam/steam/steamapps/common/Deadlock"),
    os.path.expanduser("~/.local/share/Steam/steamapps/common/Deadlock"),
]


def find_game(arg=None):
    for c in ([arg] if arg else []) + [os.environ.get("DEADLOCK_DIR")] + GAME_CANDIDATES:
        if c and os.path.isfile(os.path.join(c, "game", "citadel", "pak01_dir.vpk")):
            return c
    raise BuildError("Deadlock install not found. Pass --game <path to the Deadlock folder>.")


class Game:
    def __init__(self, root):
        self.root = root
        self.citadel = os.path.join(root, "game", "citadel")
        self.paks = []
        for folder in ("citadel", "core"):
            path = os.path.join(root, "game", folder, "pak01_dir.vpk")
            if os.path.isfile(path):
                entries, base = vpk.read_index(path)
                self.paks.append((path, entries, base))

    def names(self, prefix=""):
        """Every file in the paks whose path starts with prefix."""
        return sorted({e for _, entries, _ in self.paks for e in entries if e.startswith(prefix)})

    def has(self, path):
        return any(path in entries for _, entries, _ in self.paks)

    def read(self, path):
        for pak, entries, base in self.paks:
            if path in entries:
                return vpk.read_file(pak, entries[path], base)
        raise BuildError("game file missing from pak01 (citadel and core): " + path)

    def layout(self, path):
        return laco.to_xml(kv3.loads(resource.get_block(self.read(path), b"LaCo")))

    def version(self):
        try:
            text = open(os.path.join(self.citadel, "steam.inf"), encoding="utf-8", errors="replace").read()
            return dict(l.strip().split("=", 1) for l in text.splitlines() if "=" in l).get("ClientVersion", "?")
        except OSError:
            return "?"

toolchain.survey.py:
"""The data survey (development only): what the always-on-screen parts of the stock HUD show, and
where the game puts it, so packs can show the same.

The build reads the game's own HUD layouts and stylesheets and lists what to look for; the survey
script (probe/survey.js) finds it in the live HUD during a match:

- values: every {x:name} a HUD label shows. In game, the survey finds such a label and walks up to
  the panel the value is set on, then samples it there (and on every copy of that panel, like the
  12 player slots of the top bar).
- labels the game fills in directly (a Label without text in its layout): their text.
- bars (ProgressBar, CircularProgressBar, ProgressBarWithMiddle): their values.
- state classes: classes the stylesheets style on that no layout gives a panel, so the game adds
  them. Each part is checked for the classes of its own stylesheets.
"""
import re
import xml.etree.ElementTree as ET

from compilers import BuildError

# HUD layouts: the match HUD and the parts it is made of (not the shop, menus or post-game screens)
HUD_LAYOUT_RE = re.compile(r"^panorama/layout/(hud[^/]*|citadel_hud[^/]*|ability_hud_elements/[^/]*|citadel_status_effect|"
                           r"citadel_mods_purchased_panel|citadel_shop_mod_icon|objectives_map)\.vxml_c$")
SKIP_RE = re.compile(r"(shop(?!_mod_icon)|escape_menu|hero_testing|hideout|chat|hero_builds|report_?card|match_end|"
                     r"sandbox_tutorial|combat_log|replay|personal_best|play_?of_?the_?game|damage_report|quickbuy|"
                     r"pregame|match_start|subtitles|paused|commend|join_team|perfstats)")
VAR_RE = re.compile(r"\{([a-z])(?::(r))?:([A-Za-z0-9_]+)\}")
BAR_TYPES = ("ProgressBar", "CircularProgressBar", "ProgressBarWithMiddle")
STRUCTURE = {"root", "styles", "include", "scripts", "snippets", "snippet"}
SHARED_SHEET_USES = 10  # a stylesheet included by this many HUD layouts holds common styles, not one part's states


def part_type(path, top):
    """The panel type a layout belongs to: its top panel's, or for a plain Panel at the top (a layout the
    game loads into its own panel) the type its file name gives: hud_abilities -> CitadelHudAbilities."""
    if top != "Panel":
        return top
    name = path.rsplit("/", 1)[1][:-len(".vxml_c")]
    for prefix in ("citadel_hud_", "hud_"):
        if name.startswith(prefix):
            return "CitadelHud" + "".join(w[:1].upper() + w[1:] for w in name[len(prefix):].split("_"))
    return None


def anchor(el):
    """How the survey finds this panel in the live HUD: "#id", or ".class" (its first class)."""
    if el.get("id"):
        return "#" + el.get("id")
    classes = (el.get("class") or "").split()
    return "." + classes[0] if classes else None


def css_classes(text):
    """Every class a stylesheet's selectors name (keyframes and comments aside)."""
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
    out, depth, sel = set(), 0, ""
    for ch in text:
        if ch == "{":
            if depth == 0:
                out |= set(re.findall(r"\.([A-Za-z_][A-Za-z0-9_-]*)", sel)) if not sel.strip().startswith("@") else set()
            depth += 1
            sel = ""
        elif ch == "}":
            depth = max(0, depth - 1)
            sel = ""
        elif depth == 0:
            sel = "" if ch == ";" else sel + ch
    return out


def stylesheet_text(game, res):
    """A compiled stylesheet's CSS text (after its 6-byte header), or "" if it can't be read."""
    import resource
    try:
        return resource.get_block(game.read(res), b"DATA")[6:].decode("utf-8", "replace")
    except Exception:  # a missing or unreadable stylesheet only means fewer classes to look for
        return ""


def spec(game):
    """What the survey looks for, from the game's HUD layouts (game: names(prefix), layout(path), read(path))."""
    values, labels, bars = [], [], []
    seen_values, seen_labels, seen_bars = set(), set(), set()
    static, sheets_by_type, layouts, uses = set(), {}, 0, {}
    for path in game.names("panorama/layout/"):
        if not HUD_LAYOUT_RE.match(path) or SKIP_RE.search(path):
            continue
        try:
            tree = ET.fromstring(game.layout(path))
        except (BuildError, ET.ParseError):
            continue
        tops = [c for c in tree if c.tag not in STRUCTURE]
        if not tops:
            continue
        layouts += 1
        part = part_type(path, tops[0].tag) or tops[0].tag
        for inc in tree.iter("include"):
            src = inc.get("src", "")
            if src.startswith("s2r://") and src.endswith(".vcss"):
                sheets_by_type.setdefault(part, set()).add(src[len("s2r://"):] + "_c")
                uses[src] = uses.get(src, 0) + 1
        for el in tree.iter():
            if el.tag in STRUCTURE:
                continue
            static |= set((el.get("class") or "").split())
            where = anchor(el)
            text = el.get("text")
            if el.tag == "Label" and where:
                if text and VAR_RE.search(text):
                    for fmt, raw, name in VAR_RE.findall(text):
                        key = (name, where)
                        if key not in seen_values:
                            seen_values.add(key)
                            values.append({"v": name, "f": fmt + (":r" if raw else ""), "a": where, "p": part})
                elif not text and (where, part) not in seen_labels:
                    seen_labels.add((where, part))
                    labels.append({"a": where, "p": part})
            elif el.tag in BAR_TYPES and where and (where, part) not in seen_bars:
                seen_bars.add((where, part))
                bars.append({"a": where, "k": el.tag, "p": part})
    shared = {"s2r://" + s[:-2] for s in set().union(*sheets_by_type.values())} if sheets_by_type else set()
    shared = {s for s in shared if uses.get(s, 0) >= SHARED_SHEET_USES}
    classes = {}
    for part, sheets in sorted(sheets_by_type.items()):
        if part == "Panel":
            continue                      # a plain panel at the top of a layout says nothing about its part
        found = set()
        for res in sorted(sheets):
            if "s2r://" + res[:-2] not in shared or part == "CitadelHud":
                found |= css_classes(stylesheet_text(game, res))
        state = sorted(found - static)
        if state:
            classes[part] = state
    return {"values": values, "labels": labels, "bars": bars, "classes": classes,
            "layouts": layouts, "class_count": sum(len(c) for c in classes.values())}

