// UI Kit runtime: mounts the installed packs' widgets into the HUD and keeps their data current.
//
// Loaded by the hook layout (hud_perfstats_basics inside the HUD, or base_hud). Widgets are compiled
// Panorama layouts: the game's C++ updates what they show through dialog variables and classes, the
// same way it drives the stock HUD. The only per-frame work here is the bridge: values a widget asked
// for with "bind" are copied from their component onto the kit root on CitadelHudUpdate, written only
// when they change (game 6746: one update with health bound took 2 us, 0.1-0.4 ms of script a second).
(function () {
    "use strict";

    var VERSION = "0.4.0";
    var TAG = "[UIKit] ";
    var DEBUG = /*__UK_DEBUG__*/true/*__END__*/;
    // filled by build.py from packs.py: mount -> panel id (null = the kit root), what binds copy, and
    // the native component types that are invisible at 0x0 (checked in debug builds)
    var MOUNTS = /*__UK_MOUNTS__*/{ "hud": null, "health": "health_and_abilities_container" }/*__END__*/;
    var BINDS = /*__UK_BINDS__*/{}/*__END__*/;
    var SIZED = /*__UK_SIZED__*/[]/*__END__*/;
    var ROOT_LAYOUT = "file://{resources}/layout/uikit/root.xml";
    var SLOT_DIGITS = 4;   // a pack's slot: 4 hex digits from its id
    var HEX = "0123456789abcdef";
    var RETRY_MS = 2000;   // a missing panel is looked up again at most this often

    var ctx = $.GetContextPanel();
    var hud = null, core = null, kitRoot = null;
    var packs = [];        // { slot, id, name, version, hide: [], widgets: [] }
    var hidden = [];       // { id, panel }
    var sources = {};      // bind -> { panel, at }
    var bridge = { handler: null, binds: [], last: {}, ticks: 0, writes: 0, since: Date.now(), failed: false };
    var started = false;
    var seen = {};         // debug: kit root classes already reported
    var sizesChecked = false;

    function log(msg) { $.Msg(TAG + msg); }
    function dbg(msg) { if (DEBUG) $.Msg(TAG + msg); }
    function alive(p) { return !!p && typeof p.IsValid === "function" && p.IsValid(); }
    function words(s) { return String(s || "").split(" ").filter(function (x) { return x; }); }
    var now = (typeof performance !== "undefined" && performance && typeof performance.now === "function")
        ? function () { return performance.now(); } : function () { return Date.now(); };

    function findHud() {
        var p = ctx;
        for (var i = 0; i < 64 && alive(p); i++) {
            if (p.id === "Hud") return p;
            p = p.GetParent();
        }
        return alive(ctx) ? ctx.FindChildTraverse("Hud") : null;   // hooked into base_hud
    }

    // ------------------------------------------------------------------ packs

    // Packs are found without a file list. Each pack VPK has marker images along the hex digits of its
    // slot ("1", "1f", "1f2", "1f2a"), so the runtime only looks inside branches that exist: 16 checks,
    // plus 48 per pack at most (game 6746: about 35 us per check).
    function discover() {
        var t0 = now(), found = [], checks = 0;
        packs = [];
        if (typeof $.BImageFileExists !== "function") { log("$.BImageFileExists is missing: can't look for packs"); return; }
        (function walk(prefix) {
            for (var i = 0; i < 16; i++) {
                var s = prefix + HEX[i];
                checks++;
                if (!$.BImageFileExists("file://{images}/uikit/packs/" + s + ".vsvg")) continue;
                if (s.length === SLOT_DIGITS) found.push(s);
                else walk(s);
            }
        })("");
        dbg("packs at " + (found.join(" ") || "no slot") + " (" + checks + " checks in " + Math.round(now() - t0) + " ms)");
        found.forEach(loadPack);
    }

    // "0.3.0" is newer than "0.2.10"
    function newer(a, b) {
        var x = String(a).split("."), y = String(b).split(".");
        for (var i = 0; i < Math.max(x.length, y.length); i++) {
            var p = parseInt(x[i] || "0", 10) || 0, q = parseInt(y[i] || "0", 10) || 0;
            if (p !== q) return p > q;
        }
        return false;
    }

    // The pack's entry layout only carries declarations, as attributes the build wrote.
    function loadPack(slot) {
        var holder = $.CreatePanel("Panel", kitRoot, "UIKitPack_" + slot);
        holder.visible = false;
        if (!holder.BLoadLayout("file://{resources}/layout/uikit/packs/" + slot + ".xml", false, false)) {
            log("slot " + slot + " has a marker but no pack layout");
            holder.DeleteAsync(0);
            return;
        }
        var pack = {
            slot: slot,
            id: holder.GetAttributeString("uikit-pack", slot),
            name: holder.GetAttributeString("uikit-name", ""),
            version: holder.GetAttributeString("uikit-version", "?"),
            author: holder.GetAttributeString("uikit-author", ""),
            hide: words(holder.GetAttributeString("uikit-hide", "")),
            edits: [],
            widgets: []
        };
        var needs = holder.GetAttributeString("uikit-needs", "0");
        if (newer(needs, VERSION)) {
            log("pack " + pack.id + " " + pack.version + " needs UI Kit " + needs + " or newer, this is " + VERSION +
                ": skipped (update UI Kit)");
            holder.DeleteAsync(0);
            return;
        }
        for (var i = 0; i < holder.GetChildCount(); i++) {
            var d = holder.GetChild(i);
            var w = {
                pack: pack,
                name: d.GetAttributeString("uikit-widget", ""),
                mount: d.GetAttributeString("uikit-mount", "hud"),
                layout: d.GetAttributeString("uikit-layout", ""),
                bind: words(d.GetAttributeString("uikit-bind", "")),
                input: d.GetAttributeString("uikit-input", "") === "1",
                fills: words(d.GetAttributeString("uikit-fills", "")).map(function (f) {
                    var at = f.lastIndexOf(":");
                    return { id: f.slice(0, at), fill: f.slice(at + 1) };
                }),
                holder: null,
                fillPanels: []
            };
            if (w.name && w.layout) pack.widgets.push(w);
        }
        var editText = holder.GetAttributeString("uikit-edits", "");
        if (editText) {
            try { pack.edits = JSON.parse(editText).rules || []; } catch (e) { log("pack " + pack.id + ": its edits can't be read: " + e); }
        }
        packs.push(pack);
        log("pack " + pack.id + " " + pack.version + (pack.author ? " by " + pack.author : "") + " (slot " + slot + "): " +
            (pack.widgets.map(function (w) { return w.name + "@" + w.mount; }).join(", ") || "no widgets") +
            (pack.edits.length ? ", " + pack.edits.length + " edits" : ""));
    }

    // ------------------------------------------------------------------ mounting

    function mountParent(mount) {
        if (!(mount in MOUNTS)) return null;
        return MOUNTS[mount] === null ? kitRoot : hud.FindChildTraverse(MOUNTS[mount]);
    }

    function mountWidget(w) {
        var parent = mountParent(w.mount);
        if (!alive(parent)) {
            log("widget " + w.pack.id + "/" + w.name + ": mount " + w.mount + " not found");
            return;
        }
        var holder = $.CreatePanel("Panel", parent, "UIKit_" + w.pack.id + "_" + w.name);
        // widgets show things; unless one asks for input, nothing in it can catch a click meant for
        // the HUD or the shop below
        holder.hittest = false;
        if (!w.input) holder.hittestchildren = false;
        if (!holder.BLoadLayout(w.layout, false, false)) {
            log("widget " + w.pack.id + "/" + w.name + ": layout did not load (" + w.layout + ")");
            holder.DeleteAsync(0);
            return;
        }
        w.holder = holder;
        w.fillPanels = [];
        w.fills.forEach(function (f) {
            var p = holder.FindChildTraverse(f.id);
            if (alive(p)) w.fillPanels.push({ panel: p, fill: f.fill, last: "" });
            else log("widget " + w.pack.id + "/" + w.name + ": no panel #" + f.id + " for uikit-fill");
        });
        dbg("mounted " + w.pack.id + "/" + w.name + " at " + w.mount);
    }

    // Stock panels a pack replaces: collapsed by an inline style, which the game's class changes
    // don't override.
    function hideStock(pack) {
        pack.hide.forEach(function (id) {
            var p = hud.FindChildTraverse(id);
            if (!alive(p)) { log("hide: no panel #" + id); return; }
            p.style.visibility = "collapse";
            hidden.push({ id: id, panel: p });
        });
    }

    // ------------------------------------------------------------------ edits

    // Edits restyle the game's own HUD panels: a selector and CSS properties, set as inline styles (which
    // win over every stylesheet) on each panel the selector matches below #Hud. They come from packs
    // (edits.json) and from the editor, and are set again when the game makes a panel anew. A selector
    // is compounds of a panel type, an #id, .classes and :nth-child(n), joined by spaces (any depth below)
    // or ">" (a direct child): "#TopBar .SoulsValue", "CitadelHudTopBarPlayer.LocalPlayer > #HealthBar".
    var edits = { live: [], set: null, count: 0, anchors: [], applied: 0, ms: 0, frames: 0, panels: 0, bad: {}, at: 0, off: false };
    // watch() runs a pass only when a panel it styled was rebuilt, and otherwise once every EDITS_FALLBACK_MS for
    // panels that are new (a pass walks the whole HUD; see applyEdits).
    var EDITS_FALLBACK_MS = 15000;
    var COMPOUND_RE = /^([A-Za-z_][A-Za-z0-9_]*)?(#[A-Za-z0-9_\-]+)?((?:\.[A-Za-z0-9_\-]+)*)(?::nth-child\((\d+)\))?$/;

    function camel(prop) { return prop.replace(/-([a-z0-9])/g, function (m, c) { return c.toUpperCase(); }); }

    // [{ comb: " " or ">" (how it hangs below the compound before it), type, id, classes, nth }] or null
    function parseSel(sel) {
        var tokens = String(sel || "").replace(/>/g, " > ").split(/\s+/).filter(function (t) { return t; });
        var out = [], comb = " ";
        for (var i = 0; i < tokens.length; i++) {
            if (tokens[i] === ">") {
                if (!out.length || comb === ">") return null;
                comb = ">";
                continue;
            }
            var m = COMPOUND_RE.exec(tokens[i]);
            if (!m || !(m[1] || m[2] || m[3] || m[4])) return null;
            out.push({ comb: comb, type: m[1] || "", id: m[2] ? m[2].slice(1) : "", nth: m[4] ? parseInt(m[4], 10) : 0,
                       classes: m[3] ? m[3].slice(1).split(".") : [] });
            comb = " ";
        }
        return out.length && comb === " " ? out : null;
    }

    // 1-based position among the parent's children, as :nth-child counts
    function childNumber(p) {
        var parent = p.GetParent();
        if (!alive(parent)) return 0;
        for (var i = 0; i < parent.GetChildCount(); i++) if (parent.GetChild(i) === p) return i + 1;
        return 0;
    }

    function fits(p, c) {
        if (c.id && p.id !== c.id) return false;
        if (c.type && p.paneltype !== c.type) return false;
        for (var i = 0; i < c.classes.length; i++) if (!p.BHasClass(c.classes[i])) return false;
        return !c.nth || childNumber(p) === c.nth;
    }

    // Is there a chain of ancestors above q that fits compounds 0..i? memo (a Map, optional, one per rule and
    // pass) keeps, for each panel and i, whether it or a panel above it fits compound i (with the rest above
    // that), so a climb stops at the first panel that already knows: thousands of candidates share ancestors.
    function aboveFits(q, parsed, i, memo, count) {
        if (i < 0) return true;
        var p = q.GetParent();
        if (!alive(p)) return false;
        if (parsed[i + 1].comb === ">") return fitsHere(p, parsed, i, memo, count);
        return fitsUp(p, parsed, i, memo, count);
    }

    // p fits compound i and the compounds above it
    function fitsHere(p, parsed, i, memo, count) {
        var known = memo && memo.get(p), key = "h" + i;
        if (known && key in known) return known[key];
        if (count) count.checks++;
        var r = fits(p, parsed[i]) && aboveFits(p, parsed, i - 1, memo, count);
        if (memo) { if (!known) { known = {}; memo.set(p, known); } known[key] = r; }
        return r;
    }

    // p or a panel above it (up to #Hud) fits compound i and the compounds above it
    function fitsUp(p, parsed, i, memo, count) {
        var chain = [], r = false, key = "u" + i;
        for (var x = p, guard = 0; alive(x) && guard < 128; x = x.GetParent(), guard++) {
            var known = memo && memo.get(x);
            if (known && key in known) { r = known[key]; break; }
            chain.push(x);
            if (fitsHere(x, parsed, i, memo, count)) { r = true; break; }
            if (x.id === "Hud") break;
        }
        if (memo) chain.forEach(function (c) { var k = memo.get(c); if (!k) { k = {}; memo.set(c, k); } k[key] = r; });
        return r;
    }

    function editRules() {
        var rules = [];
        packs.forEach(function (pk) { rules = rules.concat(pk.edits || []); });
        return rules.concat(edits.live);
    }

    // The same rule twice (Clean has "#Hud Label { font-family: Jost; }" in 51 theme files, one per layout)
    // only needs its last copy: nothing after that copy changes what it set. The copies left out are told
    // the kept one's hits when the pass ends.
    function uniqueRules(rules) {
        var last = {}, out = [], twins = [];
        rules.forEach(function (r, i) { last[r.sel + "\u0000" + JSON.stringify(r.props || {})] = i; });
        rules.forEach(function (r, i) {
            var kept = last[r.sel + "\u0000" + JSON.stringify(r.props || {})];
            if (kept === i) out.push(r); else twins.push([r, rules[kept]]);
        });
        return { rules: out, twins: twins };
    }

    function setInline(p, key, value) {
        try { p.style[key] = value; return true; } catch (e) { return false; }
    }

    // A pass sets every rule's properties on the panels it matches now (later rules win) and takes off what an
    // earlier pass set where nothing wants it any more. It walks every panel below #Hud (about 43,000 in a
    // match), so it runs as a job of small steps, at most EDIT_SLICE_MS of work per frame, and never blocks
    // the game: Clean's 451 rules in one blocking pass took 54 s in a match and froze the game (game 6753).
    // A pass that needs more than EDITS_MAX_WORK_MS of work in all is given up and edits stay off until the
    // game restarts. Steps: walk the tree (index panels by id and type), match each rule's candidates
    // (by id, type, or one native class lookup per class and pass), set what changed, take off what's gone.
    var EDIT_SLICE_MS = 3;
    // Frames far apart mean the game is in the background (about 18 fps while the author is in the editor
    // page) or paused: then a slice may take longer, or a pass of 140 slices takes 8 s to show an edit.
    var EDIT_SLICE_SLOW_MS = 20, EDIT_SLOW_GAP_MS = 40;
    var EDIT_SLICE_STEPS = 4000;
    var EDITS_MAX_WORK_MS = 8000;
    var editJob = null, editWaiting = [];

    // Ask for a pass; done() runs when it has finished (or right away if there is nothing to do). A request
    // during a pass starts another one after it, so new rules are never missed.
    function applyEdits(done) {
        if (editJob) { editWaiting.push(done || null); return; }
        var rules = edits.off || !alive(hud) ? [] : editRules();
        if (!rules.length && !edits.count) { if (done) done(); return; }
        if (typeof Map !== "function") {
            edits.off = true;
            log("edits: this game's script has no Map, so edits are off");
            if (done) done();
            return;
        }
        var unique = uniqueRules(rules);
        var job = { rules: unique.rules, twins: unique.twins, all_rules: rules.length, step: "walk", stack: [], parents: [], all: [], up: [], size: null, byId: {}, byType: {}, classes: {},
                    panels: 0, want: new Map(), styles: 0,
                    ri: 0, cands: null, ci: 0, list: null, li: 0, anchors: [], work: 0, frames: 0, spent: {}, lookups: 0, lookupMs: 0, ncands: 0, checks: 0, memo: null, done: [done] };
        for (var i = hud.GetChildCount() - 1; i >= 0; i--) { job.stack.push(hud.GetChild(i)); job.parents.push(-1); }
        editJob = job;
        editStep();
    }

    // Subtree sizes from the walk: panel n's descendants are n+1 .. n+size[n]-1.
    function editSizes(job) {
        var size = [];
        for (var i = 0; i < job.all.length; i++) size.push(1);
        for (var j = job.all.length - 1; j >= 0; j--) if (job.up[j] >= 0) size[job.up[j]] += size[j];
        job.size = size;
    }

    // The entries of a sorted list of walk positions that lie in [lo, hi]
    function inRange(list, lo, hi, out) {
        var a = 0, b = list.length;
        while (a < b) { var m = (a + b) >> 1; if (list[m] < lo) a = m + 1; else b = m; }
        for (; a < list.length && list[a] <= hi; a++) out.push(list[a]);
    }

    // The panels a selector's last compound can be. By id: from the walk. By type or class: below the nearest
    // compound with an #id when there is one ("#TopBar Label" looks at the top bar's labels, not all of them;
    // without it Clean's rules had 567,000 candidates for 25,000 matches), by type from the walk, by class
    // looked up natively.
    function editCandidates(job, parsed) {
        var last = parsed[parsed.length - 1], scope = "", out = [], i;
        if (last.id) return (job.byId[last.id] || []).map(function (n) { return job.all[n]; });
        for (i = parsed.length - 2; i >= 0; i--) if (parsed[i].id) { scope = parsed[i].id; break; }
        var roots = scope ? job.byId[scope] || [] : null;
        if (last.type) {
            var list = job.byType[last.type] || [];
            if (!roots) return list.map(function (n) { return job.all[n]; });
            var picked = [];
            for (i = 0; i < roots.length; i++) inRange(list, roots[i] + 1, roots[i] + job.size[roots[i]] - 1, picked);
            return picked.map(function (n) { return job.all[n]; });
        }
        var c = last.classes[0], key = c + "@" + scope;
        if (!(key in job.classes)) {
            var from = roots ? roots.map(function (n) { return job.all[n]; }) : [hud];
            job.lookups++;
            for (i = 0; i < from.length; i++) {
                var some = from[i].FindChildrenWithClassTraverse(c) || [];
                for (var f = 0; f < some.length; f++) out.push(some[f]);
            }
            job.classes[key] = out;
        }
        return job.classes[key];
    }

    // "#Hud x" matches every x the walk finds (they are all below #Hud): no need to look above each one
    function editParse(sel) {
        var parsed = parseSel(sel);
        if (parsed && parsed.length > 1 && parsed[0].id === "Hud" && !parsed[0].type && !parsed[0].classes.length &&
            !parsed[0].nth && parsed[1].comb === " ") parsed = parsed.slice(1);
        return parsed;
    }

    function editStep() {
        var job = editJob;
        if (!job) return;
        var t0 = now(), steps = 0, finished = false, began = job.step;
        var budget = job.last && t0 - job.last > EDIT_SLOW_GAP_MS ? EDIT_SLICE_SLOW_MS : EDIT_SLICE_MS;
        job.last = t0;
        try {
            while (!finished) {
                if (++steps > EDIT_SLICE_STEPS * (budget / EDIT_SLICE_MS) || (steps % 16 === 0 && now() - t0 >= budget)) break;
                if (job.step === "walk") {
                    if (!job.stack.length) { editSizes(job); job.step = "match"; continue; }
                    var p = job.stack.pop(), up = job.parents.pop();
                    if (!p || p.id === "UIKitEditorLayer" || p.id === "UIKitLive" || p.id === "UIKitInspect") continue;
                    var n = job.all.length;                     // depth-first order: a subtree is a range of n
                    job.all.push(p);
                    job.up.push(up);
                    job.panels++;
                    if (p.id) (job.byId[p.id] = job.byId[p.id] || []).push(n);
                    (job.byType[p.paneltype] = job.byType[p.paneltype] || []).push(n);
                    for (var c = p.GetChildCount() - 1; c >= 0; c--) { job.stack.push(p.GetChild(c)); job.parents.push(n); }
                } else if (job.step === "match") {
                    if (!job.cands) {
                        if (job.ri >= job.rules.length) {
                            job.list = [];
                            job.want.forEach(function (props, panel) { job.list.push(panel); });
                            job.step = "set";
                            continue;
                        }
                        var r = job.rules[job.ri];
                        r.hits = 0;
                        job.parsed = editParse(r.sel);
                        if (!job.parsed) {
                            if (!edits.bad[r.sel]) { edits.bad[r.sel] = true; log("edits: can't read the selector \"" + r.sel + "\""); }
                            job.ri++;
                            continue;
                        }
                        job.props = Object.keys(r.props || {}).map(function (k) { return [camel(k), r.props[k]]; });
                        var tl = now();
                        job.cands = editCandidates(job, job.parsed);
                        job.lookupMs += now() - tl;
                        job.memo = new Map();
                        job.ncands += job.cands.length;
                        if (DEBUG) (job.heavy = job.heavy || []).push([job.cands.length, r.sel]);
                        job.ci = 0;
                        steps |= 15;                       // a class lookup walks the tree natively: check the time next
                        continue;
                    }
                    if (job.ci >= job.cands.length) { job.cands = null; job.ri++; continue; }
                    var q = job.cands[job.ci++], parsed = job.parsed, rule = job.rules[job.ri];
                    if (!alive(q) || q.id === "UIKitEditorLayer" || q.id === "UIKitLive" || q.id === "UIKitInspect" || !fits(q, parsed[parsed.length - 1]) ||
                        !aboveFits(q, parsed, parsed.length - 2, job.memo, job)) continue;
                    if (!rule.hits++) job.anchors.push(q);
                    var props = job.want.get(q);
                    if (!props) { props = {}; job.want.set(q, props); }
                    for (var k = 0; k < job.props.length; k++) {
                        if (!(job.props[k][0] in props)) job.styles++;
                        props[job.props[k][0]] = job.props[k][1];
                    }
                } else if (job.step === "set") {                // what this pass wants and the last one didn't set
                    if (job.li >= job.list.length) {
                        job.list = [];
                        if (edits.set) edits.set.forEach(function (props, panel) { job.list.push(panel); });
                        job.li = 0;
                        job.step = "clear";
                        continue;
                    }
                    var panel = job.list[job.li++];
                    if (!alive(panel)) continue;
                    var want = job.want.get(panel), had = edits.set && edits.set.get(panel) || {};
                    for (var key in want) {
                        if (had[key] === want[key]) continue;
                        if (!setInline(panel, key, want[key]) && !edits.bad[key + want[key]]) {
                            edits.bad[key + want[key]] = true;
                            log("edits: the game refused " + key + ": " + want[key]);
                        }
                    }
                } else {                                        // "clear": what the last pass set and this one doesn't want
                    if (job.li >= job.list.length) { finished = true; break; }
                    var old = job.list[job.li++];
                    if (!alive(old)) continue;
                    var still = job.want.get(old) || {}, before = edits.set.get(old);
                    for (var key2 in before) if (!(key2 in still)) setInline(old, key2, null);
                }
            }
        } catch (e) {
            log("edits: a pass failed: " + e);
            finished = true;
        }
        job.work += now() - t0;
        job.spent[began] = (job.spent[began] || 0) + now() - t0;   // a slice counts for the step it began in
        job.frames++;
        if (!finished && job.work > EDITS_MAX_WORK_MS) {
            edits.off = true;
            log("edits: a pass needed more than " + EDITS_MAX_WORK_MS + " ms of work (" + job.rules.length + " rules, " + job.panels +
                " panels so far), so edits are off until the game restarts");
            finished = true;
        }
        if (!finished) { $.Schedule(0.0, editStep); return; }
        editFinish(job);
    }

    function editFinish(job) {
        if (job.step === "clear" || !edits.set) {
            edits.set = job.want;
            edits.count = job.styles;
            edits.anchors = job.anchors;
        }
        edits.applied++;
        edits.at = Date.now();
        edits.panels = job.panels;
        edits.ms = Math.round(job.work);
        edits.frames = job.frames;
        if (edits.applied === 1 || edits.ms > 30 || job.frames >= 3) {
            dbg("edits: " + job.all_rules + " rules" + (job.twins.length ? " (" + job.twins.length + " repeated)" : "") + " on " + edits.count + " styles, " + job.panels + " panels looked at, " +
                edits.ms + " ms of work in " + job.frames + " frame" + (job.frames === 1 ? "" : "s") + " (" +
                ["walk", "match", "set", "clear"].map(function (k) { return k + " " + Math.round(job.spent[k] || 0); }).join(", ") +
                " ms; " + job.lookups + " class lookups in " + Math.round(job.lookupMs) + " ms, " + job.ncands + " candidates, " +
                job.checks + " ancestor checks)");
        }
        if (DEBUG && job.heavy && job.ncands > 100000 && !edits.heavyShown) {
            edits.heavyShown = true;
            job.heavy.sort(function (a, b) { return b[0] - a[0]; });
            dbg("edits: most candidates: " + job.heavy.slice(0, 6).map(function (h) { return h[0] + " " + h[1]; }).join(" | "));
        }
        job.twins.forEach(function (t) { t[0].hits = t[1].hits; });
        editJob = null;
        job.done.forEach(function (f) { if (f) f(); });
        if (editWaiting.length) {
            var next = editWaiting;
            editWaiting = [];
            applyEdits(function () { next.forEach(function (f) { if (f) f(); }); });
        }
    }

    // a styled panel was rebuilt (the game makes some anew; one panel per rule is checked), or the slow
    // fallback for new panels is due
    function editsDue() {
        if (editJob || edits.off || (!edits.count && !editRules().length)) return false;
        for (var i = 0; i < edits.anchors.length; i++) if (!alive(edits.anchors[i])) return true;
        return Date.now() - edits.at >= EDITS_FALLBACK_MS;
    }

    // ------------------------------------------------------------------ bridge

    function widgets() {
        var out = [];
        packs.forEach(function (p) { out = out.concat(p.widgets); });
        return out;
    }

    function startBridge() {
        var wanted = {};
        widgets().forEach(function (w) {
            if (!w.holder) return;
            w.bind.forEach(function (b) { if (BINDS[b]) wanted[b] = true; });
        });
        bridge.binds = Object.keys(wanted).map(function (b, i) {
            var spec = BINDS[b];
            return {
                name: b, spec: spec, every: Math.max(1, spec.every || 1), phase: i,
                // whole numbers raw (no separators); decimals and text as the stock HUD shows them
                reads: spec.vars.map(function (v) { return v[1] === "i" ? "{i:r:" + v[0] + "}" : "{" + v[1] + ":" + v[0] + "}"; })
            };
        });
        bridge.last = {};
        if (bridge.binds.length && bridge.handler === null) {
            bridge.handler = $.RegisterForUnhandledEvent("CitadelHudUpdate", tick);
        }
        if (bridge.binds.length) dbg("copying " + bridge.binds.map(function (b) {
            return b.name + (b.every > 1 ? " (every " + b.every + " frames)" : " (every frame)");
        }).join(", "));
    }

    function findType(p, type, depth) {
        if (!alive(p) || depth > 30) return null;
        for (var i = 0; i < p.GetChildCount(); i++) {
            var c = p.GetChild(i);
            if (c.paneltype === type) return c;
            var r = findType(c, type, depth + 1);
            if (r) return r;
        }
        return null;
    }

    // A bind's source: a panel id, or "<panel type>@<id>" for the first panel of that type inside it.
    function source(b) {
        var s = sources[b.name];
        if (s && alive(s.panel)) return s.panel;
        var t = Date.now();
        if (s && t - s.at < RETRY_MS) return null;
        var spec = b.spec.source, at = spec.indexOf("@"), p = null;
        if (alive(hud)) p = at < 0 ? hud.FindChildTraverse(spec) : findType(hud.FindChildTraverse(spec.slice(at + 1)), spec.slice(0, at), 0);
        sources[b.name] = { panel: alive(p) ? p : null, at: t };
        return sources[b.name].panel;
    }

    // Once per frame: copy bound values and classes that changed, then redraw fills. Rebuilt panels are
    // watch()'s job; an error here is reported once instead of every frame.
    function tick() {
        bridge.ticks++;
        try {
            update(false);
        } catch (e) {
            if (!bridge.failed) { bridge.failed = true; log("bridge error: " + e); }
        }
        if (DEBUG && Date.now() - bridge.since >= 60000) {
            var stats = { rate: bridge.ticks * 1000 / (Date.now() - bridge.since), writes: bridge.writes };
            bridge.ticks = bridge.writes = 0;
            bridge.since = Date.now();
            $.Schedule(0.0, function () { report(stats); });
        }
    }

    // all: every bind, also the ones not due this frame (for timing)
    function update(all) {
        var changed = false;
        for (var i = 0; i < bridge.binds.length; i++) {
            var b = bridge.binds[i];
            if (!all && b.every > 1 && (bridge.ticks + b.phase) % b.every !== 0) continue;
            var src = source(b);
            if (!src) continue;
            for (var j = 0; j < b.spec.vars.length; j++) {
                // whole numbers are written as numbers (fills divide them); everything else as the text
                // the game shows: script can't set a decimal (no SetDialogVariableFloat in game 6746)
                var name = b.spec.vars[j][0], whole = b.spec.vars[j][1] === "i", text = $.Localize(b.reads[j], src);
                var v = whole ? parseInt(text, 10) : String(text);
                if (whole && !isFinite(v)) v = 0;
                if (bridge.last[name] !== v) {
                    bridge.last[name] = v;
                    if (whole) kitRoot.SetDialogVariableInt(name, v);
                    else kitRoot.SetDialogVariable(name, v);
                    bridge.writes++;
                    changed = true;
                }
            }
            for (var k = 0; k < b.spec.classes.length; k++) {
                var c = b.spec.classes[k], on = src.BHasClass(c);
                if (bridge.last["." + c] !== on) {
                    bridge.last["." + c] = on;
                    kitRoot.SetHasClass(c, on);
                }
            }
        }
        if (changed) drawFills();
    }

    // Debug builds, once a minute: what an update costs on average (binds copied every n-th frame
    // included as they run), and with every bind due at once. Date.now only counts whole milliseconds,
    // too coarse for a single update, so each piece is timed over 1000 repetitions.
    function report(stats) {
        var b = bridge.binds[0], src = b ? source(b) : null;
        var line = "bridge: " + Math.round(stats.rate) + " updates/s, " + stats.writes + " writes in the last minute";
        if (!src) { dbg(line); return; }
        var n = 1000, read = b.reads[0], cls = b.spec.classes[0] || "dead";
        function time(fn) {
            var t0 = Date.now();
            for (var i = 0; i < n; i++) fn();
            return (Date.now() - t0) * 1000 / n;
        }
        var loc = time(function () { $.Localize(read, src); });
        var has = time(function () { src.BHasClass(cls); });
        var valid = time(function () { src.IsValid(); });
        var writes = bridge.writes, ticks = bridge.ticks;
        var avg = time(function () { bridge.ticks++; update(false); });
        var full = time(function () { update(true); });
        bridge.writes = writes;
        bridge.ticks = ticks;
        dbg(line + "; one update " + avg.toFixed(2) + " us on average, " + full.toFixed(2) + " us with all " +
            bridge.binds.length + " bind" + (bridge.binds.length === 1 ? "" : "s") + " due (per call: Localize " +
            loc.toFixed(2) + ", BHasClass " + has.toFixed(2) + ", IsValid " + valid.toFixed(2) + " us) = " +
            (avg * stats.rate / 1000).toFixed(3) + " ms of script per second");
    }

    // uikit-fill panels are clipped to the bound fraction (clip doesn't relayout).
    function drawFills() {
        widgets().forEach(function (w) {
            w.fillPanels.forEach(function (f) {
                if (!alive(f.panel)) return;
                var pair = null;
                bridge.binds.forEach(function (b) { if (b.spec.fills[f.fill]) pair = b.spec.fills[f.fill]; });
                if (!pair) return;
                var total = bridge.last[pair[1]];
                var pct = total > 0 ? Math.max(0, Math.min(100, bridge.last[pair[0]] / total * 100)) : 0;
                var clip = "rect(0%, " + pct.toFixed(1) + "%, 100%, 0%)";
                if (clip !== f.last) {
                    f.last = clip;
                    f.panel.style.clip = clip;
                }
            });
        });
    }

    // Debug builds: game components that are 0x0 on screen are invisible. Their size usually comes from
    // the stock HUD's CSS for the stock panel's id, which a copy doesn't have. Checked once a match HUD
    // is on screen (the runtime starts with the HUD at the main menu, where everything is 0x0).
    function checkSizes() {
        widgets().forEach(function (w) {
            if (!alive(w.holder)) return;
            (function walk(p, depth) {
                if (depth > 12) return;
                for (var i = 0; i < p.GetChildCount(); i++) {
                    var c = p.GetChild(i), size = Math.round(c.actuallayoutwidth) + "x" + Math.round(c.actuallayoutheight);
                    if (SIZED.indexOf(c.paneltype) < 0) { walk(c, depth + 1); continue; }
                    if (c.actuallayoutwidth >= 1 && c.actuallayoutheight >= 1) {
                        dbg("widget " + w.pack.id + "/" + w.name + ": " + c.paneltype + " is " + size);
                    } else {
                        dbg("widget " + w.pack.id + "/" + w.name + ": " + c.paneltype + " is " + size + ", so it can't be " +
                            "seen; unless the widget is hidden right now, give it (or a panel around it) a width and height");
                    }
                }
            })(w.holder, 0);
        });
    }

    // ------------------------------------------------------------------ lifecycle

    function mountAll() {
        hidden = [];
        packs.forEach(function (pack) {
            pack.widgets.forEach(mountWidget);
            hideStock(pack);
        });
        startBridge();
        var n = widgets().filter(function (w) { return w.holder; }).length;
        log("mounted " + n + " widget" + (n === 1 ? "" : "s") + " from " + packs.length + " pack" + (packs.length === 1 ? "" : "s"));
    }

    // The HUD or a component can be rebuilt (map change, reconnect): put everything back. Hooked into
    // the HUD itself, this runtime goes with the old HUD and the new HUD starts a new one.
    function watch() {
        if (!alive(ctx)) return;
        if (!alive(kitRoot)) {
            log("HUD rebuilt, mounting again");
            started = false;
            sources = {};
            sizesChecked = false;
            start();
            return;
        }
        var again = false;
        widgets().forEach(function (w) {
            if (w.holder && !alive(w.holder)) { w.holder = null; again = true; }
        });
        if (again) {
            dbg("a component was rebuilt, remounting its widgets");
            widgets().forEach(function (w) { if (!w.holder) mountWidget(w); });
            startBridge();
        }
        hidden.forEach(function (h) {
            if (alive(h.panel)) return;
            var p = hud.FindChildTraverse(h.id);
            if (alive(p)) { p.style.visibility = "collapse"; h.panel = p; }
        });
        if (editsDue()) applyEdits();
        if (DEBUG) {
            ["gShopOpen", "gScoreboardOpen"].forEach(function (c) {
                if (!seen[c] && kitRoot.BHasClass(c)) { seen[c] = true; dbg("kit root has " + c + " (from its GlobalClassListener)"); }
            });
            // the kit root's stylesheet hides every widget while the HUD has InHideout (main menu)
            var away = hud.BHasClass("InHideout");
            if (seen.InHideout !== away) { seen.InHideout = away; dbg(away ? "HUD in the hideout: widgets hidden" : "HUD out of the hideout: widgets shown"); }
            var hc = sizesChecked ? null : hud.FindChildTraverse("health_and_abilities_container");
            if (alive(hc) && hc.actuallayoutwidth > 0 && !hud.BHasClass("InHideout")) {
                sizesChecked = true;
                $.Schedule(3.0, checkSizes);
            }
        }
        $.Schedule(2.0, watch);
    }

    function start() {
        if (started || !alive(ctx)) return;
        hud = findHud();
        core = alive(hud) ? (hud.FindChildrenWithClassTraverse("HudCore") || [])[0] : null;
        if (!alive(core)) { $.Schedule(0.5, start); return; }
        started = true;
        kitRoot = $.CreatePanel("Panel", core, "UIKitRoot");
        // its layout puts gShopOpen and gScoreboardOpen on it, for every widget
        if (!kitRoot.BLoadLayout(ROOT_LAYOUT, false, false)) log("kit root layout missing: widgets won't see the shop and scoreboard state");
        kitRoot.hittest = false;
        kitRoot.style.width = "100%";
        kitRoot.style.height = "100%";
        discover();
        mountAll();
        applyEdits();
        if (typeof startEditor === "function") startEditor();
        if (typeof liveStart === "function") liveStart();
        $.Schedule(2.0, watch);
    }

    /*__UK_EDITOR__*/

    /*__UK_LIVE__*/

    log("runtime " + VERSION + " loaded in " + (alive(ctx) ? ctx.paneltype : "?") + (DEBUG ? " (debug)" : ""));
    $.Schedule(0.0, start);
})();

toolchain.web/browser.py:
"""UI Kit's builder in a web page: the Python toolchain under Pyodide, fed by the page.

A web page can't open the player's 40 GB of game archives as files, and must not ship Valve's files, so:

1. The page reads the game's two VPK index files (pak01_dir.vpk of citadel and core, 8 MB) into /game.
2. plan() lists the archive pieces a build needs (layouts, stylesheets, templates): archive number, offset and
   length. The page reads just those bytes (File.slice) and hands them to load().
3. build() makes the pack's VPK with build.build_pack, exactly as `pack.py build` does (the same bytes). A file
   that wasn't fetched raises Missing; the page fetches it and builds again.
4. install_plan() runs the installer against a copy of the addons folder (real files for UI Kit's, stubs for
   other mods) and returns what to write and delete in the real one.
"""
import hashlib
import json
import os
import re
import shutil
import sys

sys.path[:0] = ["/uikit/tools", "/uikit"]

import build  # noqa: E402
import kv3  # noqa: E402
import laco  # noqa: E402
import packs as packmod  # noqa: E402
import resource  # noqa: E402
import survey as surveymod  # noqa: E402
import vpk  # noqa: E402
from compilers import BuildError  # noqa: E402

GAME = "/game"            # game/citadel/pak01_dir.vpk, game/core/pak01_dir.vpk, steam.inf
FOLDERS = ("citadel", "core")


class Missing(Exception):
    def __init__(self, path):
        Exception.__init__(self, path)
        self.path = path


class BrowserGame:
    """The installed game as build.py reads it (read, layout, names, version), from the index files and the
    pieces the page fetched."""

    def __init__(self, version="?"):
        self.paks = []
        for folder in FOLDERS:
            path = os.path.join(GAME, "game", folder, "pak01_dir.vpk")
            if os.path.isfile(path):
                entries, base = vpk.read_index(path)
                self.paks.append((folder, path, entries, base))
        self.fetched = {}
        self._version = version

    def entry(self, path):
        for folder, dirfile, entries, base in self.paks:
            if path in entries:
                return folder, dirfile, entries[path], base
        return None

    def names(self, prefix=""):
        return sorted({e for _, _, entries, _ in self.paks for e in entries if e.startswith(prefix)})

    def has(self, path):
        return self.entry(path) is not None

    def read(self, path):
        found = self.entry(path)
        if found is None:
            raise BuildError("game file missing from pak01 (citadel and core): " + path)
        folder, dirfile, e, base = found
        if not e["length"] or e["archive"] == 0x7FFF:
            return vpk.read_file(dirfile, e, base)        # in the index file, which the page loaded
        if path not in self.fetched:
            raise Missing(path)
        return e["preload"] + self.fetched[path]

    def layout(self, path):
        return laco.to_xml(kv3.loads(resource.get_block(self.read(path), b"LaCo")))

    def version(self):
        return self._version


game = None


def start(version):
    global game
    game = BrowserGame(version)
    return len(game.names())


def piece(path):
    found = game.entry(path)
    if found is None:
        return None
    folder, _, e, _ = found
    if not e["length"] or e["archive"] == 0x7FFF or path in game.fetched:
        return None
    return {"path": path, "folder": folder, "archive": e["archive"], "offset": e["offset"], "length": e["length"]}


def plan(theme_names):
    """The archive pieces a build of a pack with these theme files needs: [{path, folder, archive, offset, length}]."""
    want = {build.LAYOUT_TEMPLATE, build.CSS_TEMPLATE, build.SVG_TEMPLATE, build.HUD_LAYOUT, build.HOOKS["perfstats"]}
    want |= set(build.DEFINE_SHEETS)
    want |= {packmod.theme_res(n) + ".vxml_c" for n in theme_names}
    for path in game.names("panorama/layout/"):
        if surveymod.HUD_LAYOUT_RE.match(path) or packmod.THEME_LAYOUT_RE.match(path) or path == build.HOOKS_BASE:
            want.add(path)
    for path in game.names("panorama/styles/"):
        if path.endswith(".vcss_c") and packmod.THEME_STYLE_RE.search(path):
            want.add(path)
    return json.dumps([p for p in (piece(path) for path in sorted(want)) if p])


def load(path, data):
    """data: the piece's bytes (a JavaScript Uint8Array)."""
    game.fetched[path] = data.to_bytes() if hasattr(data, "to_bytes") else bytes(data)


def build_pack(files_json):
    """files: {relative path: text} of a pack folder. Returns JSON: {"ok": true, "vpk": path, "id", "warnings"} or
    {"missing": path} (fetch it, load() it, build again) or {"error": message}."""
    files = json.loads(files_json)
    folder = "/work/pack"
    shutil.rmtree("/work", ignore_errors=True)
    for rel, text in files.items():
        dest = os.path.join(folder, rel)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "w", encoding="utf-8") as f:
            f.write(text)
    try:
        result = build.build_pack(game, folder, dist="/work/dist")
    except Missing as m:
        return json.dumps({"missing": piece(m.path)})
    except BuildError as e:
        return json.dumps({"error": str(e)})
    return json.dumps({"ok": True, "vpk": result["vpk"], "id": result["pack"].id, "warnings": result["warnings"]})


def build_runtime():
    """UI Kit's runtime (for packs with widgets), as `install.py --release` builds it. JSON {"ok", "vpk", "version"}
    or {"missing": piece} or {"error"}."""
    try:
        result = build.build_game(game, debug=False, dist="/work/runtime")
    except Missing as m:
        return json.dumps({"missing": piece(m.path)})
    except BuildError as e:
        return json.dumps({"error": str(e)})
    return json.dumps({"ok": True, "vpk": result["vpk"], "version": result["version"]})


# ------------------------------------------------------------------ installing into the real addons folder

ROOT = "/install"            # a copy of the Deadlock folder: game/citadel/gameinfo.gi and game/citadel/addons


ORIGINAL = "/install_original"   # the addons copy as the page set it up: every attempt starts from it


def install_start():
    """The page has put the addons copy in place: keep it, so a second attempt (replacing a theme after the
    first found it in the way) starts from the same files, not from what the first one changed."""
    addons_dir = os.path.join(ROOT, "game", "citadel", "addons")
    shutil.rmtree(ORIGINAL, ignore_errors=True)
    shutil.copytree(addons_dir, ORIGINAL)


def install_plan(gameinfo, listing_json, vpk_path, replace, runtime_vpk=None):
    """listing: {file name in addons: bytes or null (a big file of another mod: a stub stands in)}, set up by the
    page under /install. Runs pack.py's installer there; returns JSON {"write": {name: path of the new content},
    "delete": [names], "messages": [...]} or {"error", "conflict": [pack ids]}."""
    import addons
    import pack as packcli
    addons_dir = os.path.join(ROOT, "game", "citadel", "addons")
    listing = json.loads(listing_json)
    if os.path.isdir(ORIGINAL):
        shutil.rmtree(addons_dir)
        shutil.copytree(ORIGINAL, addons_dir)
    before = {}
    for name in os.listdir(addons_dir):
        with open(os.path.join(addons_dir, name), "rb") as f:
            before[name] = hashlib.sha1(f.read()).hexdigest()
    messages = []
    try:
        if runtime_vpk:
            # as install.py: an installed UI Kit is updated in its place unless it is newer; else the next number
            installed = addons.runtime(addons_dir)
            ours = build.RUNTIME_VERSION
            if installed and packmod.version_tuple(installed.runtime_version) > packmod.version_tuple(ours):
                messages.append("UI Kit %s is installed (newer than this page's %s): kept" % (installed.runtime_version, ours))
            else:
                number = installed.number if installed else addons.free_number(addons_dir)
                name = addons.install(addons_dir, runtime_vpk, number)
                messages.append("%s UI Kit %s as %s" % ("updated" if installed else "installed", ours, name))
        if replace:
            manifest = packcli.vpk_manifest(vpk_path)
            mine = packcli.replaced(manifest)
            for pid, pak in addons.installed_packs(addons_dir).items():
                if pid != manifest["id"] and (mine & packcli.replaced(pak.manifest) or pak.manifest.get("slot") == manifest["slot"]):
                    messages.append("pack %s: %s" % (pid, addons.remove(addons_dir, pak.number)))
        messages += packcli.install_pack(ROOT, vpk_path, game=game)
    except BuildError as e:
        text = str(e)
        conflict = re.findall(r"installed pack (\w+)", text)
        return json.dumps({"error": text, "conflict": conflict})
    write, delete = {}, []
    after = set(os.listdir(addons_dir))
    for name in after:
        with open(os.path.join(addons_dir, name), "rb") as f:
            digest = hashlib.sha1(f.read()).hexdigest()
        if before.get(name) != digest:
            if listing.get(name, "") is None and name in before:
                continue                   # a stub of another mod's big file: never written back
            write[name] = os.path.join(addons_dir, name)
    delete = sorted(set(before) - after)
    return json.dumps({"write": write, "delete": delete, "messages": messages})

toolchain.tools/compilers.py:
"""Source 2 Panorama resource compilers shared by the build script.

From HUD Fit (and Hero Select Plus before it), where they were validated against every UI file
in the game (tools/selftest.py). compile_new_layout compiles layout files the game doesn't have;
verified in game build 6746 (HUD Fit's engine probe).
"""
import copy
import re
import struct
import zlib

import kv3
import laco
import resource

MOD_SEARCH_PATH = "citadel_addons/uikit"


class BuildError(Exception):
    pass


def insert(xml, anchor, addition, before=False):
    """Insert `addition` on its own line(s) next to the unique line containing `anchor`, matching its indent."""
    lines = xml.split("\n")
    hits = [i for i, l in enumerate(lines) if anchor in l]
    if len(hits) != 1:
        raise BuildError("layout anchor %r found %d times (expected 1); the game layout changed" % (anchor, len(hits)))
    i = hits[0]
    indent = re.match(r"\s*", lines[i]).group(0)
    new = [indent + l for l in addition.strip("\n").split("\n")]
    pos = i if before else i + 1
    return "\n".join(lines[:pos] + new + lines[pos:])


def num(v):
    if v == 0:
        return kv3.Typed(kv3.INT64_ZERO, 0)
    if v == 1:
        return kv3.Typed(kv3.INT64_ONE, 1)
    return kv3.Typed(kv3.UINT32, v)


def objs(items):
    return kv3.Typed(kv3.ARRAY_TYPE_BYTE_LENGTH, items, 0, (kv3.OBJECT, 0)) if items else []


def input_dep(rel, crc, exists):
    return {"m_RelativeFilename": rel, "m_SearchPath": MOD_SEARCH_PATH, "m_nFileCRC": num(crc),
            "m_bOptional": not exists, "m_bFileExists": exists, "m_bIsGameFile": False}


def compile_layout(original, xml, added_refs):
    """Rebuild a .vxml_c from patched XML, keeping the original file's metadata."""
    version, blocks = resource.read_blocks(original)
    out = []
    for name, body in blocks:
        if name == b"LaCo":
            body = kv3.dumps(laco.from_xml(xml))
        elif name == b"DATA":
            body = struct.pack("<IH", zlib.crc32(xml.encode("utf-8")), 0)
        elif name == b"RED2":
            red = kv3.loads(body)
            weak = red.get("m_WeakReferenceList")
            refs = sorted(set((weak.v if isinstance(weak, kv3.Typed) else []) + added_refs))
            red["m_WeakReferenceList"] = kv3.Typed(kv3.ARRAY_TYPE_BYTE_LENGTH, refs, 0, (kv3.STRING, 2))
            body = kv3.dumps(red)
        out.append((name, body))
    if not any(n == b"LaCo" for n, _ in out):
        raise BuildError("game layout has no compiled layout block; the layout format changed")
    return resource.write_blocks(version, out)


def compile_new_layout(template, xml, res, refs):
    """Compile a layout file the game doesn't have (res = 'panorama/layout/<name>', no extension).

    A game layout supplies the resource metadata, as the stylesheet template does for compile_css;
    its RED2 is pointed at the new source and lists `refs` as the file's references.
    """
    version, blocks = resource.read_blocks(template)
    out = []
    for name, body in blocks:
        if name == b"LaCo":
            body = kv3.dumps(laco.from_xml(xml))
        elif name == b"DATA":
            body = struct.pack("<IH", zlib.crc32(xml.encode("utf-8")), 0)
        elif name == b"RED2":
            red = copy.deepcopy(kv3.loads(body))
            red["m_InputDependencies"] = objs([
                input_dep(res + ".xml", zlib.crc32(xml.encode("utf-8")), True),
                input_dep(res + ".vxml", 0, False),
            ])
            red["m_WeakReferenceList"] = (kv3.Typed(kv3.ARRAY_TYPE_BYTE_LENGTH, sorted(set(refs)), 0, (kv3.STRING, 2))
                                          if refs else [])
            body = kv3.dumps(red)
        out.append((name, body))
    if not any(n == b"LaCo" for n, _ in out):
        raise BuildError("game layout has no compiled layout block; the layout format changed")
    return resource.write_blocks(version, out)


def minify_css(src, imports=False):
    """Minify CSS the way the game's compiler lays it out and build the byte -> source position map.

    Plain rules, @define constants and @keyframes blocks. @import only with imports=True (the game's own
    stylesheets use it; a theme adds its rules to them); packs include stylesheets from layouts instead.
    """
    text = re.sub(r"/\*.*?\*/", lambda m: re.sub(r"[^\n]", " ", m.group(0)), src, flags=re.S)
    out, smap = [], []
    size = 0

    def emit(s):
        nonlocal size
        out.append(s)
        size += len(s.encode("utf-8"))

    def pos(offset):
        line = text.count("\n", 0, offset) + 1
        col = offset - (text.rfind("\n", 0, offset) + 1) + 1
        return line, col

    def mark(offset, shift=0):
        line, col = pos(offset)
        smap.append([size, line, col + shift])

    def skip_space(i):
        while i < n and text[i].isspace():
            i += 1
        return i

    def declarations(start, end):
        cursor = start
        for decl in text[start:end].split(";"):
            stripped = decl.strip()
            if stripped:
                if ":" not in stripped:
                    raise BuildError("css: bad declaration %r" % stripped)
                at = cursor + (len(decl) - len(decl.lstrip()))
                prop, value = stripped.split(":", 1)
                prop, value = prop.strip(), " ".join(value.split())
                mark(at)
                emit(prop + ": ")
                mark(at, len(prop) + 2)
                emit(value)
                mark(at)
                emit(";")
            cursor += len(decl) + 1

    def block(i):
        """Index of the '{' after i and of its matching '}' (no nesting inside)."""
        brace = text.find("{", i)
        end = text.find("}", brace)
        if brace < 0 or end < 0:
            raise BuildError("css: unbalanced braces near offset %d" % i)
        if "{" in text[brace + 1:end]:
            raise BuildError("css: nested block near offset %d (only @keyframes may nest)" % i)
        return brace, end

    i, n = 0, len(text)
    while True:
        i = skip_space(i)
        if i >= n:
            break
        if text.startswith("@define", i):
            semi = text.find(";", i)
            if semi < 0:
                raise BuildError("css: @define without ';' near offset %d" % i)
            mark(i)
            emit(" ".join(text[i:semi].split()) + ";")
            i = semi + 1
            continue
        if text.startswith("@keyframes", i):
            open_at = text.find("{", i)
            name = text[i + len("@keyframes"):open_at].strip() if open_at > 0 else ""
            if not re.match(r"^(['\"])[\w\-]+\1$|^[\w\-]+$", name):
                raise BuildError("css: bad @keyframes name near offset %d" % i)
            if name[0] not in "'\"":
                name = "'%s'" % name
            mark(i)
            emit("@keyframes %s{" % name)
            j = open_at + 1
            while True:
                j = skip_space(j)
                if j >= n:
                    raise BuildError("css: unclosed @keyframes %s" % name)
                if text[j] == "}":
                    j += 1
                    break
                brace, end = block(j)
                mark(j)
                emit(",".join(" ".join(s.split()) for s in text[j:brace].split(",")) + "{")
                declarations(brace + 1, end)
                emit("}")
                j = end + 1
            mark(i)
            emit("}")
            i = j
            continue
        if imports and text.startswith("@import", i):
            semi = text.find(";", i)
            if semi < 0:
                raise BuildError("css: @import without ';' near offset %d" % i)
            mark(i)
            emit(" ".join(text[i:semi].split()) + ";")
            i = semi + 1
            continue
        if text[i] == "@":
            raise BuildError("css: %s is not supported (include stylesheets from the layout instead)"
                             % text[i:i + 12].split()[0])
        brace, end = block(i)
        mark(i)
        emit(",".join(" ".join(s.split()) for s in text[i:brace].split(",")) + "{")
        declarations(brace + 1, end)
        mark(i)
        emit("}")
        i = end + 1
    return "".join(out), smap


def compile_css(template, src, res, imports=False):
    """A stylesheet resource like `template` with `src` as its CSS. Blocks other than RED2, DATA and SrMa
    (the game's own stylesheets have RERL, the images they use) are kept as they are."""
    version, blocks = resource.read_blocks(template)
    names = [n for n, _ in blocks]
    if not {b"RED2", b"DATA", b"SrMa"} <= set(names) or not set(names) <= {b"RERL", b"RED2", b"DATA", b"SrMa"}:
        raise BuildError("unexpected stylesheet template blocks %r; the style format changed" % names)
    text, smap = minify_css(src, imports)
    red = copy.deepcopy(kv3.loads(dict(blocks)[b"RED2"]))
    red["m_InputDependencies"] = objs([
        input_dep(res + ".css", zlib.crc32(src.encode("utf-8")), True),
        input_dep(res + ".vcss", 0, False),
    ])
    rows = [kv3.Typed(kv3.ARRAY_TYPE_AUXILIARY_BUFFER, r, 0, (kv3.INT32, 0)) for r in smap]
    outer = kv3.ARRAY_TYPE_BYTE_LENGTH if len(rows) <= 255 else kv3.ARRAY_TYPED
    srma = {"DBITSLC": kv3.Typed(outer, rows, 0, (kv3.ARRAY_TYPE_AUXILIARY_BUFFER, 0))}
    data = struct.pack("<IH", zlib.crc32(src.encode("utf-8")), 0) + text.encode("utf-8")
    new = {b"RED2": kv3.dumps(red), b"DATA": data, b"SrMa": kv3.dumps(srma)}
    return resource.write_blocks(version, [(n, new.get(n, body)) for n, body in blocks])


def patch_defines(body, values):
    """The game stylesheet `body` with new values for some of its @define constants; (body, {name: old value})
    for the ones it defines, (None, {}) if it defines none of them.

    The game resolves names like `sans` or `offWhite` from these constants in every stylesheet that uses them,
    so one changed value restyles the whole UI. The change is made in place and keeps every byte where it was:
    DATA starts with a table of the images the stylesheet uses (count in the header, then per image a
    NUL-terminated path and two 32-bit values) and SrMa maps byte offsets of the CSS, so the new value is
    padded to the old length with spaces after the colon, which CSS skips. Values can't be longer than the
    game's own."""
    version, blocks = resource.read_blocks(body)
    data = dict(blocks).get(b"DATA")
    if data is None or len(data) < 6:
        raise BuildError("stylesheet without a DATA block; the style format changed")
    out, old, last = bytearray(data[:6]), {}, 6
    pattern = rb"@define\s+(%s)\s*:([^;{}]*);" % b"|".join(re.escape(n.encode("ascii")) for n in sorted(values))
    for m in re.finditer(pattern, data[6:]):
        name = m.group(1).decode("ascii")
        start, end = m.start(2) + 6, m.end(2) + 6
        new = values[name].encode("utf-8")
        if len(new) + 1 > end - start:
            raise BuildError("defines: %s %r is longer than the game's value %r (at most %d characters)"
                             % (name, values[name], data[start:end].strip().decode("utf-8", "replace"), end - start - 1))
        out += data[last:start] + b" " * (end - start - len(new)) + new
        last = end
        old[name] = data[start:end].strip().decode("utf-8", "replace")
    if not old:
        return None, {}
    out += data[last:]
    if len(out) != len(data):
        raise BuildError("defines: the patched stylesheet changed size")
    return resource.write_blocks(version, [(n, bytes(out) if n == b"DATA" else b) for n, b in blocks]), old


def compile_js(src, res):
    def special(s, fp):
        return {"m_String": s, "m_CompilerIdentifier": "CompileJavaScript",
                "m_nFingerprint": num(fp), "m_nUserData": num(0)}

    red = {
        "m_InputDependencies": objs([
            input_dep(res + ".js", zlib.crc32(src.encode("utf-8")), True),
            input_dep(res + ".vjs", 0, False),
        ]),
        "m_AdditionalInputDependencies": [],
        "m_ArgumentDependencies": objs([{
            "m_ParameterName": "___OverrideInputData___", "m_ParameterType": "BinaryBlobArg",
            "m_nFingerprint": num(0), "m_nFingerprintDefault": num(0)}]),
        "m_SpecialDependencies": objs([special("JavaScript Compiler Version", 4),
                                       special("Panorama Preprocessor Presence/Version", 0)]),
        "m_AdditionalRelatedFiles": [],
        "m_ChildResourceList": [],
        "m_WeakReferenceList": [],
        "m_SearchableUserData": {"IsChildResource": num(0)},
        "m_SubassetReferences": None,
        "m_SubassetDefinitions": None,
    }
    return resource.write_blocks((12, 4), [(b"RED2", kv3.dumps(red)), (b"DATA", src.encode("utf-8"))])




def compile_svg(template, src, res, search_path=None, source_crc=None):
    """Compile SVG text into a .vsvg_c, using a game .vsvg_c for the resource metadata.

    DATA is crc32(source) + 2 zero bytes + the SVG text, as in the game's own icons.
    """
    version, blocks = resource.read_blocks(template)
    names = [n for n, _ in blocks]
    if names != [b"RED2", b"DATA"]:
        raise BuildError("unexpected vector graphic template blocks %r; the format changed" % names)
    red = copy.deepcopy(kv3.loads(dict(blocks)[b"RED2"]))
    deps = red["m_InputDependencies"]
    rows = deps.v if isinstance(deps, kv3.Typed) else deps
    if not rows:
        raise BuildError("vector graphic template has no input dependency")
    row = rows[0]
    row["m_RelativeFilename"] = res + ".svg"
    if search_path is not None:
        row["m_SearchPath"] = search_path
    # m_nFileCRC is the CRC of the .svg file on disk; DATA carries the CRC of the text itself.
    row["m_nFileCRC"] = source_crc if source_crc is not None else num(zlib.crc32(src.encode("utf-8")))
    data = struct.pack("<IH", zlib.crc32(src.encode("utf-8")), 0) + src.encode("utf-8")
    return resource.write_blocks(version, [(b"RED2", kv3.dumps(red)), (b"DATA", data)])

