#!/usr/bin/env python3
"""Binary KeyValues3 (version 5) reader/writer, enough for Panorama 'LaCo' blocks.

Values decode to plain Python: dict, list, str, bool, None, int, float.
Typed leaf detail that matters for byte-exact re-encoding is kept in small
wrapper classes (see Typed).
"""
import struct

MAGIC5 = b"\x05\x33\x56\x4b"
FORMAT_GENERIC = bytes.fromhex("7c161274e9069846aff2e63eb59037e7")
TRAILER = 0xFFEEDD00

(NULL, BOOLEAN, INT64, UINT64, DOUBLE, STRING, BINARY_BLOB, ARRAY, OBJECT, ARRAY_TYPED,
 INT32, UINT32, BOOLEAN_TRUE, BOOLEAN_FALSE, INT64_ZERO, INT64_ONE, DOUBLE_ZERO, DOUBLE_ONE,
 FLOAT, INT16, UINT16, UNKNOWN_22, INT32_AS_BYTE, ARRAY_TYPE_BYTE_LENGTH,
 ARRAY_TYPE_AUXILIARY_BUFFER) = range(1, 26)


class Typed:
    """A leaf or array whose exact binary node type should be preserved."""
    __slots__ = ("t", "v", "flag", "sub")

    def __init__(self, t, v, flag=0, sub=None):
        self.t, self.v, self.flag, self.sub = t, v, flag, sub

    def __repr__(self):
        return "Typed(%d,%r%s%s)" % (self.t, self.v, ",flag=%d" % self.flag if self.flag else "",
                                     ",sub=%r" % (self.sub,) if self.sub else "")

    def __eq__(self, o):
        return isinstance(o, Typed) and (self.t, self.v, self.flag, self.sub) == (o.t, o.v, o.flag, o.sub)


def plain(v):
    """Strip Typed wrappers."""
    if isinstance(v, Typed):
        return plain(v.v)
    if isinstance(v, dict):
        return {k: plain(x) for k, x in v.items()}
    if isinstance(v, list):
        return [plain(x) for x in v]
    return v


# ---------------------------------------------------------------- LZ4 block

def lz4_decompress(src, out_size):
    out = bytearray()
    i, n = 0, len(src)
    while i < n:
        tok = src[i]; i += 1
        lit = tok >> 4
        if lit == 15:
            while True:
                b = src[i]; i += 1
                lit += b
                if b != 255:
                    break
        out += src[i:i + lit]; i += lit
        if i >= n:
            break
        off = src[i] | (src[i + 1] << 8); i += 2
        ml = tok & 15
        if ml == 15:
            while True:
                b = src[i]; i += 1
                ml += b
                if b != 255:
                    break
        ml += 4
        start = len(out) - off
        if off >= ml:
            out += out[start:start + ml]
        else:
            for k in range(ml):
                out.append(out[start + k])
    if len(out) != out_size:
        raise ValueError("lz4: expected %d bytes, got %d" % (out_size, len(out)))
    return bytes(out)


def lz4_compress(src):
    """Greedy LZ4 block compressor (hash chain-less, single candidate)."""
    n = len(src)
    out = bytearray()
    table = {}
    i = 0
    anchor = 0
    limit = n - 12  # last match must start before the final 12 bytes
    end_literals = n - 5

    def emit(lit_start, lit_end, mlen, off):
        lit = lit_end - lit_start
        tok_l = 15 if lit >= 15 else lit
        if mlen is None:
            out.append(tok_l << 4)
        else:
            m = mlen - 4
            out.append((tok_l << 4) | (15 if m >= 15 else m))
        if lit >= 15:
            r = lit - 15
            while r >= 255:
                out.append(255); r -= 255
            out.append(r)
        out.extend(src[lit_start:lit_end])
        if mlen is not None:
            out.append(off & 255); out.append(off >> 8)
            m = mlen - 4
            if m >= 15:
                r = m - 15
                while r >= 255:
                    out.append(255); r -= 255
                out.append(r)

    while i < limit:
        key = src[i:i + 4]
        cand = table.get(key)
        table[key] = i
        if cand is not None and i - cand <= 65535:
            ml = 4
            while i + ml < end_literals and src[cand + ml] == src[i + ml]:
                ml += 1
            emit(anchor, i, ml, i - cand)
            i += ml
            anchor = i
        else:
            i += 1
    emit(anchor, n, None, 0)
    return bytes(out)


def zstd_decompress(src):
    """Zstandard via node's built-in zlib (python 3.10 has no zstd)."""
    import subprocess
    r = subprocess.run(["node", "-e",
                        "const c=[];process.stdin.on('data',d=>c.push(d)).on('end',()=>"
                        "process.stdout.write(require('zlib').zstdDecompressSync(Buffer.concat(c))))"],
                       input=src, capture_output=True, check=True)
    return r.stdout


# ---------------------------------------------------------------- reader

class _Lanes:
    def __init__(self):
        self.b1 = self.b2 = self.b4 = self.b8 = b""
        self.p1 = self.p2 = self.p4 = self.p8 = 0

    def u8(self):
        v = self.b1[self.p1]; self.p1 += 1; return v

    def rd(self, fmt, lane):
        size = struct.calcsize(fmt)
        if lane == 2:
            v = struct.unpack_from(fmt, self.b2, self.p2)[0]; self.p2 += size
        elif lane == 4:
            v = struct.unpack_from(fmt, self.b4, self.p4)[0]; self.p4 += size
        else:
            v = struct.unpack_from(fmt, self.b8, self.p8)[0]; self.p8 += size
        return v

    def done(self):
        return (self.p1 == len(self.b1) and self.p2 == len(self.b2)
                and self.p4 == len(self.b4) and self.p8 == len(self.b8))


def _align(o, a):
    return (o + a - 1) // a * a


def parse_header(data):
    if data[:4] != MAGIC5:
        raise ValueError("not KV3 v5: %r" % data[:4])
    names = ("compression dict frame c1 c4 c8 ctypes cobjects carrays usize csize cblocks blobbytes "
             "c2 blocksizes u1 z1 u2 z2 c1b c2b c4b c8b unk13 cobjects2 carrays2 unk16").split()
    vals = struct.unpack_from("<IHHiiiiHHiiiiiiiiiiiiiiiiii", data, 20)
    h = dict(zip(names, vals))
    h["format"] = data[4:20]
    h["_end"] = 20 + struct.calcsize("<IHHiiiiHHiiiiiiiiiiiiiiiiii")
    return h


def raw_buffers(data):
    h = parse_header(data)
    pos = h["_end"]
    if h["compression"] == 0:
        b1 = data[pos:pos + h["u1"]]; pos += h["u1"]
        b2 = data[pos:pos + h["u2"]]; pos += h["u2"]
    elif h["compression"] == 1:
        b1 = lz4_decompress(data[pos:pos + h["z1"]], h["u1"]); pos += h["z1"]
        b2 = lz4_decompress(data[pos:pos + h["z2"]], h["u2"]); pos += h["z2"]
    elif h["compression"] == 2:
        b1 = zstd_decompress(data[pos:pos + h["z1"]]); pos += h["z1"]
        b2 = zstd_decompress(data[pos:pos + h["z2"]]); pos += h["z2"]
    else:
        raise ValueError("unsupported compression %d" % h["compression"])
    if h["cblocks"]:
        raise ValueError("binary blobs not supported")
    return h, b1, b2


def loads(data):
    h, b1, b2 = raw_buffers(data)
    aux = _Lanes()
    o = 0
    aux.b1 = b1[o:o + h["c1"]]; o += h["c1"]
    if h["c2"]:
        o = _align(o, 2); aux.b2 = b1[o:o + h["c2"] * 2]; o += h["c2"] * 2
    if h["c4"]:
        o = _align(o, 4); aux.b4 = b1[o:o + h["c4"] * 4]; o += h["c4"] * 4
    if h["c8"]:
        o = _align(o, 8); aux.b8 = b1[o:o + h["c8"] * 8]; o += h["c8"] * 8
    assert o == len(b1), (o, len(b1))
    nstr = aux.rd("<i", 4)
    strings = []
    for _ in range(nstr):
        e = aux.b1.index(b"\0", aux.p1)
        strings.append(aux.b1[aux.p1:e].decode("utf-8")); aux.p1 = e + 1

    main = _Lanes()
    o = h["cobjects2"] * 4
    objlens = list(struct.unpack_from("<%di" % h["cobjects2"], b2, 0))
    main.b1 = b2[o:o + h["c1b"]]; o += h["c1b"]
    if h["c2b"]:
        o = _align(o, 2); main.b2 = b2[o:o + h["c2b"] * 2]; o += h["c2b"] * 2
    if h["c4b"]:
        o = _align(o, 4); main.b4 = b2[o:o + h["c4b"] * 4]; o += h["c4b"] * 4
    if h["c8b"]:
        o = _align(o, 8); main.b8 = b2[o:o + h["c8b"] * 8]; o += h["c8b"] * 8
    types = b2[o:o + h["ctypes"]]; o += h["ctypes"]
    assert struct.unpack_from("<I", b2, o)[0] == TRAILER
    assert o + 4 == len(b2), (o, len(b2))

    st = {"tp": 0, "op": 0, "buf": main, "aux": aux}

    def rtype():
        t = types[st["tp"]]; st["tp"] += 1
        flag = 0
        if t & 0x80:
            t &= 0x3F
            flag = types[st["tp"]]; st["tp"] += 1
        return t, flag

    def sid(buf):
        i = buf.rd("<i", 4)
        return "" if i == -1 else strings[i]

    def value(t, flag):
        buf = st["buf"]
        if t == STRING:
            s = sid(buf)
            return Typed(STRING, s, flag) if flag else s
        if t == OBJECT:
            n = objlens[st["op"]]; st["op"] += 1
            d = {}
            for _ in range(n):
                ct, cf = rtype()
                key = sid(st["buf"])
                d[key] = value(ct, cf)
            return d
        if t == ARRAY:
            n = buf.rd("<i", 4)
            out = []
            for _ in range(n):
                ct, cf = rtype()
                out.append(value(ct, cf))
            return out
        if t in (ARRAY_TYPED, ARRAY_TYPE_BYTE_LENGTH, ARRAY_TYPE_AUXILIARY_BUFFER):
            n = buf.u8() if t != ARRAY_TYPED else buf.rd("<i", 4)
            ct, cf = rtype()
            if t == ARRAY_TYPE_AUXILIARY_BUFFER:
                st["buf"], st["aux"] = st["aux"], st["buf"]
            items = [value(ct, cf) for _ in range(n)]
            if t == ARRAY_TYPE_AUXILIARY_BUFFER:
                st["buf"], st["aux"] = st["aux"], st["buf"]
            if ct not in (OBJECT, ARRAY, ARRAY_TYPED, ARRAY_TYPE_BYTE_LENGTH, ARRAY_TYPE_AUXILIARY_BUFFER):
                items = [x.v if isinstance(x, Typed) else x for x in items]  # element type lives in sub
            return Typed(t, items, flag, (ct, cf))
        if t == NULL: return None
        if t == BOOLEAN_TRUE: return True
        if t == BOOLEAN_FALSE: return False
        if t == BOOLEAN: return Typed(t, buf.u8() == 1, flag)
        if t == INT64_ZERO: return Typed(t, 0, flag)
        if t == INT64_ONE: return Typed(t, 1, flag)
        if t == DOUBLE_ZERO: return Typed(t, 0.0, flag)
        if t == DOUBLE_ONE: return Typed(t, 1.0, flag)
        if t == INT32_AS_BYTE: return Typed(t, buf.u8(), flag)
        if t == INT16: return Typed(t, buf.rd("<h", 2), flag)
        if t == UINT16: return Typed(t, buf.rd("<H", 2), flag)
        if t == INT32: return Typed(t, buf.rd("<i", 4), flag)
        if t == UINT32: return Typed(t, buf.rd("<I", 4), flag)
        if t == FLOAT: return Typed(t, buf.rd("<f", 4), flag)
        if t == INT64: return Typed(t, buf.rd("<q", 8), flag)
        if t == UINT64: return Typed(t, buf.rd("<Q", 8), flag)
        if t == DOUBLE: return Typed(t, buf.rd("<d", 8), flag)
        raise ValueError("unknown KV3 node type %d" % t)

    t, f = rtype()
    root = value(t, f)
    assert st["tp"] == len(types) and st["op"] == len(objlens), "trailing type/object data"
    assert main.done() and aux.done(), "trailing lane data"
    return root


# ---------------------------------------------------------------- writer

class _Out:
    def __init__(self):
        self.b1 = bytearray(); self.b2 = bytearray(); self.b4 = bytearray(); self.b8 = bytearray()


def build_buffers(root):
    """Encode a tree into the two uncompressed v5 buffers. Returns (header_fields, buf1, buf2)."""
    strings = {}
    main, aux = _Out(), _Out()
    types = bytearray()
    objlens = bytearray()
    st = {"buf": main, "aux": aux}
    cnt = dict(objects=0, arrays=0, arrays_main=0, members=0, main_elems=0)

    def sid(s):
        if s == "":
            return -1
        if s not in strings:
            strings[s] = len(strings)
        return strings[s]

    def wtype(t, flag=0):
        if flag:
            types.append(t | 0x80); types.append(flag)
        else:
            types.append(t)

    def node_type(v):
        if isinstance(v, Typed): return v.t, v.flag
        if isinstance(v, str): return STRING, 0
        if isinstance(v, dict): return OBJECT, 0
        if isinstance(v, list): return ARRAY, 0
        if v is None: return NULL, 0
        if v is True: return BOOLEAN_TRUE, 0
        if v is False: return BOOLEAN_FALSE, 0
        raise TypeError("wrap numbers in kv3.Typed: %r" % (v,))

    def wvalue(v, t):
        buf = st["buf"]
        if t == STRING:
            buf.b4 += struct.pack("<i", sid(v.v if isinstance(v, Typed) else v))
        elif t == OBJECT:
            cnt["objects"] += 1; cnt["members"] += len(v)
            objlens.extend(struct.pack("<i", len(v)))
            for k, x in v.items():
                ct, cf = node_type(x)
                wtype(ct, cf)
                st["buf"].b4 += struct.pack("<i", sid(k))
                wvalue(x, ct)
        elif t == ARRAY:
            cnt["arrays"] += 1; cnt["arrays_main"] += 1; cnt["main_elems"] += max(len(v), 1)
            buf.b4 += struct.pack("<i", len(v))
            for x in v:
                ct, cf = node_type(x)
                wtype(ct, cf)
                wvalue(x, ct)
        elif t in (ARRAY_TYPED, ARRAY_TYPE_BYTE_LENGTH, ARRAY_TYPE_AUXILIARY_BUFFER):
            cnt["arrays"] += 1
            items = v.v
            if t == ARRAY_TYPED:
                buf.b4 += struct.pack("<i", len(items))
            else:
                if len(items) > 255:
                    raise ValueError("byte-length array with %d items" % len(items))
                buf.b1.append(len(items))
            ct, cf = v.sub
            wtype(ct, cf)
            if t == ARRAY_TYPE_AUXILIARY_BUFFER:
                st["buf"], st["aux"] = st["aux"], st["buf"]
            else:
                cnt["arrays_main"] += 1; cnt["main_elems"] += max(len(items), 1)
            for x in items:
                wvalue(x, ct)
            if t == ARRAY_TYPE_AUXILIARY_BUFFER:
                st["buf"], st["aux"] = st["aux"], st["buf"]
        elif t in (NULL, BOOLEAN_TRUE, BOOLEAN_FALSE, INT64_ZERO, INT64_ONE, DOUBLE_ZERO, DOUBLE_ONE):
            pass
        else:
            x = v.v if isinstance(v, Typed) else v
            if t == BOOLEAN: buf.b1.append(1 if x else 0)
            elif t == INT32_AS_BYTE: buf.b1.append(x)
            elif t == INT16: buf.b2 += struct.pack("<h", x)
            elif t == UINT16: buf.b2 += struct.pack("<H", x)
            elif t == INT32: buf.b4 += struct.pack("<i", x)
            elif t == UINT32: buf.b4 += struct.pack("<I", x)
            elif t == FLOAT: buf.b4 += struct.pack("<f", x)
            elif t == INT64: buf.b8 += struct.pack("<q", x)
            elif t == UINT64: buf.b8 += struct.pack("<Q", x)
            elif t == DOUBLE: buf.b8 += struct.pack("<d", x)
            else: raise ValueError("cannot write node type %d" % t)

    t, f = node_type(root)
    wtype(t, f)
    wvalue(root, t)

    strbytes = b"".join(s.encode("utf-8") + b"\0" for s in strings)
    aux_b1 = strbytes + bytes(aux.b1)
    aux_b4 = struct.pack("<i", len(strings)) + bytes(aux.b4)

    def lanes(prefix, b1, b2, b4, b8):
        out = bytearray(prefix)
        out += b1
        if b2:
            out += b"\0" * ((-len(out)) % 2); out += b2
        if b4:
            out += b"\0" * ((-len(out)) % 4); out += b4
        if b8:
            out += b"\0" * ((-len(out)) % 8); out += b8
        return out

    buf1 = bytes(lanes(b"", aux_b1, aux.b2, aux_b4, aux.b8))
    buf2 = lanes(objlens, main.b1, main.b2, main.b4, main.b8)
    buf2 += types
    buf2 += struct.pack("<I", TRAILER)
    buf2 = bytes(buf2)
    h = dict(c1=len(aux_b1), c2=len(aux.b2) // 2, c4=len(aux_b4) // 4, c8=len(aux.b8) // 8,
             ctypes=len(types), cobjects=min(cnt["objects"], 65535), carrays=min(cnt["arrays"], 65535),
             c1b=len(main.b1), c2b=len(main.b2) // 2, c4b=len(main.b4) // 4, c8b=len(main.b8) // 8,
             unk13=cnt["members"] + 1, cobjects2=cnt["objects"], carrays2=cnt["arrays_main"],
             unk16=cnt["main_elems"], u1=len(buf1), u2=len(buf2))
    return h, buf1, buf2


def dumps(root, compress=True, fmt=FORMAT_GENERIC):
    h, buf1, buf2 = build_buffers(root)
    if compress:
        z1, z2 = lz4_compress(buf1), lz4_compress(buf2)
        assert lz4_decompress(z1, len(buf1)) == buf1 and lz4_decompress(z2, len(buf2)) == buf2
        method, frame = 1, 16384
        zs1, zs2, csize = len(z1), len(z2), len(z1) + len(z2)
    else:
        z1, z2 = buf1, buf2
        method, frame = 0, 0
        zs1 = zs2 = 0
        csize = len(buf1) + len(buf2)
    out = bytearray(MAGIC5 + fmt)
    out += struct.pack("<IHHiiiiHHiiiiiiiiiiiiiiiiii", method, 0, frame,
                       h["c1"], h["c4"], h["c8"], h["ctypes"], h["cobjects"], h["carrays"],
                       h["u1"] + h["u2"], csize, 0, 0, h["c2"], 0,
                       h["u1"], zs1, h["u2"], zs2,
                       h["c1b"], h["c2b"], h["c4b"], h["c8b"], h["unk13"], h["cobjects2"],
                       h["carrays2"], h["unk16"])
    out += z1 + z2
    return bytes(out)

