#!/usr/bin/env python3
"""Panorama compiled layout (the 'LaCo' block of a .vxml_c) <-> XML."""
import xml.parsers.expat
from xml.sax.saxutils import quoteattr

import kv3

REF_PREFIX = {"REFERENCE_COMPILED": "s2r://", "REFERENCE_PASSTHROUGH": "file://"}
CONTAINER_TAGS = {"ROOT": "root", "STYLES": "styles", "SCRIPTS": "scripts", "SNIPPETS": "snippets"}
TAG_TYPES = {v: k for k, v in CONTAINER_TAGS.items()}
LC_ATTR = "__lc"  # test-only attribute carrying an explicit source line/column


def _subnodes(node):
    if "vecChildren" in node:
        return node["vecChildren"].v
    if "child" in node:
        return [node["child"]]
    return []


def _attr_value(v):
    t = v["eType"]
    name = v.get("name", "")
    if t in REF_PREFIX:
        return REF_PREFIX[t] + name
    if t == "PANEL_ATTRIBUTE_VALUE":
        return name
    raise ValueError("unknown value node " + t)


def to_xml(root_kv, annotate=False):
    """Render the layout tree as XML. annotate=True embeds original line/column for exact round trips."""
    out = []

    def emit(node, depth):
        ind = "\t" * depth
        t = node["eType"]
        lc = ""
        slc = node.get("sourceLineColumn")
        if annotate and isinstance(slc, kv3.Typed):
            lc = ' %s="%d,%d"' % (LC_ATTR, slc.v[0], slc.v[1])
        if t == "INCLUDE":
            out.append("%s<include src=%s%s />" % (ind, quoteattr(_attr_value(node["child"])), lc))
            return
        if t == "SCRIPT_BODY":
            out.append("%s<script><![CDATA[%s]]></script>" % (ind, node["name"]))
            return
        subs = _subnodes(node)
        attrs = [s for s in subs if s["eType"] == "PANEL_ATTRIBUTE"]
        kids = [s for s in subs if s["eType"] != "PANEL_ATTRIBUTE"]
        if t == "PANEL":
            tag = node["name"]
        elif t == "SNIPPET":
            tag = "snippet"
        elif t in CONTAINER_TAGS:
            tag = CONTAINER_TAGS[t]
        else:
            raise ValueError("unknown node type " + t)
        s = "%s<%s" % (ind, tag)
        if t == "SNIPPET":
            s += " name=%s" % quoteattr(node["name"])
        for a in attrs:
            s += " %s=%s" % (a["name"], quoteattr(_attr_value(a["child"])))
        s += lc
        if not kids:
            out.append(s + " />")
            return
        out.append(s + ">")
        for k in kids:
            emit(k, depth + 1)
        out.append("%s</%s>" % (ind, tag))

    emit(root_kv["m_AST"]["m_pRoot"], 0)
    return "\n".join(out) + "\n"


def _value_node(value):
    for etype, prefix in REF_PREFIX.items():
        if value.startswith(prefix):
            return {"eType": etype, "name": value[len(prefix):]}
    node = {"eType": "PANEL_ATTRIBUTE_VALUE"}
    if value != "":
        node["name"] = value
    return node


def _finish(node, subs, lc):
    if len(subs) == 1:
        node["child"] = subs[0]
    elif subs:
        node["vecChildren"] = kv3.Typed(kv3.ARRAY_TYPE_BYTE_LENGTH, subs, 0, (kv3.OBJECT, 0))
    if lc is None:
        node["sourceLineColumn"] = []
    else:
        node["sourceLineColumn"] = kv3.Typed(kv3.ARRAY_TYPE_AUXILIARY_BUFFER, list(lc), 0, (kv3.INT32, 0))
    return node


def from_xml(text):
    """Compile layout XML into the KV3 tree stored in a LaCo block."""
    parser = xml.parsers.expat.ParserCreate()
    parser.ordered_attributes = True
    stack = []   # (node, subs, lc, kind)
    result = []

    def start(tag, attrs):
        pairs = list(zip(attrs[0::2], attrs[1::2]))
        lc = (parser.CurrentLineNumber, parser.CurrentColumnNumber + 2)
        for k, v in pairs:
            if k == LC_ATTR:
                lc = tuple(int(x) for x in v.split(","))
        pairs = [(k, v) for k, v in pairs if k != LC_ATTR]
        parent_kind = stack[-1][3] if stack else None
        subs = []
        if parent_kind is None:
            if tag != "root":
                raise ValueError("layout must start with <root>")
            node, kind, lc = {"eType": "ROOT"}, "ROOT", None
        elif parent_kind == "ROOT" and tag in ("styles", "scripts", "snippets"):
            kind = TAG_TYPES[tag]
            node = {"eType": kind}
        elif parent_kind in ("STYLES", "SCRIPTS") and tag == "include":
            kind = "INCLUDE"
            node = {"eType": "INCLUDE"}
            subs.append(_value_node(dict(pairs)["src"]))
            pairs = []
        elif parent_kind == "SNIPPETS" and tag == "snippet":
            kind = "SNIPPET"
            node = {"eType": "SNIPPET", "name": dict(pairs)["name"]}
            pairs = []
        else:
            kind = "PANEL"
            node = {"eType": "PANEL", "name": tag}
        for k, v in pairs:
            subs.append({"eType": "PANEL_ATTRIBUTE", "name": k, "child": _value_node(v)})
        stack.append((node, subs, lc, kind))

    def end(tag):
        node, subs, lc, kind = stack.pop()
        _finish(node, subs, lc)
        if stack:
            stack[-1][1].append(node)
        else:
            result.append(node)

    def chars(data):
        if data.strip():
            raise ValueError("unexpected text in layout: %r" % data.strip()[:40])

    parser.StartElementHandler = start
    parser.EndElementHandler = end
    parser.CharacterDataHandler = chars
    parser.Parse(text, True)
    return {"m_AST": {"m_pRoot": result[0]}}

