#!/usr/bin/env python3
"""Minimal Valve VPK (v2) reader/writer. No dependencies.

Usage:
  vpk.py list    <pak_dir.vpk> [substring]
  vpk.py extract <pak_dir.vpk> <outdir> [substring ...]
  vpk.py pack    <srcdir> <out_dir.vpk>
"""
import hashlib
import os
import struct
import sys
import zlib

SIG = 0x55AA1234


def read_cstr(buf, pos):
    end = buf.index(b"\0", pos)
    return buf[pos:end].decode("utf-8", "replace"), end + 1


def read_index(path):
    """Return (entries, data_base). entries: {fullpath: dict}."""
    with open(path, "rb") as f:
        head = f.read(28)
        sig, ver, tree_size = struct.unpack_from("<III", head, 0)
        if sig != SIG:
            raise ValueError("not a VPK: %s" % path)
        if ver == 2:
            header_size = 28
        elif ver == 1:
            header_size = 12
        else:
            raise ValueError("unsupported VPK version %d" % ver)
        f.seek(header_size)
        tree = f.read(tree_size)
    entries = {}
    pos = 0
    while True:
        ext, pos = read_cstr(tree, pos)
        if not ext:
            break
        while True:
            d, pos = read_cstr(tree, pos)
            if not d:
                break
            while True:
                name, pos = read_cstr(tree, pos)
                if not name:
                    break
                crc, preload, arch, off, length, term = struct.unpack_from("<IHHIIH", tree, pos)
                pos += 18
                pre = tree[pos:pos + preload]
                pos += preload
                full = name if ext == " " else name + "." + ext
                if d != " ":
                    full = d + "/" + full
                entries[full] = dict(crc=crc, preload=pre, archive=arch, offset=off, length=length)
    return entries, header_size + tree_size


def read_file(path, entry, data_base):
    data = entry["preload"]
    if entry["length"]:
        if entry["archive"] == 0x7FFF:
            src, off = path, data_base + entry["offset"]
        else:
            src = path[:-len("dir.vpk")] + "%03d.vpk" % entry["archive"]
            off = entry["offset"]
        with open(src, "rb") as f:
            f.seek(off)
            data += f.read(entry["length"])
    return data


def pack(srcdir, out):
    files = []
    for root, _, names in os.walk(srcdir):
        for n in names:
            full = os.path.join(root, n)
            rel = os.path.relpath(full, srcdir).replace(os.sep, "/")
            files.append((rel, full))
    files.sort()
    tree = {}
    blob = bytearray()
    for rel, full in files:
        with open(full, "rb") as f:
            data = f.read()
        d, _, base = rel.rpartition("/")
        name, _, ext = base.rpartition(".")
        if not name:
            name, ext = ext, " "
        tree.setdefault(ext, {}).setdefault(d or " ", []).append((name, zlib.crc32(data) & 0xFFFFFFFF, len(blob), len(data)))
        blob += data
    t = bytearray()
    for ext, dirs in tree.items():
        t += ext.encode() + b"\0"
        for d, items in dirs.items():
            t += d.encode() + b"\0"
            for name, crc, off, length in items:
                t += name.encode() + b"\0"
                t += struct.pack("<IHHIIH", crc, 0, 0x7FFF, off, length, 0xFFFF)
            t += b"\0"
        t += b"\0"
    t += b"\0"
    body = struct.pack("<IIIIIII", SIG, 2, len(t), len(blob), 0, 48, 0) + bytes(t) + bytes(blob)
    tree_md5 = hashlib.md5(bytes(t)).digest()
    arch_md5 = hashlib.md5(b"").digest()  # no per-archive checksum section
    whole_md5 = hashlib.md5(body + tree_md5 + arch_md5).digest()
    with open(out, "wb") as f:
        f.write(body + tree_md5 + arch_md5 + whole_md5)
    return len(files)


def main(argv):
    if len(argv) < 3:
        print(__doc__)
        return 1
    cmd = argv[1]
    if cmd == "list":
        entries, _ = read_index(argv[2])
        sub = argv[3] if len(argv) > 3 else ""
        for k in sorted(entries):
            if sub in k:
                e = entries[k]
                print("%10d  %s" % (e["length"] + len(e["preload"]), k))
    elif cmd == "extract":
        entries, base = read_index(argv[2])
        subs = argv[4:] or [""]
        n = 0
        for k in sorted(entries):
            if any(s in k for s in subs):
                dst = os.path.join(argv[3], k)
                os.makedirs(os.path.dirname(dst) or ".", exist_ok=True)
                with open(dst, "wb") as f:
                    f.write(read_file(argv[2], entries[k], base))
                n += 1
        print("extracted %d files" % n)
    elif cmd == "pack":
        print("packed %d files" % pack(argv[2], argv[3]))
    else:
        print(__doc__)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

