files.theme/ability_hud_elements/element_gun.c:
/* Clean: ammo under the crosshair. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .weapon_ammo
{
	font-size: 22px;
	font-weight: black;
	font-style: italic;
	color: var(--text);
	width: 44px;
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

#Hud .weapon_ammo_max
{
	font-size: 15px;
	font-weight: bold;
	color: #F4F6F8A0;
	margin-top: 6px;
}

files.theme/citadel_hud_ability_upgrade_pips.c:
/* Clean: the ability upgrade pips, each ability's three upgrades and their cost (shown with the scoreboard,
   the detail view or on hover). Flat rounded rows instead of pills and the cost in italic; the colours of
   each state (bought, affordable, too dear) are still the game's. Other panels can hold these pips too
   (the stock styles name the shop's ability slots and a radial menu), so the rules are for the ability
   bar only (#hud_signature). */

#Hud Label
{
	font-family: var(--font);
}

#Hud #hud_signature .abilityUpgradeContainer,
#Hud #hud_signature .upgradeReadyFlash
{
	border-radius: 4px;
}

#Hud #hud_signature .abilityUpgradeCostLabel
{
	font-style: italic;
}

files.theme/citadel_hud_active_player_stats.cs:
/* Clean: weapon, spirit and vitality (above the items): a flat ring in each stat's colour around an
   upright number, instead of the painted emblems. The colours are still the game's: its rules tint
   each ring per stat (wash-color), so only the shape changes. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #HudStatBlock #CoreStats .core_stat .core_bg
{
	background-image: none;
	background-color: #0B0F14A0;
	border: 3px solid var(--text);
	border-radius: 32px;
	width: 64px;
	height: 64px;
	horizontal-align: center;
	vertical-align: center;
	opacity: 1;
}

#Hud #HudStatBlock #CoreStats .statNumber
{
	font-size: 22px;
	font-weight: black;
	font-style: italic;
	transform: none;
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

files.theme/citadel_hud_data_feed_info.css:
/* Clean: one kill feed entry. Dark plates (the game's slanted shapes kept) instead of the team-coloured
   ones, names in the team's colour instead: your team white, enemies red; when spectating the two teams
   in amber and sapphire. Level text, light icons. */

#Hud Label
{
	font-family: var(--font);
}

#Hud CitadelHudInfoFeed
{
	horizontal-align: right;
}

#Hud .unit_bg
{
	background-color: var(--plate);
}

#Hud .personaName
{
	font-size: 15px;
	font-weight: bold;
	letter-spacing: 1px;
	color: var(--text);
	text-shadow: 0px 1px 3px 1.0 #000000c0;
}

#Hud .enemy .personaName
{
	color: var(--danger);
}

#Hud .team_1 .personaName
{
	color: var(--team1);
}

#Hud .team_2 .personaName
{
	color: var(--team2);
}

#Hud .soulBagAmount .personaName
{
	color: var(--good);
}

#Hud .victimContainer .personaName
{
