#Hud .IsBuff.MessageContainer,
#Hud .IsBuff .MessageContainer
{
	border-left: 3px solid var(--text);
}

#Hud #MessageLabel
{
	font-weight: bold;
	color: var(--text);
	text-shadow: none;
}

files.theme/citadel_hud_player_level.css:
/* Clean: the level number beside the souls, black italic. The spirit jar around it keeps the game's
   art: how the game fills it (its height or its image) isn't known, and a flat fill could look full
   whatever the progress. The same layout draws the level in the level rewards panel, so the rule is
