#Hud Label
{
	font-family: var(--font);
}

#Hud #gold_and_ap_container #PlayerLevelNumber
{
	font-size: 30px;
	font-weight: black;
	font-style: italic;
	color: var(--text);
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

/* Clean: the "Boon received" toast at a level up: the title black italic (still in the souls colour),
   the rewards bold and upper case, with shadows instead of glows as it sits over the world. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .LevelUpTitle
{
	font-weight: black;
	font-style: italic;
	letter-spacing: 1px;
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

#Hud .LevelUpTypeLabel
{
	text-transform: uppercase;
	letter-spacing: 1px;
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

files.theme/citadel_hud_pregame_countdown.css:
/* Clean: the countdown before the match starts. A big black italic number in white instead of the green
   gradient, and its caption a bold spaced label. The shrinking animation is the game's. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #PausedCountdownLabel
{
	font-weight: black;
	font-style: italic;
	color: var(--text);
	text-shadow: 0px 4px 16px 1.0 #000000c8;
}

#Hud #PausedLabel
{
	font-weight: bold;
	letter-spacing: 2px;
}

files.theme/citadel_hud_top_bar.css:
/* Clean: the top bar (clock, team souls). Its size is HUD Fit's (inline ui-scale): Clean leaves it. */

#Hud Label
{
	font-family: var(--font);
}

/* The dark gradient behind the bar: the plates carry the contrast instead. */
#Hud #GradientBacker
{
	opacity: 0;
}

#Hud .GameClock
{
	background-color: #0B0F14B8;
	border-radius: 3px;
	padding: 3px 12px;
	margin-top: 6px;
}

#Hud #GameTime
{
	font-size: 20px;
	font-weight: bold;
	color: var(--text);
	width: 90px;
	height: 26px;
	text-align: center;
}

#Hud .ScoreLabel
{
	font-size: 22px;
	font-weight: black;
	font-style: italic;
	color: var(--text);
	text-shadow: 0px 2px 5px 1.0 #000000c0;
}

/* The team souls plates either side of the clock: flat dark plates with the team's colour along the
   bottom, instead of team-coloured brush strokes. */
#Hud .ScoreBG
{
	background-color: #0B0F14B8;
	wash-color: none;
	opacity-mask: url("uikit://solid.vsvg");
	border-radius: 3px;
}

#Hud .team1 .ScoreBG
{
	border-bottom: 3px solid var(--team1);
}

#Hud .team2 .ScoreBG
{
	border-bottom: 3px solid var(--team2);
}

/* The game darkens the amber team's number and icon for its light plate. */
#Hud .team1 .ScoreContainer
{
	wash-color: none;
}

/* Scoreboard (held Tab): the team kills under the clock. Black italic numbers either side of a small spaced
   label, with a shadow as they sit over the world; the game's blur behind each number stays. The players'
   cards are in theme/citadel_hud_top_bar_player.css. */
#Hud .KillsLabel,
#Hud .APLabel
{
	font-weight: black;
	font-style: italic;
	color: var(--text);
	wash-color: none;
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

#Hud .ScoreTypeLabel
{
	font-weight: bold;
	letter-spacing: 1px;
	color: var(--text);
	opacity: 0.6;
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

files.theme/citadel_hud_top_bar_player.css:
/* Clean: one player in the top bar: the portrait, the souls tab under it, the ultimate's status, and the
   dead, low health and disconnected looks. Flat shapes instead of the glowing coin, the tilted framed health
   bar and the team-coloured souls tab (now a dark plate with a thin amber or sapphire edge); Jost numbers.
   The round plate right behind each hero comes from the hero badge's own layout (hero_badge.xml) and keeps
   the game's look. Every state the game shows here still shows. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .SoulsValue
{
	font-weight: bold;
	font-size: 14px;
}

#Hud .RespawnTimer
{
	font-weight: black;
	font-style: italic;
	color: var(--danger);
}

/* Behind your portrait (and the spectated player's, and faintly your lane mate's): a flat, even disc
   instead of the glowing coin that fades towards the top (hence the uniform opacity-brush). The game still
   colours it per state: team, kill streak, low health (flashing), dead. 80 px and lifted 8 px, so it ends
   where the portrait does: the souls number under it stays in full view. */
#Hud .HeroContentsCoinBackground
{
	background-image: none;
	background-color: var(--text);
	width: 80px;
	height: 80px;
	horizontal-align: center;
	vertical-align: bottom;
	margin-bottom: 8px;
	border-radius: 50%;
	opacity-brush: gradient( linear, 0% 0%, 0% 100%, from( #ffffff ), to( #ffffff ) );
}

/* The game brightens the coin threefold for these two: a flat colour would turn almost white. */
#Hud CitadelHudTopBarPlayer.LocalPlayer .HeroContentsCoinBackground,
#Hud CitadelHudTopBarPlayer.SpectatorTarget .HeroContentsCoinBackground
{
	brightness: 1;
}

/* The souls tab under each portrait (its top hides behind the portrait): a dark plate with the team's
   colour along the bottom instead of a team-coloured plate. */
#Hud .SoulsValueContainer
{
	background-color: var(--plate);
	box-shadow: none;
}

#Hud .team1 .SoulsValueContainer
{
	border-bottom: 3px solid var(--team1);
}

#Hud .team2 .SoulsValueContainer
{
	border-bottom: 3px solid var(--team2);
}

/* The tab's states: a gold edge while the player holds the rejuvenator, a mint plate (dark number) during a
   kill streak. */
#Hud .HasRejuvenator .SoulsValueContainer
{
	border-bottom: 3px solid var(--warn);
}

#Hud .KillStreak .SoulsValueContainer
{
	background-color: var(--good);
}

/* The game darkens the amber team's number for its light plate. */
#Hud .team1 .SoulsValue
{
	wash-color: none;
}

#Hud .KillStreak .SoulsValue
{
	wash-color: #0B0F14;
}

/* The small health bar beside a portrait, when the game shows it: a thin upright bar along the portrait's
   outer edge (left on the left-hand team, right on the other), square and unframed, instead of the wide
   tilted, tapered and framed one over the face. Its fill keeps the game's colours. The margins replace the
   game's per-team ones. */
#Hud #PlayerDetailsContainer #HealthBar
{
	transform: none;
	width: 4px;
	margin-left: 2px;
	margin-right: 2px;
}

#Hud #HealthBar_Border
{
	background-image: none;
}

#Hud #HealthBar_Contents
{
	background-color: var(--plate);
	opacity-mask: url("uikit://solid.vsvg");
}

/* Low health: the game's "CRITICAL" tag in red on a dark plate, instead of white with a red glow. */
#Hud #CriticalIndicator Label
{
	font-weight: bold;
	letter-spacing: 1px;
	color: var(--danger);
	background-color: var(--plate);
	border-radius: 3px;
	padding: 1px 4px;
	text-shadow: none;
}

/* The ultimate's status: a small rounded square like Clean's ability icons. The game still fills it with
   the team's colour until the ultimate is ready, then shows the lit icon alone. */
#Hud .UltimateStatus,
#Hud .UltimateStatusBG
{
	border-radius: 4px;
}

/* Dead: the respawn countdown over the dark portrait, with a soft shadow instead of the outline. */
#Hud .DeathStatus .RespawnTimer
{
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

/* Disconnected: a dark plate with a yellow edge and icon instead of the yellow bar; red once the player
   has abandoned. */
#Hud .NetworkStatus
{
	background-color: var(--plate-strong);
	border-left: 3px solid var(--warn);
	border-radius: 3px;
}

#Hud .NetworkIcon
{
	wash-color: var(--warn);
}

#Hud .Abandoned .NetworkStatus
{
	border-left: 3px solid var(--danger);
}

#Hud .Abandoned .NetworkIcon
{
	wash-color: var(--danger);
}

/* The kill streak call-out: a black italic number, both lines in the souls colour (the game's outline stays,
   for the burst behind them). */
#Hud .KillStreakNum
{
	font-weight: black;
	font-style: italic;
	color: var(--good);
}

#Hud .KillStreakLabel
{
	letter-spacing: 1px;
	color: var(--good);
}

/* Scoreboard (held Tab). Each player's card unfolds under the portrait: name, hero, kills, deaths and
   assists, the item graph, health and resists, abilities, items. A dark plate with the team's colour along
   the bottom, like the souls tab, instead of the painted strip; your own card a little lighter. The game's
   blur behind the card stays. Health and resists are in theme/citadel_hud_top_bar_player_details.css. */

/* The strip is the plate (the game shows it at 40 %). The card around it stays see-through until Tab is
   held, so the plate needs no state of its own. */
#Hud #BackgroundStrip
{
	background-image: none;
	background-color: var(--plate-strong);
	border-radius: 4px;
	opacity: 1;
}

#Hud .team1 #BackgroundStrip
{
	border-bottom: 3px solid var(--team1);
}

#Hud .team2 #BackgroundStrip
{
	border-bottom: 3px solid var(--team2);
}

/* The game's blur behind the card, rounded like the plate. */
#Hud #PlayerNameNWContainer
{
	border-radius: 4px;
}

#Hud CitadelHudTopBarPlayer.LocalPlayer #BackgroundStrip
{
	background-color: #1A222CD0;
}

/* The card under the pointer: the game brightens it and lights its name up; every name is lit here, so the
   plate lightens instead. */
#Hud CitadelHudTopBarPlayer:selected #BackgroundStrip
{
	background-color: #252E39D0;
}

#Hud #PlayerNameNWContainer .PlayerName
{
	font-weight: bold;
	color: var(--text);
	opacity: 1;
}

/* Party members' names keep the game's green. */
#Hud .InParty #PlayerNameNWContainer .PlayerName
{
	color: #C8E8B5;
}

#Hud #PlayerNameNWContainer .HeroName
{
	font-weight: bold;
	color: var(--text);
	opacity: 0.6;
}

#Hud #KDAContainer .StatLabel
{
	font-weight: bold;
	text-transform: uppercase;
	color: var(--text);
	opacity: 0.6;
}

/* Kills, deaths, assists: bold italic, deaths and assists dimmer as in the game. Jost's figures are wider
   than the old font's and black ones ran into the next card, so they are bold and a size smaller, with
   less room around the slashes; a row of double figures that still doesn't fit shrinks. */
#Hud #KDAContainer .PlayerStat
{
	font-size: 13px;
	font-weight: bold;
	font-style: italic;
	color: var(--text);
	text-overflow: shrink;
}

#Hud #KDAContainer .ForwardSlash
{
	margin: 2px 1px 0px 1px;
}

#Hud #KDAContainer .PlayerStat.deaths
{
	color: #F4F6F899;
}

#Hud #KDAContainer .PlayerStat.assists
{
	color: #F4F6F8CC;
}

/* Objective damage, when the game shows it. */
#Hud #KDAContainer .objDamageLabel
{
	color: var(--text);
	opacity: 0.6;
}

files.theme/citadel_hud_top_bar_player_details:
/* Clean: maximum health and resists on a player's scoreboard card (held Tab), under the item graph. Jost
   italic numbers like Clean's others: the health black and white, the bullet and spirit resists bold in
   the game's weapon and spirit colours. Only the top bar draws this layout. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #KeyStatPrintout .statNumberLg
{
	font-weight: black;
	font-style: italic;
	color: var(--text);
}

#Hud #KeyStatPrintout .statNumberSm
{
	font-weight: bold;
	font-style: italic;
}

files.theme/citadel_shop_mod_icon.css:
/* Clean: the items in the purchased-items grid at the bottom left. Each slot is a dark rounded plate with
   the item art on it, unchanged and 2 px in from the edge (active items keep their round art). The tier
   corner keeps its category colour. The same layout draws item icons in the shop, the top bar, tooltips
   and the quick-buy queue, so every rule here is for the HUD's grid only (#ModsContainer). */

#Hud Label
{
	font-family: var(--font);
}

#Hud #ModsContainer .mod_icon_single_container
{
	background-color: var(--plate);
	border-radius: 4px;
}

/* Empty slots: a lighter plate (the game still dims them, and draws the lock on locked ones). */
#Hud #ModsContainer .unowned.mod_icon_single_container
{
	background-color: #0B0F1480;
}

/* The art's box, centred in the 45 x 45 slot by the game's rule. */
#Hud #ModsContainer #mod_icon_background
{
	width: 41px;
	height: 41px;
}

files.theme/citadel_shop_mod_view.css:
/* Clean: an item card in the shop (its art, name, tier corner and badges, and the overlays shown on
   hover). A flat dark plate with a 3 px top edge in the item's category colour (weapon, vitality,
   spirit) and a white name, instead of the paper card. The game's states still show: a card you can't
   afford is dimmed by the game and its art greyed (instead of the red wash), owned and used-as-component
   cards stay darker with their check mark and OWNED tag, queued cards keep their badge and outline, and
   the new, imbue, upgrade, enhanced and corrupted marks and the sell and other hover overlays stay. The
   same layout draws the card in tooltips, popups and the build browser, so every rule here is for the
   shop only (#CitadelHudHeroShop). */

#Hud Label
{
	font-family: var(--font);
}

/* No drop shadow, and no red wash on a card you can't afford: the game still dims it (opacity) and its
   art is greyed below. */
#Hud #CitadelHudHeroShop CitadelShopMod
{
	wash-color: none;
	box-shadow: none;
}

/* Disabled items keep the game's dark wash (the rule above outranks it). */
#Hud #CitadelHudHeroShop CitadelShopMod.itemDisabled,
#Hud #CitadelHudHeroShop CitadelShopMod.disabledFromPurchasing
{
	wash-color: #00000060;
}

/* The plate, as wide as the card (the paper was 80 px, cut to the card by its mask), a step lighter than
   the tier and build sections it sits on. Active items keep the game's rounded top. */
#Hud #CitadelHudHeroShop CitadelShopMod #ModCard
{
	width: 100%;
	background-image: none;
	background-color: #1E2630;
	opacity-mask: none;
}

#Hud #CitadelHudHeroShop CitadelShopMod:hover #ModCard
{
	background-color: #2A3440;
}

/* The game still darkens it for owned items (background-color). */
#Hud #CitadelHudHeroShop CitadelShopMod #CardBacker
{
	background-image: none;
}

#Hud #CitadelHudHeroShop CitadelShopMod .paperWear,
#Hud #CitadelHudHeroShop CitadelShopMod .paperTexture,
#Hud #CitadelHudHeroShop CitadelShopMod .paperBevel
{
	visibility: collapse;
}

/* The art without its torn edges, greyed while you can't afford the item. */
#Hud #CitadelHudHeroShop CitadelShopMod #ModIconImage
{
	opacity-mask: none;
	saturation: 0.3;
}

#Hud #CitadelHudHeroShop CitadelShopMod.canAffordMod #ModIconImage,
#Hud #CitadelHudHeroShop CitadelShopMod.owned #ModIconImage,
#Hud #CitadelHudHeroShop CitadelShopMod.usedAsComponent #ModIconImage,
#Hud #CitadelHudHeroShop.gEditingBuilds CitadelShopMod #ModIconImage
{
	saturation: 1;
}

/* The category edge. The art covers the top of the plate, so #CorruptedBorder draws it: an empty panel
   the game doesn't style, laid over the art and over the outline the game draws around queued, owned and
   related cards. Its corners follow the plate's, rounded case by case as the game rounds #ModCard. */
#Hud #CitadelHudHeroShop CitadelShopMod #CorruptedBorder
{
	width: 100%;
	height: 100%;
	ignore-parent-flow: true;
	z-index: 10;
	border-radius: 3px;
}

#Hud #CitadelHudHeroShop CitadelShopMod.isWeapon #CorruptedBorder
{
	border-top: 3px solid #EC9719;
}

#Hud #CitadelHudHeroShop CitadelShopMod.isArmor #CorruptedBorder
{
	border-top: 3px solid #7BBA1D;
}

#Hud #CitadelHudHeroShop CitadelShopMod.isTech #CorruptedBorder
{
	border-top: 3px solid #CE90FF;
}

#Hud #CitadelHudHeroShop CitadelShopMod.isActiveItem #CorruptedBorder
{
	border-radius: 50px 50px 2px 2px;
}

#Hud #CitadelHudHeroShop CitadelShopMod.isActiveItem.quickbuy #CorruptedBorder
{
	border-radius: 2px 40px 2px 2px;
}

#Hud #CitadelHudHeroShop.showingFavorites CitadelShopMod.isActiveItem #CorruptedBorder
{
	border-radius: 40px 2px 2px 2px;
}

#Hud #CitadelHudHeroShop.showingFavorites CitadelShopMod.quickbuy #CorruptedBorder
{
	border-radius: 2px;
}

/* The name, white on the plate. No side padding: long names shrink less (Jost is wider than the game's
   font). */
#Hud #CitadelHudHeroShop CitadelShopMod .modName
{
	color: var(--text);
	font-weight: bold;
	text-shadow: none;
	padding: 0px;
}

/* CAN'T AFFORD (on hover) and OWNED: level labels on a dark band instead of tilted lettering over the
   art. */
#Hud #CitadelHudHeroShop CitadelShopMod .CantAffordLabel
{
	color: var(--danger);
	font-weight: bold;
	letter-spacing: 1px;
	text-shadow: none;
	transform: none;
	background-color: var(--plate-strong);
	border-radius: 2px;
}

#Hud #CitadelHudHeroShop CitadelShopMod #ItemPurchased Label
{
	color: var(--good);
	font-weight: bold;
	letter-spacing: 1px;
	text-shadow: none;
	transform: none;
	background-color: var(--plate-strong);
	border-radius: 2px;
}

/* Imbue: upright on a small dark plate instead of italic in a heavy outline, which ran together at this
   size; the line height fits its 16 px box. */
#Hud #CitadelHudHeroShop CitadelShopMod #ImbueTag
{
	font-style: normal;
	line-height: 16px;
	text-shadow: none;
	background-color: var(--plate-strong);
	border-radius: 2px;
}

/* Hovering an owned item: SELL and the souls you get back, in the souls colour. The line height fits the
   label's 20 px box. */
#Hud #CitadelHudHeroShop CitadelShopMod .SellLabel
{
	line-height: 20px;
	letter-spacing: 1px;
	text-transform: uppercase;
	text-shadow: none;
}

#Hud #CitadelHudHeroShop CitadelShopMod #SellCostAmount
{
	color: var(--good);
	font-style: italic;
}

files.theme/citadel_shop_mods_build.css:
/* Clean: the Builds tab, a hero build in sections of item cards (the sections are in
   theme/citadel_shop_mods_build_category.css). Its header, with the build's name and buttons, becomes a
   faint plate with the name in white, instead of the painted blue strip with black lettering. The build
   browser draws this layout too, so every rule here is for the shop only (#CitadelHudHeroShop). */

#Hud Label
{
	font-family: var(--font);
}

#Hud #CitadelHudHeroShop CitadelShopModsBuild .BuildHeaderShared
{
	background-image: none;
	background-color: #F4F6F80F;
	border-radius: 4px;
}

/* The name in the header only: the list of favourite builds that opens under it keeps its dark names on
   light rows. */
#Hud #CitadelHudHeroShop CitadelShopModsBuild #SelectedBuildOuter .SelectedBuildName
{
	color: var(--text);
}

/* The info icon beside it, light instead of black (the game's brightness and hover stay). */
#Hud #CitadelHudHeroShop CitadelShopModsBuild .BuildDetails
{
	wash-color: var(--text);
}

files.theme/citadel_shop_mods_build_category.c:
/* Clean: one section of a hero build in the Builds tab ("Core Build", "Early", "Late"...): a faint plate
   without a frame or dark title band, its title small, bold and upper case, instead of a framed panel.
   Optional sections keep a light blue tint (the game fills them blue) and their OPTIONAL tag. The frames
   of build editing (the section being edited, where a dragged item will land) are the game's, set again
   here. The build browser draws this layout too, so every rule here is for the shop only
   (#CitadelHudHeroShop). */

#Hud Label
{
	font-family: var(--font);
}

/* The frame stays 2 px wide but see-through, so nothing moves. */
#Hud #CitadelHudHeroShop CitadelShopModsBuildCategory
{
	background-color: #F4F6F80F;
	border: 2px solid #00000000;
	border-radius: 4px;
}

#Hud #CitadelHudHeroShop CitadelShopModsBuildCategory.Optional
{
	background-color: #85B5FF14;
}

/* Build editing: the game's frames, in its order (the rules above outrank them). */
#Hud #CitadelHudHeroShop.gEditingBuilds CitadelShopModsBuildCategory.Focused
{
	border: 2px dashed #D3D3D3;
}

#Hud #CitadelHudHeroShop.gEditingBuilds .FocusedOnMod CitadelShopModsBuildCategory.BuildModCategory.Focused
{
	border: 2px solid #00000000;
}

#Hud #CitadelHudHeroShop .BuildModCategory.DropTarget
{
	border: 2px solid #0000FF;
}

#Hud #CitadelHudHeroShop.gEditingBuilds CitadelShopModsBuildCategory.Focused.DropTarget
{
	border: 2px dashed #0000FF;
}

#Hud #CitadelHudHeroShop CitadelShopModsBuildCategory #BuildCategoryHeader
{
	background-color: #00000000;
}

/* The description a size smaller, so the wider upper case title doesn't push it onto another line. */
#Hud #CitadelHudHeroShop CitadelShopModsBuildCategory #BuildCategoryHeader .CategoryName
{
	font-size: 13px;
	font-weight: bold;
	letter-spacing: 1px;
	text-transform: uppercase;
	color: var(--text);
}

#Hud #CitadelHudHeroShop CitadelShopModsBuildCategory #BuildCategoryHeader .CategoryDescription
{
	font-size: 14px;
}

files.theme/citadel_shop_mods_filtered.css:
/* Clean: the item lists of the Weapon, Spirit and Vitality tabs and of All items: each price tier's
   cards (on their plates, theme/citadel_shop_mods_tier.css) with the tier's price above them. The price
   is bold italic in the souls colour, one size for every tier, in a box wide enough for Jost: the game's
   80 px box cut "1,600" to "16...". No class tells this label whether you can afford the tier, so it is
   always the souls colour, as in the game. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #CitadelHudHeroShop CitadelShopModsFiltered .tierRow .CostLabel Label
{
	width: 130px;
	font-size: 24px;
	font-weight: bold;
	font-style: italic;
	color: var(--good);
	text-shadow: none;
}

/* The painted price sticker panel beside each tier, drawn out of view (the stickers in the game's look
   are part of the catalog page's art). */
#Hud #CitadelHudHeroShop CitadelShopModsFiltered .tierRow .CostSticker
{
	visibility: collapse;
}

files.theme/citadel_shop_mods_recommended.css:
/* Clean: the Recommended tab (Popular Items): a header with the hero's icon, then each price tier's cards
   in three columns (weapon, spirit, vitality) with the tier's price above them. The header becomes a
   faint plate with the game's "Popular Items" title as text (it hides that label and shows a painted
   header), without the pulsing star behind the hero's icon. Prices as on the other tabs
   (theme/citadel_shop_mods_filtered.css): the game's 80 px box was too narrow for Jost. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #CitadelHudHeroShop CitadelShopModsRecommended #PopularItemsHeader
{
	background-color: #F4F6F80F;
	border-radius: 4px;
}

#Hud #CitadelHudHeroShop CitadelShopModsRecommended #PopularItemsHeader .recommendations_header_bg,
#Hud #CitadelHudHeroShop CitadelShopModsRecommended #PopularItemsHeader .recommendatations_hero_bg
{
	visibility: collapse;
}

#Hud #CitadelHudHeroShop CitadelShopModsRecommended #PopularItemsHeader #HeaderLabel
{
	visibility: visible;
	font-size: 18px;
	font-weight: bold;
	font-style: normal;
	letter-spacing: 1px;
	text-transform: uppercase;
	color: var(--text);
}

#Hud #CitadelHudHeroShop CitadelShopModsRecommended #PopularItemsHeader .InfoIcon
{
	wash-color: var(--text);
}

#Hud #CitadelHudHeroShop CitadelShopModsRecommended .tierRow .CostLabel Label
{
	width: 130px;
	font-size: 24px;
	font-weight: bold;
	font-style: italic;
	color: var(--good);
	text-shadow: none;
}

/* The painted price sticker beside each tier. */
#Hud #CitadelHudHeroShop CitadelShopModsRecommended .tierRow .CostSticker
{
	visibility: collapse;
}

files.theme/citadel_shop_mods_tier.css:
/* Clean: the cards of one price tier in a shop list (Weapon, Spirit, Vitality, All items and Recommended
   tabs; one per category on the last two): a faint plate behind them, in place of the frames painted on
   the catalog pages. The tier's price above it is in theme/citadel_shop_mods_filtered.css. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #CitadelHudHeroShop CitadelShopModsTier
{
	background-color: #F4F6F80F;
	border-radius: 4px;
}

files.theme/citadel_status_effect.css:
/* Clean: status effects (stunned, silenced, item buffs...), the small badges under the crosshair and
   at the bottom left. The painted round badge becomes a dark rounded square: a thin edge around a flat
   square in the effect's colour, the icon on top. The colours are still the game's: its rules tint the
   edge (white for a buff, red for a debuff) and the square (per effect) with wash-color, so only the
   shape changes. The same layout draws the badges over heroes' heads, which live outside #Hud: those
   keep the game's look. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .statusEffect
{
	background-image: none;
	background-color: var(--plate);
	border-radius: 4px;
	margin: 0px 2px;
}

#Hud .statusEffect #StatusEffectsBorder
{
	background-image: none;
	border: 2px solid var(--text);
	border-radius: 4px;
}

/* Inset from the edge, one size for every effect (the game makes a few of them 120 %). */
#Hud .statusEffect #StatusEffectInner
{
	background-image: none;
	background-color: var(--text);
	border-radius: 2px;
	width: 74%;
	height: 74%;
}

/* The build-up fill (and its colour per effect) stays under the square: it shows around it. */
#Hud .statusEffect #StatusEffectCooldownOverlay
{
	border-radius: 4px;
}

/* An ability's own icon, which some effects show: square like the badge instead of round. */
#Hud .statusEffect #StatusEffectImage
{
	border-radius: 2px;
}

#Hud .statusEffect #stacks
{
	font-size: 16px;
	font-weight: black;
	font-style: italic;
	color: var(--text);
	text-shadow: 0px 1px 3px 2.0 #000000e0;
}

files.theme/citadel_ui_shop_filters.css:
/* Clean: the filter bar of the All items tab (the effect categories, their menus, the tags of active
   filters and the search box). Flat colours instead of the painted bar and the dotted print on the menus
   and tags, and a short shadow under an open menu instead of a 50 px blur. Each category keeps the game's
   colour; labels, ticks and icons are unchanged. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #CitadelHudHeroShop CitadelShopFilters .filter_backer
{
	background-image: none;
	background-color: #F4F6F80F;
	border-radius: 4px;
}

#Hud #CitadelHudHeroShop CitadelShopFilters #FilterGroupPhysical,
#Hud #CitadelHudHeroShop CitadelShopFilters #FilterGroupSpirit,
#Hud #CitadelHudHeroShop CitadelShopFilters #FilterGroupDefense,
#Hud #CitadelHudHeroShop CitadelShopFilters #FilterGroupMobility,
#Hud #CitadelHudHeroShop CitadelShopFilters #FilterGroupDisruption,
#Hud #CitadelHudHeroShop CitadelShopFilters #FilterGroupMisc,
#Hud #CitadelHudHeroShop CitadelShopFilters #Breadcrumbs .Breadcrumb
{
	background-image: none;
}

#Hud #CitadelHudHeroShop CitadelShopFilters .FilterGroup.TopLevel
{
	box-shadow: 0px 4px 8px #0B0F1499;
}

files.theme/hud.css:
/* Clean: where the parts hud.xml declares go, and the AP counter.

   Each HUD part loads its own layout and stylesheets, and those win over rules from here, so every part
   has a theme file of its own (theme/<layout>.css goes after that layout's stylesheets). The font comes
   from pack.json's "defines": the game's font names (sans, block, oracle...) all become Jost.

   Parts are placed with alignment and margins only. HUD Fit sizes and moves parts with inline ui-scale
   and transform, which beat any stylesheet, so Clean leaves those two alone; with HUD Fit's Default
   layout the parts sit where Clean puts them and HUD Fit can still fine-tune them.

   Colours: text var(--text), plates #0B0F14 (B0-C8 alpha), warning var(--warn), danger var(--danger). */

#Hud Label
{
	font-family: var(--font);
}

/* Health: bottom left, right of the items, a 250 x 200 part (the game's is 250 x 380): the bar along its
   bottom, the numbers above, buffs above those. */
#Hud #health_and_abilities_container
{
	horizontal-align: left;
	vertical-align: bottom;
	margin-left: 300px;
	margin-right: 0px;
	margin-bottom: 26px;
	height: 200px;
}

/* The minimap without its painted compass frame, and its location tag level (the game tilts it to
   follow that round frame). */
#Hud #minimap_frame
{
	opacity: 0;
}

#Hud #minimap_location
{
	transform: none;
}

/* "Item purchased" toasts: a dark plate with a soul-coloured edge instead of the teal gradient
   (their text is in theme/hud_quickbuy_entry.css). */
#Hud .QuickbuyPurchaseToast
{
	background-color: var(--plate-strong);
	border-left: 3px solid var(--good);
	border-radius: 3px;
}

/* Respawn timer (while dead): a dark plate with a red edge instead of the red bar; "RESPAWN IN" a small
   label and the countdown big, black and italic. Where it sits (and its move to the top left in the shop)
   stays the game's. The plate is taller: the number's Jost line is 61 px. */
#Hud .respawn_timer_container
{
	height: 64px;
	background-color: var(--plate-strong);
	border-left: 3px solid var(--danger);
	border-radius: 3px;
}

#Hud .respawn_timer_col_right
{
	width: 120px;
	background-color: #00000000;
}

#Hud .respawn_text
{
	margin-left: 16px;
	font-size: 15px;
	font-weight: bold;
	letter-spacing: 1px;
	text-transform: uppercase;
	color: var(--text);
	opacity: 0.6;
}

#Hud .respawn_number
{
	font-size: 42px;
	font-weight: black;
	font-style: italic;
	color: var(--text);
	max-width: 116px;
}

#Hud .APCurrencyAmount
{
	font-weight: black;
	font-style: italic;
}

/* ---------------------------------------------------------------- Focus: where the parts go
   Each part: an anchor (horizontal-align, vertical-align) and margins in 1080p px, which scale with the screen.
   The left column (#LowerLeft) holds stats, status effects, souls and items one below the other; it spans the
   screen here, so a part taken out of its flow (ignore-parent-flow) can be anchored anywhere. */
#Hud #LowerLeft
{
	width: 100%;
}

/* souls and level: top centre, under the top bar */
#Hud #gold_and_ap_container
{
	ignore-parent-flow: true;
	horizontal-align: center;
	vertical-align: top;
	margin: 96px 0px 0px 0px;
}

/* owned items: on the right edge, halfway up (the bottom right is the minimap's, and the active items sit
   right of the abilities) */
#Hud #LowerLeft #ModsContainer
{
	ignore-parent-flow: true;
	horizontal-align: right;
	vertical-align: center;
	margin: 0px 24px 0px 0px;
}

/* health (numbers and bar, Clean's 250 x 200 part): bottom, left of the abilities. A centre anchor with a right
   margin moves it left by half that margin; 620 + 250 fits a 4:3 screen (1440 wide) too. */
#Hud #health_and_abilities_container
{
	horizontal-align: center;
	vertical-align: bottom;
	margin: 0px 620px 30px 0px;
}

/* in the shop the owned items go to the bottom left, under the souls: the shop's tiers reach the right edge */
#Hud #StatsAndModsContainer.gShopOpen #LowerLeft #ModsContainer
{
	horizontal-align: left;
	vertical-align: bottom;
	margin: 0px 0px 16px 24px;
}

files.theme/hud_ability_icon.css:
/* Clean: flat ability icons in a straight row. The game's round frame and its ring become a rounded
   square and its outline. Only shape and place change: the colours of each state (cooling down,
   active, upgrade available, not learned) still come from the game's own rules, which tint these two
   panels (wash-color, opacity). The same layout draws the small ability icons in the top bar, so every
   rule here is for the ability bar only (#hud_signature). */

#Hud Label
{
	font-family: var(--font);
}

/* A 120 x 120 button: the plate is 88 x 88 at its top, the key sits under it. */
#Hud #hud_signature .ability_bg,
#Hud #hud_signature .ability_ring
{
	background-image: none;
	width: 88px;
	height: 88px;
	horizontal-align: center;
	vertical-align: top;
	margin-top: 8px;
	border-radius: 16px;
}

#Hud #hud_signature .ability_bg
{
	background-color: var(--text);
}

#Hud #hud_signature .ability_ring
{
	background-color: #00000000;
	border: 3px solid var(--text);
}

/* The icon, centred on the plate (the plate's centre is 52 px down, the button's 60). */
#Hud #hud_signature .ability_image
{
	vertical-align: top;
	margin-top: 22px;
}

/* The cooldown sweep, cut to the plate. */
#Hud #hud_signature .cooling_down #cooldown_mask,
#Hud #hud_signature .ability_not_ready #cooldown_mask
{
	width: 88px;
	height: 88px;
	horizontal-align: center;
	vertical-align: top;
	margin-top: 8px;
	opacity-mask: url("uikit://rounded.vsvg");
}

#Hud #hud_signature .cooldown_timer
{
	font-size: 38px;
	font-weight: black;
	font-style: italic;
	color: var(--text);
	vertical-align: top;
	margin-top: 28px;
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

/* One straight row: the game lifts the middle two. */
#Hud #hud_signature #slot_signature_2 #button_container,
#Hud #hud_signature #slot_signature_3 #button_container
{
	margin-bottom: 0px;
}

files.theme/hud_ability_icon_active.css:
/* Clean: the active item slots right of the ability bar. Each item's round art sits on a dark rounded
   plate (the game's own rules still fade the plate while the item cools down, as on the ability bar); the
   cooldown number is black italic like the ability bar's, the key under the plate small, the charges badge
   flat. The same layout draws the cosmetic and held slots, so every rule here is for the item slots only
   (#ActiveAbilitiesMenu). */

#Hud Label
{
	font-family: var(--font);
}

/* A 58 x 80 slot with the 48 px art 6 px from its top: the plate is 54 x 54 around the art. The game
   washes this panel in the key colour; the plate stays dark. */
#Hud #ActiveAbilitiesMenu .ability_bg
{
	background-color: var(--plate);
	wash-color: none;
	border-radius: 4px;
	width: 54px;
	height: 54px;
	horizontal-align: center;
	vertical-align: top;
	margin: 3px 0px 0px 0px;
}

#Hud #ActiveAbilitiesMenu .ability_upgradable .ability_bg
{
	wash-color: #7662cf;
}

#Hud #ActiveAbilitiesMenu .cooldown_timer
{
	font-weight: black;
	font-style: italic;
	color: var(--text);
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

#Hud #ActiveAbilitiesMenu .ability_key_container
{
	ui-scale: 70%;
}

#Hud #ActiveAbilitiesMenu #charges_container
{
	background-color: var(--plate-strong);
	box-shadow: none;
}

#Hud #ActiveAbilitiesMenu #charges
{
	font-weight: black;
	font-style: italic;
}

files.theme/hud_ability_icon_passive.css:
/* Clean: passive items with a cooldown, in their row above the ability bar. The game tints the whole tile,
   art included, in the item's category colour; Clean gives it a dark rounded plate, keeps the art's own
   colours and shows the category as a thin edge under it. Only for #hud_passive_items, where the HUD
   draws this layout for items. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #hud_passive_items .button_container
{
	background-color: var(--plate);
	border-radius: 4px;
	wash-color: none;
}

/* The game's weapon, vitality and spirit colours. */
#Hud #hud_passive_items .isWeaponSlot .button_container
{
	border-bottom: 3px solid #EC9719;
}

#Hud #hud_passive_items .isVitalitySlot .button_container
{
	border-bottom: 3px solid #7BBA1D;
}

#Hud #hud_passive_items .isSpiritSlot .button_container
{
	border-bottom: 3px solid #CE90FF;
}

/* The game's other tints of the tile, which the plate rule would undo. */
#Hud #hud_passive_items .new_item .button_container
{
	background-color: #ffe91ec2;
	wash-color: #b969ffc2;
}

#Hud #hud_passive_items .not_enough_mana .button_container
{
	wash-color: #244B64;
}

/* The cooldown sweep, cut to the plate's corners. */
#Hud #hud_passive_items #cooldown_mask
{
	border-radius: 4px;
}

files.theme/hud_ability_resource.css:
/* Clean: the meter some heroes have above the abilities (rage, heat, ink): a flat white bar on a dark
   plate with square corners, like the Clean health bar, and its name in bold. Its flashes (a failed
   cast, heat at full) still come from the game. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #ability_resource_progress
{
	background-color: var(--plate);
	border-radius: 3px;
}

#Hud #ability_resource_progress .ProgressBarLeft
{
	background-image: none;
	background-color: var(--text);
}

/* The game's blue mana meter, set again (the rule above outranks it). */
#Hud .mana #ability_resource_progress .ProgressBarLeft
{
	background-color: var(--team2);
}

/* The plate shows through the empty part. */
#Hud #ability_resource_progress .ProgressBarRight
{
	background-color: #00000000;
}

/* Over the bar: a darker shadow keeps it readable on the white fill. */
#Hud #type_label
{
	font-weight: bold;
	text-shadow: 0px 1px 4px 1.0 #000000c8;
}

files.theme/hud_damage_impact.css:
/* Clean: the kill and assist confirmation over the crosshair (the victim's badge, KILL or ASSIST, their
   name, the souls bounty). Black italic words and numbers with a soft shadow instead of thick outlines,
   in Clean's red, yellow and souls colours. The badge keeps the game's red wash and the animations stay. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .killLabel,
#Hud .assistLabel
{
	font-weight: black;
	font-style: italic;
	letter-spacing: 2px;
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

#Hud .killLabel
{
	color: var(--danger);
}

#Hud .assistLabel
{
	color: var(--warn);
}

#Hud .playerName
{
	font-weight: bold;
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

#Hud .bountyContainer .soul_amount
{
	font-weight: black;
	font-style: italic;
	color: var(--good);
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

files.theme/hud_damage_report.css:
/* Clean: the damage report shown on the right when you die (and with the scoreboard). A dark plate instead
   of the olive one, a flat time picker, the total black and italic under a small uppercase label. Its
   modes (incoming, outgoing, tab...) and the weapon and spirit colours stay the game's. The rows are in
   theme/hud_damage_rows.css. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .HudDamageReport #ReportContents
{
	background-color: var(--plate);
	border-radius: 4px 0px 0px 4px;
}

/* The folded tab (the game darkens it). */
#Hud .HudDamageReport.Tab #ReportContents
{
	background-color: var(--plate-strong);
}

#Hud .HudDamageReport .DamageReportHeader
{
	letter-spacing: 1px;
}

/* The time picker without its gradient; hover and disabled re-added (the rule outranks the game's). */
#Hud #TimeControlDropDown
{
	background-color: #0B0F14B0;
	border: 1px solid #F4F6F833;
	border-radius: 3px;
	box-shadow: none;
}

#Hud #TimeControlDropDown:hover
{
	background-color: #F4F6F81A;
}

#Hud #TimeControlDropDown:disabled
{
	background-color: #0B0F1480;
	border: 1px solid #F4F6F81A;
}

/* Weapon and spirit share of the damage. */
#Hud .HudDamageReport .DamagePercent
{
	font-weight: black;
	font-style: italic;
}

#Hud .HudDamageReport .Footer .DamageDesc
{
	font-size: 13px;
	font-weight: bold;
	letter-spacing: 1px;
	text-transform: uppercase;
	opacity: 0.6;
	vertical-align: center;
}

#Hud .HudDamageReport .Footer .DamageValue
{
	font-size: 24px;
	font-weight: black;
	font-style: italic;
	vertical-align: center;
}

#Hud .HudDamageReport .ShowMore
{
	background-color: #F4F6F814;
	border-radius: 3px;
}

#Hud .HudDamageReport .ShowMore Label
{
	font-size: 13px;
	font-weight: bold;
	letter-spacing: 1px;
	text-transform: uppercase;
}

files.theme/hud_damage_rows.css:
/* Clean: the damage report's rows (one per damage source): the numbers black and italic. The same layout
   draws the rows of the report's tooltip, so the rule is for the report only (#DamageByAbility). */

#Hud Label
{
	font-family: var(--font);
}

#Hud #DamageByAbility .DamageValue
{
	font-weight: black;
	font-style: italic;
}

files.theme/hud_damage_summary.css:
/* Clean: the damage summary (who hurt you, and with what). A dark plate instead of the olive panel and
   rows, the title a small bold uppercase label, the damage numbers black and italic. Weapon and spirit
   damage keep their colours (bars and numbers), and the killing-blow badge stays. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .hud_damage_summary
{
	background-color: var(--plate-strong);
	border-radius: 4px;
}

#Hud .category_title
{
	font-size: 16px;
	letter-spacing: 1px;
	text-transform: uppercase;
	color: var(--text);
}

/* One row per hero, every other one lighter. */
#Hud .hero_damage_summary
{
	background-color: #F4F6F80A;
}

#Hud .hero_damage_summary.even
{
	background-color: #00000000;
}

#Hud #ability_damage
{
	font-weight: black;
	font-style: italic;
}

files.theme/hud_data_feed.css:
/* Clean: the kill feed, top right under the top bar (the game's is top left). */

#Hud Label
{
	font-family: var(--font);
}

#Hud #EventFeed
{
	horizontal-align: right;
	margin-top: 150px;
	margin-right: 24px;
	width: 760px;
	transition-property: margin-right;
	transition-duration: 0.2s;
}

/* While dead the game shows its damage report at the top right (350 px wide): the feed steps left of it. */
#Hud.dead #EventFeed,
#Hud .dead #EventFeed
{
	margin-right: 390px;
}

#Hud #EventFeed CitadelHudInfoFeed
{
	horizontal-align: right;
}

files.theme/hud_event_indicator.css:
/* Clean: the numbers that pop up in the world (damage dealt and taken, healing, souls picked up). They
   are italic, like every number in Clean; their weights, sizes, colours (per damage type, crit, heal) and
   animations stay the game's. Souls are in Clean's soul colour, souls not secured yet in red. */

#Hud Label
{
	font-family: var(--font);
}

/* The number and the souls' "+" (not the small description under some of them). */
#Hud #Value,
#Hud #GoldPlusPrefix
{
	font-style: italic;
}

#Hud .gold #Value,
#Hud .gold #GoldPlusPrefix
{
	font-weight: black;
}

#Hud .gold #Value,
#Hud .gold #GoldPlusPrefix,
#Hud .gold_small #Value,
#Hud .gold_small #GoldPlusPrefix
{
	color: var(--good);
}

/* After the rule above, which it has to beat (the game shows these in a light red). */
#Hud .isUnsecured #Value,
#Hud .isUnsecured #GoldPlusPrefix
{
	color: var(--danger);
}

/* The soul icon next to the number. */
#Hud .gold .HudIndicatorIcon,
#Hud .gold_small .HudIndicatorIcon
{
	wash-color: var(--good);
}

#Hud .isUnsecured.gold .HudIndicatorIcon,
#Hud .isUnsecured.gold_small .HudIndicatorIcon
{
	wash-color: var(--danger);
}

files.theme/hud_event_indicator_item_used.css:
/* Clean: the name of an item someone just used, popping up over them. An upright, spaced label (italics
   are for numbers in Clean), still in its category's colour (weapon, vitality, spirit) with the game's
   outline and pop-in. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #Value
{
	font-style: normal;
	letter-spacing: 1px;
}

/* Clean: a status effect landing on someone (stunned, silenced, asleep...), popping up over them. Its value
   black and italic like Clean's numbers; the condition icon, colours, outline and pop-in stay the game's.
   An ability's icon sits on a rounded square, like Clean's ability icons, instead of a circle. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #Value
{
	font-weight: black;
}

#Hud .is_ability .HudIndicatorIconContainer
{
	border-radius: 4px;
}

files.theme/hud_gold_and_ap_container.css:
/* Clean: souls. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #hudCurGoldLabel
{
	font-size: 30px;
	font-weight: black;
	font-style: italic;
	text-shadow: 0px 2px 5px 1.0 #000000c0;
}

#Hud #hudGoldLabel
{
	font-size: 12px;
	letter-spacing: 2px;
	opacity: 0.6;
}

/* Focus: in the shop, souls go back to the bottom left: the shop fills the top of the screen. (The game's own
   shop rule here sets margins for the part's usual place; a rule in this file wins over theme/hud.css.) */
#Hud #gold_and_ap_container.gShopOpen
{
	horizontal-align: left;
	vertical-align: bottom;
	margin: 0px 0px 150px 20px;
}

files.theme/hud_health.css:
/* Clean: a flat, level health bar along the bottom of the health part. The game's bar stands upright and
   fills from the bottom, so the whole bar is turned a quarter to the right: then it fills from the left. */

#Hud Label
{
	font-family: var(--font);
}

/* Upright 14 x 250; turned about its centre it lies along the bottom of the 250 x 200 part
   (theme/hud.css), 4 px above its edge: centre (125, 189). */
#Hud .bars_container
{
	transform: rotateZ(90deg);
	width: 14px;
	height: 250px;
	horizontal-align: left;
	vertical-align: bottom;
	margin: 0px 0px -114px 118px;
	padding: 0px;
	flow-children: none;
}

#Hud .health_bar_line
{
	width: 100%;
	height: 100%;
}

#Hud .health_bar_border
{
	width: 100%;
	height: 100%;
	margin: 0px;
}

/* The bar and the bars drawn over it (incoming damage and heal, shields): the full box, square ends (the
   game's mask tapers them). */
#Hud #health_bar,
#Hud #pending_incoming_damage,
#Hud #pending_incoming_heal,
#Hud #shield_bar_2,
#Hud #ratking_armor_bar,
#Hud #healthLines
{
	width: 100%;
	height: 100%;
	margin: 0px;
	opacity-mask: url("uikit://solid.vsvg");
}

#Hud #health_bar
{
	background-color: #0B0F14B8;
}

#Hud #health_bar .ProgressBarLeft
{
	background-color: var(--text);
	background-image: none;
}

#Hud .healthMid #health_bar .ProgressBarLeft
{
	background-color: var(--warn);
}

#Hud .healthLow #health_bar .ProgressBarLeft
{
	background-color: var(--danger);
}

/* The game's tick marks become thin segment lines across the bar. */
#Hud #healthLines .line_large
{
	height: 2px;
	background-color: #0B0F14;
	opacity: 0.6;
}

#Hud #healthLines .line_small
{
	height: 2px;
	width: 40%;
	background-color: #0B0F14;
	opacity: 0.4;
}

#Hud #health_bar_frame,
#Hud .regen_container
{
	visibility: collapse;
}

/* The rejuvenator sign: just past the right end of the bar, turned back level. */
#Hud #RejuvenatorContainer
{
	transform: rotateZ(-90deg);
	horizontal-align: center;
	vertical-align: top;
	width: 34px;
	height: 34px;
	margin: -44px 0px 0px 0px;
}

files.theme/hud_health_container.css:
/* Clean: the health number, big and upright, above the bar (theme/hud_health.css). */

#Hud Label
{
	font-family: var(--font);
}

/* The numbers' box covers the whole part, level; the numbers sit at its bottom left. */
#Hud #HealthRegenAndTotal
{
	transform: none;
	width: 100%;
	height: 100%;
	horizontal-align: left;
	vertical-align: top;
	margin: 0px;
}

#Hud .healthContainer
{
	horizontal-align: left;
	vertical-align: bottom;
	width: fit-children;
	height: fit-children;
	margin: 0px 0px 20px 0px;
	flow-children: right;
}

#Hud .healthBacker
{
	visibility: collapse;
}

#Hud .currentHealthLabel
{
	font-size: 46px;
	font-weight: black;
	font-style: italic;
	color: var(--text);
	margin: 0px;
	padding: 0px 6px 0px 0px;
	max-width: 190px;
	text-shadow: 5px 2px 6px 1.0 #000000c8;
}

#Hud .totalHealthLabel
{
	font-size: 18px;
	font-weight: bold;
	font-style: italic;
	color: var(--text);
	opacity: 0.6;
	transform: none;
	horizontal-align: left;
	vertical-align: bottom;
	margin: 0px 0px 9px 0px;
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

/* With a bullet shield the number turns light blue, as in the game (mid and low health still win). */
#Hud .HasBulletShield .currentHealthLabel
{
	color: #A1F4FF;
}

#Hud #health_and_abilities_container.localPlayerMidHealth .currentHealthLabel
{
	color: var(--warn);
}

#Hud #health_and_abilities_container.localPlayerLowHealth .currentHealthLabel
{
	color: var(--danger);
}

/* Heal and damage counters: at the right end, above the bar. */
#Hud #RecentHealContainer
{
	horizontal-align: right;
	vertical-align: bottom;
	margin: 0px 0px 58px 0px;
}

#Hud #RecentDamageContainer
{
	horizontal-align: right;
	vertical-align: bottom;
	margin: 0px 0px 24px 0px;
}

files.theme/hud_hints.css:
/* Clean: the hint bar (tips in the middle of the screen). One flat dark plate with small rounded corners
   instead of the black pill, and the warning yellow for the info icon and emphasised words. The opening
   animation (the ends sliding apart, the middle widening, then the text) is the game's. */

#Hud Label
{
	font-family: var(--font);
}

/* The bar is three panels: two ends and the middle. */
#Hud .capLeft,
#Hud .capRight,
#Hud .body
{
	background-color: var(--plate);
}

#Hud .capLeft
{
	border-radius: 4px 0px 0px 4px;
}

#Hud .capRight
{
	border-radius: 0px 4px 4px 0px;
}

#Hud #hintText
{
	color: var(--text);
}

#Hud .infoIcon
{
	wash-color: var(--warn);
}

#Hud .hintTextEmphasis
{
	color: var(--warn);
}

files.theme/hud_match_end.css:
/* Clean: the end of the match. VICTORY or DEFEAT big, black and italic (white for a win, red for a loss)
   over a flat dark veil, instead of the painted brush band in the team's colour or red. The cancelled-match
   screen is level, its title red. */

#Hud Label
{
	font-family: var(--font);
}

/* The band, without its brush-shaped mask: a veil over the whole screen. It outranks the game's red for a
   loss on purpose: the outcome's colour moves to the word (below). */
#Hud #MatchCompleteBG
{
	background-color: #0B0F14;
	opacity-mask: none;
	opacity: 0.5;
}

/* Faded in instead of the brush wipe (whose mask would cut the veil back to a band while it runs). */
#Hud .ShowMatchEnd.MatchFinished #MatchCompleteBG
{
	animation-name: CleanMatchEndFadeIn;
	animation-duration: 0.6s;
}

@keyframes 'CleanMatchEndFadeIn'
{
	0%
	{
		opacity: 0;
	}

	100%
	{
		opacity: 0.5;
	}
}

#Hud .OutcomeLabel
{
	font-size: 150px;
	font-weight: black;
	font-style: italic;
	text-transform: uppercase;
	color: var(--text);
	text-shadow: 0px 4px 12px 1.0 #000000c8;
}

#Hud .LocalPlayerTeam1.Team2Victory .OutcomeLabel,
#Hud .LocalPlayerTeam2.Team1Victory .OutcomeLabel
{
	color: var(--danger);
}

#Hud .MatchAbandonedDisplay
{
	background-color: var(--plate);
}

#Hud .MatchAbandonedDisplay .MatchAbandonedTitle
{
	font-size: 72px;
	font-weight: black;
	font-style: italic;
	color: var(--danger);
	pre-transform-rotate2d: 0deg;
}

/* The game pulls it up under its taller title. */
#Hud .MatchAbandonedDisplay .MatchAbandonedSubtitle
{
	font-size: 26px;
	font-weight: bold;
	letter-spacing: 2px;
	text-transform: uppercase;
	color: var(--text);
	opacity: 0.6;
	margin-top: 0px;
	pre-transform-rotate2d: 0deg;
}

files.theme/hud_minimap.css:
/* Clean: the minimap's own text, the mid boss's respawn timer (on the map in the detail view), black
   italic. The map, its icons and their colours stay the game's; the painted compass frame around the
   minimap is hidden in theme/hud.css. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .map_button.mid_boss .midboss_timer
{
	font-weight: black;
	font-style: italic;
	color: var(--text);
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

files.theme/hud_modifiers_custom.css:
/* Clean: a buff or debuff with a small table of numbers under its name (few effects have one). The same
   look as the other entries (theme/hud_modifiers_entry.css): a dark plate with a thin edge, white for a
   buff and red for a debuff, instead of the green or red plate, and a light fill for the time left. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .modifier.modifier_custom
{
	background-color: var(--plate);
	border: 0px solid #00000000;
	border-radius: 4px;
}

#Hud .modifier_custom.buff
{
	border-left: 3px solid var(--text);
}

#Hud .modifier_custom.debuff
{
	border-left: 3px solid var(--danger);
}

/* The time left. The game colours it per state; each state is here again, in the game's order. */
#Hud #modifier_progress
{
	background-color: #F4F6F826;
}

#Hud .buff #modifier_progress
{
	background-color: #F4F6F840;
}

#Hud .debuff #modifier_progress
{
	background-color: #FF5A5F59;
}

#Hud .MODIFIER_STATE_SILENCED #modifier_progress
{
	background-color: #BC1DCA99;
}

#Hud .debuff.MODIFIER_STATE_STUNNED #modifier_progress
{
	background-color: #FF5A5FCC;
}

#Hud .buildup #modifier_progress
{
	background-color: #FF5A5F33;
}

#Hud .buildup_applied #modifier_progress
{
	background-color: #FF5A5FCC;
}

#Hud .buildup.modifier_citadel_silence_proc_buildup #modifier_progress,
#Hud .buildup_applied.modifier_citadel_silence_proc_buildup #modifier_progress
{
	background-color: #CC00FFB3;
}

#Hud .modifier_custom .modifier_name
{
	font-weight: bold;
	letter-spacing: 1px;
	color: var(--text);
}

#Hud .modifier_custom .modifier_stats_cell
{
	color: var(--text);
}

files.theme/hud_modifiers_entry.css:
/* Clean: one buff or debuff in the list on the left of the screen (an effect's name, its time left and
   its stacks). A dark plate with a thin edge, white for a buff and red for a debuff, instead of the green
   or red plate and frame; the time left is a light fill (red for a debuff) instead of the solid one, and
   the stack count is big. The same layout likely also draws the small buff icons above the health
   (CitadelHudModifierIcons): the plate and edge are for the left list only (#hud_aura_modifiers), the
   fill and the text for both. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #hud_aura_modifiers .modifier
{
	background-color: var(--plate);
	border: 0px solid #00000000;
	border-radius: 4px;
}

#Hud #hud_aura_modifiers .buff .modifier
{
	border-left: 3px solid var(--text);
}

#Hud #hud_aura_modifiers .debuff .modifier
{
	border-left: 3px solid var(--danger);
}

/* The time left. The game colours it per state; each state is here again, in the game's order. */
#Hud #modifier_progress
{
	background-color: #F4F6F826;
}

#Hud .buff #modifier_progress
{
	background-color: #F4F6F840;
}

#Hud .debuff #modifier_progress
{
	background-color: #FF5A5F59;
}

#Hud .MODIFIER_STATE_SILENCED #modifier_progress
{
	background-color: #BC1DCA99;
}

#Hud .debuff.MODIFIER_STATE_STUNNED #modifier_progress
{
	background-color: #FF5A5FCC;
}

/* A debuff building up, then the moment it applies. */
#Hud .buildup #modifier_progress
{
	background-color: #FF5A5F33;
}

#Hud .buildup_applied #modifier_progress
{
	background-color: #FF5A5FCC;
}

#Hud .buildup.modifier_citadel_silence_proc_buildup #modifier_progress,
#Hud .buildup_applied.modifier_citadel_silence_proc_buildup #modifier_progress
{
	background-color: #CC00FFB3;
}

#Hud .modifier .modifier_name
{
	font-weight: bold;
	letter-spacing: 1px;
	color: var(--text);
}

/* line-height: the left list gives every label 16 px, too little for this size. */
#Hud .modifier .modifier_stacks
{
	font-size: 26px;
	font-weight: black;
	font-style: italic;
	line-height: 30px;
	color: var(--text);
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

files.theme/hud_modifiers_entry_center.css:
/* Clean: buffs and debuffs in the middle of the screen, above the abilities. A channel or timed effect
   shows its name over a bar; crowd control shows a big word (STUNNED, SILENCED...) that fills with the
   effect's colour as it runs out. Flat: no speckled mask, the big word in black italic with a soft
   shadow instead of the heavy outline, and a slim flat bar (white, red for a debuff) on a dark track
   instead of the textured one. Every sweep and fill is still the game's. */

#Hud Label
{
	font-family: var(--font);
}

/* The speckle texture over the whole entry. */
#Hud CitadelHudModifiers_Entry
{
	opacity-mask: none;
}

/* The big word. Its coloured copy (the sweep) is drawn from this label, so it follows. */
#Hud .SplitLabelProgressBar .SplitLabelName Label
{
	font-weight: black;
	font-style: italic;
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

/* The ability that did it, under the word. */
#Hud .AbilityNameLabel
{
	font-size: 20px;
	font-weight: bold;
	letter-spacing: 1px;
	text-transform: uppercase;
	color: var(--text);
	opacity: 0.6;
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

#Hud .center_modifiers .modifier_name
{
	font-weight: bold;
	letter-spacing: 1px;
	color: var(--text);
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

#Hud .center_modifiers #bar_container
{
	height: 16px;
}

#Hud .center_modifiers #bar_bg
{
	background-color: var(--plate);
}

#Hud .center_modifiers .debuff #bar_bg
{
	background-color: #3C1E23C8;
}

/* The fill. The game colours it per state; each state is here again. */
#Hud .center_modifiers #modifier_progress
{
	background-image: none;
	background-color: var(--text);
}

#Hud .center_modifiers .debuff #modifier_progress
{
	background-color: var(--danger);
}

#Hud .center_modifiers .buildup #modifier_progress
{
	background-color: #FF5A5F4D;
}

#Hud .center_modifiers .buildup_applied #modifier_progress
{
	background-color: var(--danger);
}

#Hud .center_modifiers .buildup.modifier_citadel_silence_proc_buildup #modifier_progress,
#Hud .center_modifiers .buildup_applied.modifier_citadel_silence_proc_buildup #modifier_progress
{
	background-color: #CC00FF;
}

/* Bars split into named segments (white names) keep the game's size and get a see-through fill. */
#Hud .center_modifiers .has_bar_segments #bar_container
{
	height: 44px;
}

#Hud .center_modifiers .has_bar_segments #modifier_progress
{
	background-color: #F4F6F840;
}

files.theme/hud_movement_speed.css:
/* Clean: the speed readout (bottom right, when the game or the Speedometer setting shows it): the number
   black italic, the bar flat on a dark plate. Slower than base turns Clean's red, faster keeps the
   game's green, and the tick on the bar still marks base speed. */

#Hud Label
{
	font-family: var(--font);
}

/* The number's box is 80 px wide: a longer value shrinks instead of wrapping. */
#Hud #MovementSpeedLabel
{
	font-size: 18px;
	font-weight: black;
	font-style: italic;
	max-width: 80px;
	white-space: nowrap;
	text-overflow: shrink;
	text-shadow: 0px 2px 6px 1.0 #000000c8;
}

#Hud .isNegative #MovementSpeedLabel
{
	color: var(--danger);
}

#Hud #MovementSpeed
{
	background-color: #0B0F14B8;
	border-radius: 2px;
}

/* Flat fills instead of the gradients; each state the game colours is set again here. */
#Hud #MovementSpeed .ProgressBarLeft
{
	background-color: #F4F6F8A0;
	border-right: 3px solid var(--text);
}

#Hud .isNegative #MovementSpeed .ProgressBarLeft
{
	background-color: #FF5A5FA0;
	border-right: 3px solid var(--danger);
}

#Hud .isPositive #MovementSpeed .ProgressBarLeft
{
	background-color: #00BE16A0;
	border-right: 3px solid #00FF1E;
}

files.theme/hud_objective_health.css:
/* Clean: the health bars of guardians, walkers, the patron and other bosses (top centre, in a fight):
   flat bars on dark plates with square ends, like the Clean health bar. The fill turns white and the
   game's own rules still tint it per team (wash-color), so enemy, friendly and team colours keep their
   meaning. The patron's painted backer goes; its team logo stays. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #name
{
	font-size: 16px;
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

#Hud #healthbar_background,
#Hud #bulletshield_background
{
	background-color: var(--plate);
	border-radius: 3px;
}

/* Square ends: the game's mask tapers them. */
#Hud #healthbar_progress,
#Hud #bulletshield_progress
{
	opacity-mask: url("uikit://solid.vsvg");
}

#Hud #healthbar_progress .ProgressBarLeft,
#Hud #bulletshield_progress .ProgressBarLeft
{
	background-image: none;
	background-color: var(--text);
}

/* The extra bars beside the patron's: flat and square, still tinted and faded by the game. */
#Hud .fakeHealthbar
{
	background-image: none;
	opacity-mask: url("uikit://solid.vsvg");
}

/* As specific as the game's rule that paints it (it names the team containers). */
#Hud .objective.is_titan #boss_background
{
	background-image: none;
}

/* "Destroyed": a dark plate with a red edge instead of a red fill. */
#Hud #deadlabel
{
	background-color: var(--plate-strong);
	border-left: 3px solid var(--danger);
	border-radius: 3px;
}

#Hud #deadlabel Label
{
	font-weight: bold;
	letter-spacing: 2px;
}

#Hud #BackdoorProtection Label,
#Hud #OutOfRange Label
{
	font-weight: bold;
	letter-spacing: 1px;
}

#Hud #PausedOverlay .pauseTitle
{
	letter-spacing: 1px;
	color: var(--danger);
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

#Hud #PausedOverlay .pauseDesc,
#Hud #PausedOverlay .resistantDesc
{
	font-style: normal;
	font-weight: bold;
	color: var(--text);
	text-shadow: 0px 1px 4px 1.0 #000000c0;
}

files.theme/hud_quickbuy.css:
/* Clean: the quick-buy queue in the shop (top left): the "Quick Buy" button that opens it and the box around
   the queue. Dark plates instead of the frosted ones. The rows are in theme/hud_quickbuy_entry.css. */

#Hud Label
{
	font-family: var(--font);
}

#Hud #QuickbuyShopSummary
{
	background-color: var(--plate);
	border: 0px solid #00000000;
	border-radius: 4px;
}

#Hud .QuickbuyQueueOuter
{
	background-color: #0B0F14E6;
	border: 0px solid #00000000;
	border-radius: 4px;
}

files.theme/hud_quickbuy_entry.css:
/* Clean: the text of an "item purchased" toast, light on its dark plate (theme/hud.css). The same
   layout draws the quick-buy queue, so these rules are for the toasts only. */

#Hud Label
{
	font-family: var(--font);
}

#Hud .QuickbuyPurchaseToast #ModName
{
	color: var(--text);
}

#Hud .QuickbuyPurchaseToast .QuickbuyLabel
{
	color: var(--text);
	opacity: 0.6;
}

/* ---- Queue rows in the shop (added for the shop; the rules above are the toasts'). Each item in the
   quick-buy queue, and in the sell queue above it, is a dark plate with a thin edge in its category's colour
   (weapon, vitality, spirit) instead of a coloured gradient, the rows parted by a dark line. Jost's lines are
   taller than the game's font, so the name and the cost under it overflowed the 50 px row and the cost was
   cut: the rows are 62 px and the cost a size smaller (a 20 px line-height on both labels changed nothing in
   game). The row's dimming and hover, the drop-target and drag-out looks, the
   "slots full" fade and the cost's colours (souls colour when you can afford it, red when not) stay the
   game's. */

#Hud #QuickbuyQueue .QuickbuyItem,
#Hud #QuickbuySellQueue .QuickbuyItem
{
	height: 62px;
	background-color: #161C24;
	border-bottom: 2px solid #0B0F14;
	border-radius: 3px;
	box-shadow: none;
}

#Hud #QuickbuyQueue .QuickbuyItem.isWeapon,
#Hud #QuickbuySellQueue .QuickbuyItem.isWeapon
{
	border-left: 3px solid #EC9719;
}

#Hud #QuickbuyQueue .QuickbuyItem.isArmor,
#Hud #QuickbuySellQueue .QuickbuyItem.isArmor
{
	border-left: 3px solid #7BBA1D;
}

#Hud #QuickbuyQueue .QuickbuyItem.isTech,
#Hud #QuickbuySellQueue .QuickbuyItem.isTech
{
	border-left: 3px solid #CE90FF;
}

/* The row you drag: a lighter plate (the plate rule outranks the game's colour for it). */
#Hud #QuickbuyQueue .QuickbuyItem.IsBeingDragged,
#Hud #QuickbuySellQueue .QuickbuyItem.IsBeingDragged
{
	background-color: #2A3340;
}

#Hud #QuickbuyQueue .CostPanel #ModCost,
#Hud #QuickbuySellQueue .CostPanel #ModCost
{
	font-size: 14px;
}

/* Reorder and remove: light, as the game's black would vanish on the dark plate. The rule outranks the game's
   hover, so it is here again. */
#Hud #QuickbuyQueue #ReorderButton,
#Hud #QuickbuySellQueue #ReorderButton,
#Hud #QuickbuyQueue #DeleteButton,
#Hud #QuickbuySellQueue #DeleteButton
{
	wash-color: var(--text);
	opacity: 0.5;
}

#Hud #QuickbuyQueue #ReorderButton:hover,
#Hud #QuickbuySellQueue #ReorderButton:hover
{
	opacity: 0.9;
}

#Hud #QuickbuyQueue #DeleteButton:hover,
#Hud #QuickbuySellQueue #DeleteButton:hover
{
	wash-color: var(--danger);
	opacity: 1;
}

files.theme/hud_spectate_bar.css:
/* Clean: the spectating panel (top right, while dead or spectating): who you watch on a dark plate,
   small bold labels. The dark gradient band across the top of the screen goes; its top edge stays, and
   the game still colours it with the team of the player you watch. */

#Hud Label
{
	font-family: var(--font);
}

/* Also clears the band's per-team tints (gradients); the edge keeps the team colour. */
#Hud .SpectateTopBar
{
	background-color: #00000000;
}

#Hud #spectate_target
{
	background-color: var(--plate);
	border-radius: 3px;
	padding: 8px 12px;
}

/* Lines the camera hints up with the text on the plate above. */
#Hud #camera_section
{
	padding: 0px 12px;
}

#Hud .spectatingTitle
{
	font-size: 13px;
	font-weight: bold;
	letter-spacing: 1px;
	opacity: 0.6;
	text-shadow: 0px 1px 3px 1.0 #000000c0;
}

#Hud .keybindTitle
{
	text-shadow: 0px 1px 3px 1.0 #000000c0;
}

files.theme/hud_unit_indicators_v2.css:
/* Clean: the markers the game puts on heroes (name, hero icon, distance). Names in the Clean team
   colours, as in the kill feed: amber, sapphire, enemies red. The icon sits on a dark disc with a ring in
   that colour instead of a coloured disc. Which colour a marker gets is still the game's choice: the
   rules below follow its own state rules, in its order (enemy last, so it wins). */

#Hud Label
{
	font-family: var(--font);
}

#Hud .PlayerEntry.team_1 #PlayerName Label
{
	color: var(--team1);
}

#Hud .PlayerEntry.team_2 #PlayerName Label
{
	color: var(--team2);
}

#Hud .PlayerEntry.enemy #PlayerName Label
{
	color: var(--danger);
}

#Hud .PlayerEntry #HeroIcon
{
	background-color: var(--plate);
	border: 2px solid var(--text);
}

#Hud .PlayerEntry.team_1 #HeroIcon
{
	border-color: var(--team1);
}

#Hud .PlayerEntry.team_2 #HeroIcon
{
	border-color: var(--team2);
}

#Hud .PlayerEntry.enemy #HeroIcon
{
	border-color: var(--danger);
}

/* "Critical" (low health): red text with a dark shadow instead of white with a red glow. */
#Hud .PlayerEntry #CriticalIndicator Label
{
	font-weight: bold;
	letter-spacing: 1px;
	color: var(--danger);
	text-shadow: 0px 1px 3px 1.0 #000000c8;
}

#Hud .distance_label
{
	font-size: 12px;
	font-weight: bold;
	text-shadow: 0px 1px 3px 1.0 #000000c0;
}

files.pack.css:
/* Arena: health and ammo the way a hero shooter draws them: white type and white pips straight on the game,
   no plates, each corner block tilted towards the middle of the screen (the game's own HUD tilts its health
   part the same way before a match: a perspective on the parent, rotateY on the part). Shared by both
   widgets; colours and font are the pack's vars (pack.json). Data comes from the binds (health, ammo), state
   from classes the game and UI Kit put on the panels above (.dead on the HUD; .gShopOpen, .gScoreboardOpen,
   .localPlayerLowHealth, .reloading on UI Kit's root). */
.Vital
{
	vertical-align: bottom;
	width: 340px;
	height: 140px;
	margin-bottom: 26px;
	perspective: 900;
	transition-property: opacity;
	transition-duration: 0.15s;
}

.dead .Vital,
.gShopOpen .Vital,
.gScoreboardOpen .Vital
{
	visibility: collapse;
}

.Tilt
{
	width: 100%;
	height: fit-children;
	vertical-align: bottom;
	flow-children: down;
}

.Row
{
	flow-children: right;
}

/* the value in bold, the maximum after a thin bar in a lighter weight, as "200 | 200" */
.Now
{
	font-family: var(--font);
	font-size: 30px;
	font-weight: bold;
	color: var(--text);
	text-shadow: 0px 1px 3px 1.0 #00000090;
}

.Sep
{
	width: 2px;
	height: 22px;
	vertical-align: bottom;
	margin: 0px 8px 7px 8px;
	background-color: var(--text);
	opacity: 0.5;
}

.Max
{
	font-family: var(--font);
	font-size: 22px;
	font-weight: normal;
	color: var(--text);
	opacity: 0.75;
	vertical-align: bottom;
	margin-bottom: 3px;
	text-shadow: 0px 1px 3px 1.0 #00000090;
}

