files.theme/citadel_hud_hero_shop.css:
/* Clean: the shop's window: the catalog page each tab opens, the category tabs down its left edge, the back
   button, the purchase prompt and the in-combat warning. The painted catalog pages become one flat dark
   plate: paper, logos, doodles, the "study guides" lettering and the tier boxes with their "Tier 1-4" titles
   are all one picture per tab (the tiers keep their price tags, which are labels). The paper tabs become flat
   blocks in their colour with the game's icons, the open one in full. What sits on the page (lists, item
   cards, filters, search) has theme files of its own (citadel_shop_*, citadel_ui_shop_filters). The backdrop,
   its red tint in combat and the hero model stay the game's. The main menu's item browser draws this layout
   too; it lives outside #Hud, so it keeps the game's look. */

#Hud Label
{
	font-family: var(--font);
}

/* The page, whatever the tab (the game paints a different one for each, and the filters view brown). */
#Hud #ShopModListsContainer
{
	background-image: none;
	background-color: #0B0F14E6;
	border-radius: 4px;
}

/* The category tabs: flat blocks in their colour (weapon, spirit, vitality; light for builds, recommended
   and all items) with the game's dark icon, instead of the paper shapes. The open tab (which the game
   still makes taller) in full, the others faded until the pointer is on them. */
#Hud #ShopNavigation .NavigationButton
{
	background-image: none;
	background-color: var(--text);
	border-radius: 4px 0px 0px 4px;
	opacity: 0.45;
}

#Hud #ShopNavigation #WeaponNav.NavigationButton
{
	background-color: #EC9719;
}

#Hud #ShopNavigation #TechNav.NavigationButton
{
	background-color: #CE90FF;
}

#Hud #ShopNavigation #ArmorNav.NavigationButton
{
	background-color: #7BBA1D;
}

#Hud #ShopNavigation .ShopNavigationTabBackground,
#Hud #ShopNavigation .ShopNavigationTabEdgeOverlay
{
	background-image: none;
}

#Hud #ShopNavigation .NavigationButton:hover
{
	opacity: 0.75;
}

/* After the hover rule, which it ties. */
#Hud .showingFavorites #FavoritesNav.NavigationButton,
#Hud .showingRecommendations #RecommendedNav.NavigationButton,
#Hud .showingAllItems #FilteredNav.NavigationButton,
#Hud .showingWeapon #WeaponNav.NavigationButton,
#Hud .showingTech #TechNav.NavigationButton,
#Hud .showingArmor #ArmorNav.NavigationButton
{
	opacity: 1;
}

/* "Esc Back", bottom left (#Shop: the build browser popup has a #BackButton too). */
#Hud #Shop #BackButton .FooterCommandLabel
{
	font-weight: bold;
	letter-spacing: 1px;
}

/* "Damage Warning" while you're in combat: red on a dark plate with a red edge, instead of a red glow. */
#Hud #InCombatAlert
{
	background-color: var(--plate-strong);
	border-left: 3px solid var(--danger);
	border-radius: 3px;
}

#Hud #InCombatAlert Label
{
	font-weight: bold;
	letter-spacing: 2px;
	color: var(--danger);
	text-shadow: none;
}

/* ...and the red frame around the screen, thinner and in Clean's red. Each item card has an #Outline too:
   this is the shop's own (a child of the shop). */
#Hud #CitadelHudHeroShop > #Outline
{
	border: 3px solid var(--danger);
}

/* "Enter to purchase <item>" (or to sell): a dark plate with an edge in the souls colour, red to sell,
   instead of the green-framed gradient and its wide shadow. */
#Hud #EnterPurchasePrompt
{
	background-color: #0B0F14E6;
	border: 0px solid #00000000;
	border-left: 3px solid var(--good);
	border-radius: 4px;
	box-shadow: none;
}

#Hud .EnterWillSell #EnterPurchasePrompt
{
	border-left: 3px solid var(--danger);
}

#Hud .EnterPurchaseLabel
{
	font-weight: bold;
	letter-spacing: 1px;
	text-shadow: none;
}

files.theme/citadel_hud_modifier_message.css:
/* Clean: the short messages about effects put on you (the caster's portrait, the ability's icon and a
   line of text), above the abilities. Each message becomes a dark plate with a thin edge, red for a
   debuff and white for a buff, instead of bare text with a red or black outline. */

#Hud Label
